INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5324cda3-d2f4-4903-a0cc-caa371b779a5', '遠山', '远山', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["隱隱隔千里，巍巍知幾重。","平時未能去，夢斷一聲鐘。"]', '["隐隐隔千里，巍巍知幾重。","平时未能去，梦斷一声鐘。"]', '诗', 'shi', '', NULL, '遠山 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9b80bd8-7452-4707-804d-37052e15f35d', '江樹', '江樹', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["終日衝奔浪，何年墜亂風。","謝公堪入詠，目極在雲中。"]', '["終日衝奔浪，何年墜亂风。","謝公堪入詠，目極在云中。"]', '诗', 'shi', '', NULL, '江樹 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1ad73ed-0422-41aa-a546-d474fe77ad76', '薔薇', '薔薇', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["萬卉春風度，繁花夏景長。","館娃人盡醉，西子始新妝。"]', '["万卉春风度，繁花夏景长。","館娃人尽醉，西子始新妝。"]', '诗', 'shi', '', NULL, '薔薇 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67315f65-c655-4657-a130-79083e9a1710', '梅雨', '梅雨', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["渾開又密望中迷，乳燕歸遲粉竹低。","撲地暗來飛野馬，舞風斜去散醯雞。","初從滴瀝妨琴榭，漸到潺湲繞藥畦。","少傍海邊飄泊處，中庭自有兩犁泥。"]', '["渾开又密望中迷，乳燕归遲粉竹低。","撲地暗来飞野马，舞风斜去散醯雞。","初從滴瀝妨琴榭，漸到潺湲繞藥畦。","少傍海邊飄泊处，中庭自有兩犁泥。"]', '诗', 'shi', '', NULL, '梅雨 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de71c0e-db4c-490e-9a46-60d16c6e3d06', '登途懷友人', '登途懷友人', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["日落野原秀，雨餘雲物閑。","清時正愁絕，高處正躋攀。","京洛遙天外，江河戰鼓間。","孤懷欲誰寄，應望塞鴻還。"]', '["日落野原秀，雨餘云物闲。","清时正愁絕，高处正躋攀。","京洛遙天外，江河戰鼓间。","孤懷欲誰寄，應望塞鴻還。"]', '诗', 'shi', '', NULL, '登途懷友人 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c92652ee-7b02-4711-b529-cd236ffcf699', '聞蟬', '闻蟬', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["夏在先催過，秋賒已被迎。","自應人不會，莫道物無情。","木葉縱未落，鬢絲還易生。","西風正相亂，休上夕陽城。"]', '["夏在先催過，秋賒已被迎。","自應人不會，莫道物無情。","木葉縱未落，鬢絲還易生。","西风正相亂，休上夕陽城。"]', '诗', 'shi', '', NULL, '聞蟬 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('840a4e36-23e9-4d3c-8ef8-2e931fbd0b65', '秋色', '秋色', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["染不成乾畫未銷，霏霏拂拂又迢迢。","曾從建業城邊路，蔓草寒煙鏁六朝。"]', '["染不成乾畫未銷，霏霏拂拂又迢迢。","曾從建業城邊路，蔓草寒煙鏁六朝。"]', '诗', 'shi', '', NULL, '秋色 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('256c3267-b5bd-4ee5-afdf-e5c635f0156b', '自諷', '自諷', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["本是滄洲把釣人，無端三署接清塵。","從來不解長流涕，也渡湘灕作逐臣。"]', '["本是滄洲把釣人，無端三署接清塵。","從来不解长流涕，也渡湘灕作逐臣。"]', '诗', 'shi', '', NULL, '自諷 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8f52307-eaa9-4187-a33a-08ad6448a3ee', '宿青雲驛', '宿青云驛', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["蒼黃負譴走商顏，保得微躬出武關。","今夜青雲驛前月，伴吟應到落西山。"]', '["蒼黄負譴走商顏，保得微躬出武关。","今夜青云驛前月，伴吟應到落西山。"]', '诗', 'shi', '', NULL, '宿青雲驛 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fa956bc-e4e4-4f6e-a05a-4ff9791a7071', '秋聞子規', '秋闻子規', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["年年春恨化冤魂，血染枝紅壓疊繁。","正是西風花落盡，不知何處認啼痕。"]', '["年年春恨化冤魂，血染枝紅壓叠繁。","正是西风花落尽，不知何处認啼痕。"]', '诗', 'shi', '', NULL, '秋聞子規 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f7f1795-8d5b-4155-86f3-c69edf9f1c44', '荆南席上聞歌', '荆南席上闻歌', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["迎愁歛黛一聲分，弔屈江邊日暮聞。","何事遏雲翻不定，自緣蹤跡愛行雲。"]', '["迎愁歛黛一声分，弔屈江邊日暮闻。","何事遏云翻不定，自緣蹤跡愛行云。"]', '诗', 'shi', '', NULL, '荆南席上聞歌 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f1bd48-e70c-44f1-a5a3-db0560d6fdfe', '武關', '武关', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["時來時去若循環，雙闔平雲謾鏁山。","祗道地教秦設險，不知天與漢爲關。","貪生莫作千年計，到了都成一夢閑。","爭得便如岩下水，從他興廢自潺潺。"]', '["时来时去若循环，雙闔平云謾鏁山。","祗道地教秦設險，不知天與漢爲关。","貪生莫作千年計，到了都成一梦闲。","爭得便如岩下水，從他兴廢自潺潺。"]', '诗', 'shi', '', NULL, '武關 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13853a21-9a33-4abe-8dda-7ba0b2c3b1b8', '月夕追事', '月夕追事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["曾聽豪家碧玉歌，雲牀冰簟落秋河。","月臨高閣簾無影，風過迴廊幕有波。","屈指盡隨雲雨散，滿頭贏得雪霜多。","此時空見清涼影，來伴蛩聲咽砌莎。"]', '["曾听豪家碧玉歌，云牀冰簟落秋河。","月臨高閣簾無影，风過迴廊幕有波。","屈指尽隨云雨散，满头贏得雪霜多。","此时空见清涼影，来伴蛩声咽砌莎。"]', '诗', 'shi', '', NULL, '月夕追事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe7f6888-5e55-45cf-83c0-c3c7bc0ff94b', '上陽宮辭', '上陽宮辞', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["苑路青青半是苔，翠華西去未知回。","景陽春漏無人報，太液秋波有雁來。","單影可堪明月照，紅顏無奈落花催。","誰能賦得長門事，不惜千金奉酒桮。"]', '["苑路青青半是苔，翠华西去未知回。","景陽春漏無人報，太液秋波有雁来。","單影可堪明月照，紅顏無奈落花催。","誰能賦得长门事，不惜千金奉酒桮。"]', '诗', 'shi', '', NULL, '上陽宮辭 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f609f2a2-22fe-4be2-9c32-5aadaa8bc2ef', '送于員外歸隱藍田', '送于員外归隐藍田', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["曾吟工部兩峰寒，今日星郎得挂冠。","吾道不行歸始是，世情如此住應難。","圍棋已訪生雲石，把釣先尋急雨灘。","若遇秦時雪髯客，紫芝兼可備朝餐。"]', '["曾吟工部兩峰寒，今日星郎得挂冠。","吾道不行归始是，世情如此住應难。","圍棋已訪生云石，把釣先尋急雨灘。","若遇秦时雪髯客，紫芝兼可備朝餐。"]', '诗', 'shi', '', NULL, '送于員外歸隱藍田 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc4dedc-1ff3-4895-8624-187266377cc0', '廢宅', '廢宅', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["風飄碧瓦雨摧垣，却有隣人與鏁門。","幾樹好花閑白晝，滿庭荒草易黃昏。","放魚池涸蛙爭聚，棲燕梁空雀自喧。","不獨淒涼眼前事，咸陽一火便成原。"]', '["风飄碧瓦雨摧垣，却有隣人與鏁门。","幾樹好花闲白晝，满庭荒草易黄昏。","放鱼池涸蛙爭聚，棲燕梁空雀自喧。","不独淒涼眼前事，咸陽一火便成原。"]', '诗', 'shi', '', NULL, '廢宅 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17b69912-19ef-4f95-8b46-ea2fd9eb3cb2', '湖州晚望', '湖州晚望', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["鼓角迎秋晚韻長，斷虹疎雨間微陽。","兩條溪水分頭碧，四面人家入骨涼。","獨鳥歸時雲鬬迥，殘蟬急處日爭忙。","他年若得壺中術，一簇汀洲盡貯將。"]', '["鼓角迎秋晚韻长，斷虹疎雨间微陽。","兩條溪水分头碧，四面人家入骨涼。","独鸟归时云鬬迥，殘蟬急处日爭忙。","他年若得壺中術，一簇汀洲尽貯將。"]', '诗', 'shi', '', NULL, '湖州晚望 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fad6799c-322c-4f85-973c-fbde93d57321', '宋玉宅', '宋玉宅', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["草白煙寒半野陂，臨江舊宅指遺基。","已懷湘浦招魂事，更憶高唐說夢時。","穿徑早曾聞客住，登牆豈復見人窺。","今朝送別還經此，吟斷當年幾許悲。"]', '["草白煙寒半野陂，臨江旧宅指遺基。","已懷湘浦招魂事，更憶高唐说梦时。","穿徑早曾闻客住，登牆豈复见人窺。","今朝送別還經此，吟斷當年幾許悲。"]', '诗', 'shi', '', NULL, '宋玉宅 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a53ceb2-0556-4393-ac13-39a21a520e26', '春晚書懷', '春晚书懷', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["落盡紅芳春意闌，綠蕪空鏁辟疆園。","嫦娥斷影霜輪冷，帝子無蹤淚竹繁。","未達東鄰還絕想，不勞南浦更銷魂。","晚來雖共殘鶯約，爭奈風淒又雨昏。"]', '["落尽紅芳春意闌，綠蕪空鏁辟疆园。","嫦娥斷影霜輪冷，帝子無蹤泪竹繁。","未達东鄰還絕想，不勞南浦更銷魂。","晚来雖共殘鶯約，爭奈风淒又雨昏。"]', '诗', 'shi', '', NULL, '春晚書懷 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de06c890-766d-4632-8c7f-30ae7d09b845', '寄楊侍郎', '寄楊侍郎', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["雲情鶴態莫誇慵，正上仙樓十二重。","吟逸易沈鳷鵲月，夢長先斷景陽鐘。","奇文已刻金書券，秘語看鐫玉檢封。","何事春來待歸隱，探知溪畔有風松。"]', '["云情鹤態莫誇慵，正上仙楼十二重。","吟逸易沈鳷鵲月，梦长先斷景陽鐘。","奇文已刻金书券，秘語看鐫玉檢封。","何事春来待归隐，探知溪畔有风松。"]', '诗', 'shi', '', NULL, '寄楊侍郎 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('743aa9cf-9b50-45e1-8deb-8403fa41c33e', '杏花', '杏花', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["粉薄紅輕揜歛羞，花中占斷得風流。","軟非因醉都無力，凝不成歌亦自愁。","獨照影時臨水畔，最含情處出牆頭。","裴回盡日難成別，更待黃昏對酒樓。"]', '["粉薄紅轻揜歛羞，花中占斷得风流。","軟非因醉都無力，凝不成歌亦自愁。","独照影时臨水畔，最含情处出牆头。","裴回尽日难成別，更待黄昏对酒楼。"]', '诗', 'shi', '', NULL, '杏花 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38ecba14-83f8-4047-98a1-9ea39ee58763', '憲丞裴公上洛退居有寄二首 一', '憲丞裴公上洛退居有寄二首 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["鴻在冥冥已自由，紫芝峰下更高秋。","拋來簪紱都如夢，泥著杯香不爲愁。","晚樹拂簷風脫翠，夜灘當戶月和流。","自嗟不得從公去，共上仙家十二樓。"]', '["鴻在冥冥已自由，紫芝峰下更高秋。","拋来簪紱都如梦，泥著杯香不爲愁。","晚樹拂簷风脫翠，夜灘當戶月和流。","自嗟不得從公去，共上仙家十二楼。"]', '诗', 'shi', '', NULL, '憲丞裴公上洛退居有寄二首 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a6bfe8f-4623-4652-9000-dcb35fe63649', '憲丞裴公上洛退居有寄二首 二', '憲丞裴公上洛退居有寄二首 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["瘦如仙鶴爽風篁，外却塵囂興緒長。","偶坐幾回沈皓月，閑吟是處到殘陽。","門前立使修書嬾，花下留賓壓酒忙。","目斷瓊林攀不得，一重丹水抵三湘。"]', '["瘦如仙鹤爽风篁，外却塵囂兴緒长。","偶坐幾回沈皓月，闲吟是处到殘陽。","门前立使修书嬾，花下留賓壓酒忙。","目斷瓊林攀不得，一重丹水抵三湘。"]', '诗', 'shi', '', NULL, '憲丞裴公上洛退居有寄二首 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eba4826d-a5da-4303-8623-1066ae4bd9a5', '叢祠', '叢祠', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["叢祠一炬照秦川，雨散雲飛二十年。","長路未歸萍逐水，舊居難問草平煙。","金鞍正伴桐鄉客，粉壁猶懷桂苑仙。","何必向來曾識面，拂塵看字也淒然。"]', '["叢祠一炬照秦川，雨散云飞二十年。","长路未归萍逐水，旧居难问草平煙。","金鞍正伴桐乡客，粉壁猶懷桂苑仙。","何必向来曾識面，拂塵看字也淒然。"]', '诗', 'shi', '', NULL, '叢祠 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aea6ea10-4541-40bd-a3d9-ff9e4338daf7', '分水嶺', '分水嶺', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["兩派潺湲不暫停，嶺頭長瀉別離情。","南隨去馬通巴棧，北逐歸人達渭城。","澄處好窺雙黛影，咽時堪寄斷腸聲。","紫溪舊隱還如此，清夜梁山月更明。"]', '["兩派潺湲不暫停，嶺头长瀉別離情。","南隨去马通巴棧，北逐归人達渭城。","澄处好窺雙黛影，咽时堪寄斷腸声。","紫溪旧隐還如此，清夜梁山月更明。"]', '诗', 'shi', '', NULL, '分水嶺 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f72a01d0-c57c-4d99-aa23-4c378f94b93a', '赴職西川過便橋書懷寄同年', '赴職西川過便橋书懷寄同年', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["平門橋下水東馳，萬里從軍一望時。","鄉思旋生芳草見，客愁何限夕陽知。","秦陵無樹煙猶鏁，漢苑空牆浪欲吹。","不是傷春愛回首，杏壇恩重馬遲遲。"]', '["平门橋下水东驰，万里從軍一望时。","乡思旋生芳草见，客愁何限夕陽知。","秦陵無樹煙猶鏁，漢苑空牆浪欲吹。","不是傷春愛回首，杏壇恩重马遲遲。"]', '诗', 'shi', '', NULL, '赴職西川過便橋書懷寄同年 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('811ed19b-b95a-44fb-974b-8b8f67c957f9', '太保中書令軍前新樓', '太保中书令軍前新楼', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["十二闌干壓錦城，半空人語落灘聲。","風流近接平津閣，氣色高含細柳營。","盡日捲簾江草綠，有時欹枕雪峰晴。","不知捧詔朝天後，誰此登臨看月明。"]', '["十二闌干壓錦城，半空人語落灘声。","风流近接平津閣，氣色高含細柳營。","尽日捲簾江草綠，有时欹枕雪峰晴。","不知捧詔朝天後，誰此登臨看月明。"]', '诗', 'shi', '', NULL, '太保中書令軍前新樓 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e7a1a13-7702-448b-a558-cef0e86df5dd', '玉女廟', '玉女廟', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["九清何日降仙霓，掩暎荒祠路欲迷。","愁黛不開山淺淺，離心長在草萋萋。","簷橫淥派王餘擲，窗褭紅枝杜宇啼。","若得洗頭盆置此，靚妝無復碧蓮西。"]', '["九清何日降仙霓，掩暎荒祠路欲迷。","愁黛不开山淺淺，離心长在草萋萋。","簷橫淥派王餘擲，窗褭紅枝杜宇啼。","若得洗头盆置此，靚妝無复碧蓮西。"]', '诗', 'shi', '', NULL, '玉女廟 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('145163c7-0397-48e6-84fe-b6a6c12a2eda', '坤維軍前寄江南弟兄', '坤維軍前寄江南弟兄', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["二年征戰劒山秋，家在松江白浪頭。","關月幾時乾客淚，戍煙終日起鄉愁。","未知遼堞何當下，轉覺燕臺不易酬。","獨羨一聲南去雁，滿天風雨到汀洲。"]', '["二年征戰劒山秋，家在松江白浪头。","关月幾时乾客泪，戍煙終日起乡愁。","未知遼堞何當下，轉覺燕台不易酬。","独羨一声南去雁，满天风雨到汀洲。"]', '诗', 'shi', '', NULL, '坤維軍前寄江南弟兄 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('295ad042-cebb-494f-88c0-da4e7f23a846', '滻水席上獻座主侍郎', '滻水席上獻座主侍郎', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["暖泉宮裏告虔回，略避紅塵小宴開。","落絮已隨流水去，啼鶯還傍夕陽來。","草能緣岸侵羅薦，花不容枝蘸玉杯。","莫訝諸生中獨醉，感恩傷別正難裁。"]', '["暖泉宮裏告虔回，略避紅塵小宴开。","落絮已隨流水去，啼鶯還傍夕陽来。","草能緣岸侵羅薦，花不容枝蘸玉杯。","莫訝諸生中独醉，感恩傷別正难裁。"]', '诗', 'shi', '', NULL, '滻水席上獻座主侍郎 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be50bb6-2714-4474-8256-d0f50b6c4147', '送知古上人', '送知古上人', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["昔年離別浙河東，多難相逢舊楚宮。","振錫纔尋三徑草，登船忽挂一帆風。","幾程村飯添盂白，何處山花照衲紅？","不似投荒憔悴客，滄浪無際問漁翁。"]', '["昔年離別浙河东，多难相逢旧楚宮。","振錫纔尋三徑草，登船忽挂一帆风。","幾程村飯添盂白，何处山花照衲紅？","不似投荒憔悴客，滄浪無際问漁翁。"]', '诗', 'shi', '', NULL, '送知古上人 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f55086ed-c307-43be-9a99-4616c35d88a9', '和座主尚書登布善寺樓', '和座主尚书登布善寺楼', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["往事何時不繫腸，更堪凝睇白雲鄉。","楚王城壘空秋色，羊祜江山祗暝光。","林下遠分南去馬，渡頭偏認北歸航。","誰知此日憑軒處，一筆工夫勝七襄。"]', '["往事何时不繫腸，更堪凝睇白云乡。","楚王城壘空秋色，羊祜江山祗暝光。","林下远分南去马，渡头偏認北归航。","誰知此日憑軒处，一笔工夫勝七襄。"]', '诗', 'shi', '', NULL, '和座主尚書登布善寺樓 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ef3566c-a526-412a-8716-12cd9fc0e5b5', '金橋感事', '金橋感事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["太行和雪疊晴空，二月春郊尚朔風。","飲馬早聞臨渭北，射鵰今欲過山東。","百年徒有伊川歎，五利寧無魏絳功。","日暮長亭正愁絕，哀笳一曲戍煙中。"]', '["太行和雪叠晴空，二月春郊尚朔风。","饮马早闻臨渭北，射鵰今欲過山东。","百年徒有伊川歎，五利寧無魏絳功。","日暮长亭正愁絕，哀笳一曲戍煙中。"]', '诗', 'shi', '', NULL, '金橋感事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f5cf40-96f7-46d8-ab57-0afe7b38d113', '蕭縣道中', '蕭縣道中', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["戍火三籠滯晚程，枯桑繫馬上寒城。","滿川落照無人過，卷地飛蓬有燒明。","楚客早聞歌鳳德，劉琨休更舞雞聲。","草堂舊隱終歸去，寄語巖猨莫曉驚。"]', '["戍火三籠滯晚程，枯桑繫马上寒城。","满川落照無人過，卷地飞蓬有燒明。","楚客早闻歌鳳德，劉琨休更舞雞声。","草堂旧隐終归去，寄語巖猨莫晓驚。"]', '诗', 'shi', '', NULL, '蕭縣道中 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6e48b56-b629-4f7c-9349-b31fdcc7c5f8', '題兖州泗河中石牀', '題兖州泗河中石牀', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一片苔牀水漱痕，何人清賞動乾坤。","謫仙醉後雲爲態，野客吟時月作魂。","光景不回波自遠，風流難問石無[言]。","邇來多少登臨客，千載誰將勝事論。"]', '["一片苔牀水漱痕，何人清賞动乾坤。","謫仙醉後云爲態，野客吟时月作魂。","光景不回波自远，风流难问石無[言]。","邇来多少登臨客，千載誰將勝事論。"]', '诗', 'shi', '', NULL, '題兖州泗河中石牀 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d37ffcf9-5285-4d74-883e-8ac79bab45ce', '禁直偶書', '禁直偶书', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["玉皇新復五城居，仙館詞臣在碧虛。","錦砌漸看翻芍藥，鏁窗還詠隔蟾蜍。","敢期林上靈烏語，貪草雲間彩鳳書。","爭奈滄洲頻入夢，白波無際落紅蕖。"]', '["玉皇新复五城居，仙館词臣在碧虛。","錦砌漸看翻芍藥，鏁窗還詠隔蟾蜍。","敢期林上靈烏語，貪草云间彩鳳书。","爭奈滄洲頻入梦，白波無際落紅蕖。"]', '诗', 'shi', '', NULL, '禁直偶書 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b23b7d0-b611-4e3c-b7af-74d129e91ee2', '送弟東歸', '送弟东归', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["偶持麟筆侍金閨，夢想三年在故溪。","祖竹定欺簷雪折，穉杉應拂棟雲齊。","謾勞筋力趨丹鳳，可有文詞詠碧雞。","此別更無閑事囑，北山高處謝猨啼。"]', '["偶持麟笔侍金閨，梦想三年在故溪。","祖竹定欺簷雪折，穉杉應拂棟云齊。","謾勞筋力趨丹鳳，可有文词詠碧雞。","此別更無闲事囑，北山高处謝猨啼。"]', '诗', 'shi', '', NULL, '送弟東歸 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83e643a1-daea-42fa-98ea-5fbfb6efb046', '和座主尚書春日郊居', '和座主尚书春日郊居', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["海燕初歸朔雁回，靜眠深揜百花臺。","春蔬已爲高僧掇，臘醞還因熟客開。","簷外暖絲兼絮墮，檻前輕浪帶鷗來。","謝公難避蒼生意，自古風流必上台。"]', '["海燕初归朔雁回，静眠深揜百花台。","春蔬已爲高僧掇，臘醞還因熟客开。","簷外暖絲兼絮墮，檻前轻浪带鷗来。","謝公难避蒼生意，自古风流必上台。"]', '诗', 'shi', '', NULL, '和座主尚書春日郊居 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('179a5d17-46f2-4e9d-b436-91de2246258c', '僧舍白牡丹二首 一', '僧舍白牡丹二首 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["膩若裁雲薄綴霜，春殘獨自殿羣芳。","梅妝向日霏霏暖，紈扇搖風閃閃光。","月魄照來空見影，露華凝後更多香。","天生潔白宜清淨，何必殷紅暎洞房。"]', '["膩若裁云薄綴霜，春殘独自殿羣芳。","梅妝向日霏霏暖，紈扇搖风閃閃光。","月魄照来空见影，露华凝後更多香。","天生潔白宜清淨，何必殷紅暎洞房。"]', '诗', 'shi', '', NULL, '僧舍白牡丹二首 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b9bca44-2754-47f0-a988-cd1f15396f63', '僧舍白牡丹二首 二', '僧舍白牡丹二首 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["侯家萬朵簇霞丹，若並霜林素豔難。","合影只應天際月，分香多是畹中蘭。","雖饒百卉爭先發，還在三春向後殘。","想得惠林憑此檻，肯將榮落意來看。"]', '["侯家万朵簇霞丹，若並霜林素豔难。","合影只應天際月，分香多是畹中蘭。","雖饒百卉爭先發，還在三春向後殘。","想得惠林憑此檻，肯將榮落意来看。"]', '诗', 'shi', '', NULL, '僧舍白牡丹二首 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d5e7d4-1dd4-4e0b-baac-7e1a50f5bf20', '八月十五夜禁直寄同僚', '八月十五夜禁直寄同僚', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["中秋月滿盡相尋，獨入非煙宿禁林。","曾恨人間千里隔，更堪天上九門深。","明涵太液魚龍定，靜鏁圓靈象緯沈。","目斷枚臯何處在，闌干十二憶登臨。"]', '["中秋月满尽相尋，独入非煙宿禁林。","曾恨人间千里隔，更堪天上九门深。","明涵太液鱼龙定，静鏁圓靈象緯沈。","目斷枚臯何处在，闌干十二憶登臨。"]', '诗', 'shi', '', NULL, '八月十五夜禁直寄同僚 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('319502e8-c7de-4bfb-ba4b-3d6a45f13e0a', '上巳日花下閑看', '上巳日花下闲看', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["十里香塵撲馬飛，碧蓮峰下踏青時。","雲鬟照水和花重，羅袖擡風惹絮遲。","可便無心邀娬媚，還應有淚憶袁熙。","如煙如夢爭尋得，溪柳回頭萬萬絲。"]', '["十里香塵撲马飞，碧蓮峰下踏青时。","云鬟照水和花重，羅袖擡风惹絮遲。","可便無心邀娬媚，還應有泪憶袁熙。","如煙如梦爭尋得，溪柳回头万万絲。"]', '诗', 'shi', '', NULL, '上巳日花下閑看 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a51d913c-3354-40d0-a470-7a7f9d082ba0', '禪院弈棋偶題', '禪院弈棋偶題', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["裛塵絲雨送微涼，偶出樊籠入道場。","半偈已能消萬事，一枰兼得了殘陽。","尋知世界都如夢，自喜身心甚不忙。","更約西風搖落後，醉來終日臥禪房。"]', '["裛塵絲雨送微涼，偶出樊籠入道場。","半偈已能消万事，一枰兼得了殘陽。","尋知世界都如梦，自喜身心甚不忙。","更約西风搖落後，醉来終日臥禪房。"]', '诗', 'shi', '', NULL, '禪院弈棋偶題 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52e28c9a-c24a-4abc-ab94-2e7ab8774a1f', '和張舍人', '和張舍人', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["玉女盆邊雪未銷，正多春事莫無憀。","杏花向日紅勻臉，雲帶環山白繫腰。","鶯囀樹頭欹枕聽，凍開泉眼杖藜挑。","陵遷谷變如須問，控鶴山人字子喬。"]', '["玉女盆邊雪未銷，正多春事莫無憀。","杏花向日紅勻臉，云带环山白繫腰。","鶯囀樹头欹枕听，凍开泉眼杖藜挑。","陵遷谷变如須问，控鹤山人字子喬。"]', '诗', 'shi', '', NULL, '和張舍人 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc9758b-5b1f-4c18-b661-bac9db4b81be', '送友赴闕', '送友赴闕', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["故人歸去指翔鸞，樂帶離聲可有歡。","驛路兩行秋吹急，渭波千疊夕陽寒。","空郊已歎周禾熟，舊苑應尋漢火殘。","遙羨從公無一事，探花先醉曲江干。"]', '["故人归去指翔鸾，乐带離声可有歡。","驛路兩行秋吹急，渭波千叠夕陽寒。","空郊已歎周禾熟，旧苑應尋漢火殘。","遙羨從公無一事，探花先醉曲江干。"]', '诗', 'shi', '', NULL, '送友赴闕 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ac1c0cb-3e3c-462b-ba4b-2a80fd7d1464', '過鄧城縣作', '過鄧城縣作', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["不用登臨足感傷，古來今往盡茫茫。","未知堯桀誰臧否，可便彭殤有短長。","楚壘萬重多故事，漢波千疊更殘陽。","到頭一切皆身外，只覺關身是醉鄉。"]', '["不用登臨足感傷，古来今往尽茫茫。","未知堯桀誰臧否，可便彭殤有短长。","楚壘万重多故事，漢波千叠更殘陽。","到头一切皆身外，只覺关身是醉乡。"]', '诗', 'shi', '', NULL, '過鄧城縣作 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05e80444-fbeb-4146-b858-86958752fd1e', '文德初聞車駕東遊', '文德初闻车駕东游', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["龍斾叢叢下劒門，還將瑞氣入中原。","鰲頭一蕩山雖沒，烏足重安日不昏。","晉客已知周禮在，秦人仍喜漢官存。","自憐閑坐漁磯石，萬級雲臺落夢魂。"]', '["龙斾叢叢下劒门，還將瑞氣入中原。","鰲头一蕩山雖沒，烏足重安日不昏。","晉客已知周禮在，秦人仍喜漢官存。","自怜闲坐漁磯石，万級云台落梦魂。"]', '诗', 'shi', '', NULL, '文德初聞車駕東遊 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e730162-0a4d-44e0-b17f-581ef798d05e', '子規', '子規', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["舉國繁華委逝川，羽毛飄蕩一年年。","他山叫處花成血，舊苑春來草似煙。","雨暗不離濃綠樹，月斜長弔欲明天。","湘江日暮聲淒切，愁殺行人歸去船。"]', '["舉国繁华委逝川，羽毛飄蕩一年年。","他山叫处花成血，旧苑春来草似煙。","雨暗不離濃綠樹，月斜长弔欲明天。","湘江日暮声淒切，愁殺行人归去船。"]', '诗', 'shi', '', NULL, '子規 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7150de2-4c5b-410a-a658-5a3ce099a431', '簡州歸降賀京兆公', '簡州归降賀京兆公', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["分棟山前曙色開，三千鐵騎簡州回。","雲間墮箭飛書去，風裏擎竿露布來。","古謂伐謀爲上策，今看靜勝自中台。","功名一似淮西事，只是元臣不姓裴。"]', '["分棟山前曙色开，三千鐵騎簡州回。","云间墮箭飞书去，风裏擎竿露布来。","古謂伐謀爲上策，今看静勝自中台。","功名一似淮西事，只是元臣不姓裴。"]', '诗', 'shi', '', NULL, '簡州歸降賀京兆公 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa3e0444-cb4e-4983-af17-6c2ecce0928d', '登漢州城樓', '登漢州城楼', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["雨餘秋色拂孤城，遠目凝時萬象清。","疊翠北來千嶂盡，漫流東去一江平。","從軍固有荆州樂，懷古能無峴首情。","欲下闌干一迴首，烏歸帆沒戍煙明。"]', '["雨餘秋色拂孤城，远目凝时万象清。","叠翠北来千嶂尽，漫流东去一江平。","從軍固有荆州乐，懷古能無峴首情。","欲下闌干一迴首，烏归帆沒戍煙明。"]', '诗', 'shi', '', NULL, '登漢州城樓 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7554ae0-8ee7-45a3-a0d3-5ab5ee07e304', '岐下寓居見槐花落因寄從事', '岐下寓居见槐花落因寄從事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["纔開便落不勝黃，覆著庭莎襯夕陽。","只共蟬催雙鬢老，可知人已十年忙。","曉窗須爲吟秋興，夜枕應教夢帝鄉。","蜀國馬卿看從獵，肯將閑事入淒涼。"]', '["纔开便落不勝黄，覆著庭莎襯夕陽。","只共蟬催雙鬢老，可知人已十年忙。","晓窗須爲吟秋兴，夜枕應教梦帝乡。","蜀国马卿看從獵，肯將闲事入淒涼。"]', '诗', 'shi', '', NULL, '岐下寓居見槐花落因寄從事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a85c285-1148-48e0-863f-624d5ba4277f', '和人有感', '和人有感', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["莫愁家住石城西，月墜星沈客到迷。","一院無人春寂寂，九原何處草萋萋。","香魂未散煙籠水，舞袖休翻柳拂堤。","蘭棹一移風雨急，流鶯千萬莫長啼。"]', '["莫愁家住石城西，月墜星沈客到迷。","一院無人春寂寂，九原何处草萋萋。","香魂未散煙籠水，舞袖休翻柳拂堤。","蘭棹一移风雨急，流鶯千万莫长啼。"]', '诗', 'shi', '', NULL, '和人有感 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af20d937-6fe6-4a07-89f4-9231e55e72fe', '春歸次金陵', '春归次金陵', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["春陰漠漠覆江城，南國歸橈趂晚程。","水上驛流初過雨，樹籠堤處不離鶯。","跡疎冠蓋兼無夢，地近鄉園自有情。","便被東風動離思，楊花千里雪中行。"]', '["春陰漠漠覆江城，南国归橈趂晚程。","水上驛流初過雨，樹籠堤处不離鶯。","跡疎冠蓋兼無梦，地近乡园自有情。","便被东风动離思，楊花千里雪中行。"]', '诗', 'shi', '', NULL, '春歸次金陵 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a44227a3-01e2-4ae6-81da-ef9957829fa2', '途中見杏花', '途中见杏花', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一枝紅豔出牆頭，牆外行人正獨愁。","長得看來猶有恨，可堪逢處更難留。","林空色暝鶯先到，春淺香寒蝶未遊。","更憶帝鄉千萬樹，澹煙籠日暗神州。"]', '["一枝紅豔出牆头，牆外行人正独愁。","长得看来猶有恨，可堪逢处更难留。","林空色暝鶯先到，春淺香寒蝶未游。","更憶帝乡千万樹，澹煙籠日暗神州。"]', '诗', 'shi', '', NULL, '途中見杏花 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45e9a714-559b-4b9c-8f15-7e0bb6200ef7', '秋日經別墅', '秋日經別墅', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["別墅蕭條海上村，偶期蘭菊與琴尊。","簷橫碧嶂秋光近，樹帶閑潮晚色昏。","幸有白雲眠楚客，不勞芳草思王孫。","北山移去前文在，無復教人歎曉猨。"]', '["別墅蕭條海上村，偶期蘭菊與琴尊。","簷橫碧嶂秋光近，樹带闲潮晚色昏。","幸有白云眠楚客，不勞芳草思王孫。","北山移去前文在，無复教人歎晓猨。"]', '诗', 'shi', '', NULL, '秋日經別墅 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde3ddab-b6aa-4cce-99de-e600b9e82746', '紅葉', '紅葉', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["露染霜乾片片輕，斜陽照處轉烘明。","和煙飄落九秋色，隨浪汎將千里情。","幾夜月中藏鳥影，誰家庭際伴蛩聲。","一時衰颯無多恨，看着清風綵剪成。"]', '["露染霜乾片片轻，斜陽照处轉烘明。","和煙飄落九秋色，隨浪汎將千里情。","幾夜月中藏鸟影，誰家庭際伴蛩声。","一时衰颯無多恨，看着清风綵剪成。"]', '诗', 'shi', '', NULL, '紅葉 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff60d5f6-007b-4134-9a6b-84a0a9e2fdc0', '離霅溪感事獻鄭員外', '離霅溪感事獻鄭員外', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["足恨饒悲不自由，萍無根蒂水長流。","庾公明月吟連曙，謝守青山看入秋。","一飯意專堪便死，千金諾在轉難酬。","雲沈鳥去回頭否，平子才多好賦愁。"]', '["足恨饒悲不自由，萍無根蒂水长流。","庾公明月吟連曙，謝守青山看入秋。","一飯意專堪便死，千金諾在轉难酬。","云沈鸟去回头否，平子才多好賦愁。"]', '诗', 'shi', '', NULL, '離霅溪感事獻鄭員外 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c4282b1-f53e-43ed-8972-fb8dbe67e7d8', '岐州安西門', '岐州安西门', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["安西門外徹安西，一百年前斷鼓鼙。","犬解人歌曾入唱，馬稱龍子幾來嘶。","自從遼水煙塵起，更到塗山道路迷。","今日登臨須下淚，行人無個草萋萋。"]', '["安西门外徹安西，一百年前斷鼓鼙。","犬解人歌曾入唱，马稱龙子幾来嘶。","自從遼水煙塵起，更到塗山道路迷。","今日登臨須下泪，行人無個草萋萋。"]', '诗', 'shi', '', NULL, '岐州安西門 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2df80a71-e7b1-4be7-87be-a8d0daa9797b', '關西驛亭即事', '关西驛亭即事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["晚霞零落雨初收，關上危闌獨悵留。","千里好春聊極目，五陵無事莫回頭。","山猶帶雪霏霏恨，柳未禁寒冉冉愁。","直是無情也腸斷，鳥歸帆沒水空流。"]', '["晚霞零落雨初收，关上危闌独悵留。","千里好春聊極目，五陵無事莫回头。","山猶带雪霏霏恨，柳未禁寒冉冉愁。","直是無情也腸斷，鸟归帆沒水空流。"]', '诗', 'shi', '', NULL, '關西驛亭即事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6710d655-c2ca-4316-9888-50a036b1a1eb', '望嵩山', '望嵩山', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["三十六峰危似冠，晴樓百尺獨登看。","高凌鳥外青冥窄，翠落人間白晝寒。","不覺衡陽遮雁過，如何鍾阜鬬龍盤。","始知萬歲聲長在，只待東巡動玉鸞。"]', '["三十六峰危似冠，晴楼百尺独登看。","高凌鸟外青冥窄，翠落人间白晝寒。","不覺衡陽遮雁過，如何鍾阜鬬龙盤。","始知万歲声长在，只待东巡动玉鸾。"]', '诗', 'shi', '', NULL, '望嵩山 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90a1e0e1-aabf-4ba0-8e96-15df37579aca', '題湖城縣西道中槐樹', '題湖城縣西道中槐樹', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["零落攲斜此路中，盛時曾識太平風。","曉迷天仗歸春苑，暮送鸞旗指洛宮。","一自煙塵生薊北，更無消息幸關東。","而今只有孤根在，鳥啄蟲穿沒亂蓬。"]', '["零落攲斜此路中，盛时曾識太平风。","晓迷天仗归春苑，暮送鸾旗指洛宮。","一自煙塵生薊北，更無消息幸关东。","而今只有孤根在，鸟啄蟲穿沒亂蓬。"]', '诗', 'shi', '', NULL, '題湖城縣西道中槐樹 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24152f34-8cc6-4582-94c4-36d77e053b2b', '東歸次瀛上', '东归次瀛上', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["煖煙輕淡草霏霏，一片晴山襯夕暉。","水露淺沙無客泛，樹連疎苑有鶯飛。","自從身與滄浪別，長被春教寂寞歸。","回首青門不知處，向人楊柳莫依依。"]', '["煖煙轻淡草霏霏，一片晴山襯夕暉。","水露淺沙無客泛，樹連疎苑有鶯飞。","自從身與滄浪別，长被春教寂寞归。","回首青门不知处，向人楊柳莫依依。"]', '诗', 'shi', '', NULL, '東歸次瀛上 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e349c048-6b35-4a24-9ec7-c71f9db72a34', '偶書', '偶书', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["青牛關畔寄孤村，山當屏風石當門。","芳樹綠陰連蔽芾，長河飛浪接崑崙。","苔田綠後蛙爭聚，麥壠黃時雀更喧。","只此無心便無事，避人何必武陵源。"]', '["青牛关畔寄孤村，山當屏风石當门。","芳樹綠陰連蔽芾，长河飞浪接崑崙。","苔田綠後蛙爭聚，麦壠黄时雀更喧。","只此無心便無事，避人何必武陵源。"]', '诗', 'shi', '', NULL, '偶書 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1b2d36c-3df3-4185-a0ec-4d5cd886846e', '得京中親友書訝久無音耗以詩代謝', '得京中親友书訝久無音耗以诗代謝', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["退閑何事不忘機，況限溪雲靜掩扉。","馬頰浪高魚去少，雞鳴關險雁來稀。","無才敢更期連茹，有意兼思學採薇。","珍重故人知我者，九霄休復寄音徽。"]', '["退闲何事不忘機，況限溪云静掩扉。","马頰浪高鱼去少，雞鳴关險雁来稀。","無才敢更期連茹，有意兼思学採薇。","珍重故人知我者，九霄休复寄音徽。"]', '诗', 'shi', '', NULL, '得京中親友書訝久無音耗以詩代謝 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4016e76-a02e-4f8b-93bb-aa84c42fd1c5', '即事', '即事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["抵鵲山前雲掩扉，更甘終老脫朝衣。","曉窺青鏡千峰入，暮倚長松獨鶴歸。","雲裏引來泉脉細，雨中移得藥苗肥。","何須一筯鱸魚膾，始挂孤帆問釣磯。"]', '["抵鵲山前云掩扉，更甘終老脫朝衣。","晓窺青镜千峰入，暮倚长松独鹤归。","云裏引来泉脉細，雨中移得藥苗肥。","何須一筯鱸鱼膾，始挂孤帆问釣磯。"]', '诗', 'shi', '', NULL, '即事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1144758b-1f67-4cb9-bad8-d3eddb0e7ff3', '病中宜茯苓寄李諫議', '病中宜茯苓寄李諫議', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["千年茯菟帶龍鱗，太華峰頭得最珍。","金鼎曉煎雲漾粉，玉甌寒貯露含津。","南宮已借徵詩客，內署今還託諫臣。","飛檄愈風知妙手，也須分藥救漳濱。"]', '["千年茯菟带龙鱗，太华峰头得最珍。","金鼎晓煎云漾粉，玉甌寒貯露含津。","南宮已借徵诗客，內署今還託諫臣。","飞檄愈风知妙手，也須分藥救漳濱。"]', '诗', 'shi', '', NULL, '病中宜茯苓寄李諫議 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('761ea005-9b29-43fa-a0d8-e2adf7c631f0', '槎', '槎', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["浪痕龍跡老敧危，流落何時別故枝。","歲月空教苔蘚積，芳菲長倩薜蘿知。","有文在朽人難識，無蠹藏心鳥莫窺。","家近滄浪從汎去，碧天消息不參差。"]', '["浪痕龙跡老敧危，流落何时別故枝。","歲月空教苔蘚積，芳菲长倩薜蘿知。","有文在朽人难識，無蠹藏心鸟莫窺。","家近滄浪從汎去，碧天消息不參差。"]', '诗', 'shi', '', NULL, '槎 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05d329e9-444b-4718-b3a9-72120f52e991', '汴上觀', '汴上观', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["九曲河冰半段來，嚴霜結出勁風裁。","非時已認蟬飄翼，到海須憂蚌失胎。","千里風清聞戛玉，幾人東下憶奔雷。","殷勤莫礙星槎路，從看天津弄杼回。"]', '["九曲河冰半段来，嚴霜結出勁风裁。","非时已認蟬飄翼，到海須憂蚌失胎。","千里风清闻戛玉，幾人东下憶奔雷。","殷勤莫礙星槎路，從看天津弄杼回。"]', '诗', 'shi', '', NULL, '汴上觀 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe955445-1f9e-46ba-b564-0bc82599010d', '閑居有作', '闲居有作', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["依依芳樹拂簷平，繞竹清流浸骨清。","愛弄綠苔魚自躍，慣偷紅果鳥無聲。","踏青堤上煙多綠，拾翠江邊月更明。","只此超然長往是，幾人能遂鑄金成。"]', '["依依芳樹拂簷平，繞竹清流浸骨清。","愛弄綠苔鱼自躍，慣偷紅果鸟無声。","踏青堤上煙多綠，拾翠江邊月更明。","只此超然长往是，幾人能遂鑄金成。"]', '诗', 'shi', '', NULL, '閑居有作 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6fcf9cc-796f-4b64-a4da-3016036037b0', '離岐下題西湖', '離岐下題西湖', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["送夏迎秋幾醉來，不堪行色被蟬催。","身隨渭水看歸遠，夢挂秦雲約自迴。","雨細若爲拋釣艇，月明誰復上歌臺。","千波萬浪西風急，更爲紅蕖把一桮。"]', '["送夏迎秋幾醉来，不堪行色被蟬催。","身隨渭水看归远，梦挂秦云約自迴。","雨細若爲拋釣艇，月明誰复上歌台。","千波万浪西风急，更爲紅蕖把一桮。"]', '诗', 'shi', '', NULL, '離岐下題西湖 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c314358-db4b-42a5-bb0d-455582751107', '岐陽蒙相國對宅因抒懷投獻', '岐陽蒙相国对宅因抒懷投獻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["風有危亭月有臺，平津閣畔好裴回。","雖非宋玉誅茅至，且學王家種竹來。","已得靜居從馬歇，不堪行色被蟬催。","故園蘭菊三千里，旅夢方應校嬾迴。"]', '["风有危亭月有台，平津閣畔好裴回。","雖非宋玉誅茅至，且学王家種竹来。","已得静居從马歇，不堪行色被蟬催。","故园蘭菊三千里，旅梦方應校嬾迴。"]', '诗', 'shi', '', NULL, '岐陽蒙相國對宅因抒懷投獻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('881b755e-5d6b-4e12-a99a-c9e1f675fb38', '晚泊松江', '晚泊松江', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["落日停橈古渡邊，古今蹤跡一蒼然。","平沙盡處雲藏樹，遠吹收來水定天。","正困東西千里路，可憐瀟灑五湖船。","如何不及前賢事，却謝鱸魚在洛川。"]', '["落日停橈古渡邊，古今蹤跡一蒼然。","平沙尽处云藏樹，远吹收来水定天。","正困东西千里路，可怜瀟灑五湖船。","如何不及前賢事，却謝鱸鱼在洛川。"]', '诗', 'shi', '', NULL, '晚泊松江 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('651f432d-3ce8-49ae-9fe0-cf68df0778d1', '過澠池書事', '過澠池书事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["澠池城郭半遺基，無限春愁挂落暉。","柳渡風輕花浪綠，麥田煙暖錦雞飛。","相如忠烈千秋斷，二主英雄一夢歸。","莫道新亭人對泣，異鄉殊代也霑衣。"]', '["澠池城郭半遺基，無限春愁挂落暉。","柳渡风轻花浪綠，麦田煙暖錦雞飞。","相如忠烈千秋斷，二主英雄一梦归。","莫道新亭人对泣，異乡殊代也霑衣。"]', '诗', 'shi', '', NULL, '過澠池書事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1fb1d49-c8b7-4c83-9fb2-9e0095d1ee71', '富春', '富春', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["水送山迎入富春，一川如畫晚晴新。","雲低遠渡帆來重，潮落寒沙鳥下頻。","未必柳間無謝客，也應花裏有秦人。","嚴光萬古清風在，不敢停橈更問津。"]', '["水送山迎入富春，一川如畫晚晴新。","云低远渡帆来重，潮落寒沙鸟下頻。","未必柳间無謝客，也應花裏有秦人。","嚴光万古清风在，不敢停橈更问津。"]', '诗', 'shi', '', NULL, '富春 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ada8699-d003-418a-8d52-f9e5fc1f6051', '高侍御話及皮博士池中白蓮因成一章寄博士兼奉呈', '高侍御話及皮博士池中白蓮因成一章寄博士兼奉呈', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["白玉花開綠錦池，風流御史報人知。","看來應是雲中墮，偷去須從月下移。","已被亂蟬催晼晚，更禁涼雨動䙰褷。","習家秋色堪圖畫，只欠山公倒接䍦。"]', '["白玉花开綠錦池，风流御史報人知。","看来應是云中墮，偷去須從月下移。","已被亂蟬催晼晚，更禁涼雨动䙰褷。","習家秋色堪圖畫，只欠山公倒接䍦。"]', '诗', 'shi', '', NULL, '高侍御話及皮博士池中白蓮因成一章寄博士兼奉呈 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9845de4b-778d-45b1-b7b7-c1ffdde83f9a', '憶猿', '憶猿', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["翠微雲歛日沈空，叫徹青冥怨不窮。","連臂影垂溪色裏，斷腸聲盡月明中。","靜含煙峽淒淒雨，高弄霜天嫋嫋風。","猶有北山歸意在，少驚佳樹近房櫳。"]', '["翠微云歛日沈空，叫徹青冥怨不窮。","連臂影垂溪色裏，斷腸声尽月明中。","静含煙峽淒淒雨，高弄霜天嫋嫋风。","猶有北山归意在，少驚佳樹近房櫳。"]', '诗', 'shi', '', NULL, '憶猿 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('411de517-cc82-4b5e-9ab2-5a19ec687e44', '紅樹', '紅樹', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一聲南雁已先紅，神女霜飛葉葉同。","自是孤根非暖地，莫驚他木耐秋風。","暖煙散去陰全薄，明月臨來影半空。","長憶洞庭千萬樹，照山橫浦夕陽中。"]', '["一声南雁已先紅，神女霜飞葉葉同。","自是孤根非暖地，莫驚他木耐秋风。","暖煙散去陰全薄，明月臨来影半空。","长憶洞庭千万樹，照山橫浦夕陽中。"]', '诗', 'shi', '', NULL, '紅樹 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43e88407-a03e-4d5c-b1ca-1d6996ca3969', '新雁', '新雁', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["湘浦波春始北歸，玉關搖落又南飛。","數聲飄去和秋色，一字橫來背晚暉。","紫閣高翻雲羃羃，灞川低渡雨微微。","莫從思婦臺邊過，未得征人萬里衣。"]', '["湘浦波春始北归，玉关搖落又南飞。","數声飄去和秋色，一字橫来背晚暉。","紫閣高翻云羃羃，灞川低渡雨微微。","莫從思婦台邊過，未得征人万里衣。"]', '诗', 'shi', '', NULL, '新雁 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5aa93f-8fb0-40eb-9c58-04925ef42c85', '海上秋懷', '海上秋懷', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["辭無珪組隱無才，門向潮頭過處開。","幾度黃昏逢罔象，有時紅旭見蓬萊。","磧連荒戍頻頻火，天絕纖雲往往雷。","昨夜秋風已搖落，那堪更上望鄉臺。"]', '["辞無珪組隐無才，门向潮头過处开。","幾度黄昏逢罔象，有时紅旭见蓬萊。","磧連荒戍頻頻火，天絕纖云往往雷。","昨夜秋风已搖落，那堪更上望乡台。"]', '诗', 'shi', '', NULL, '海上秋懷 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e50eecbd-56d2-40ed-8c4d-fb47ff027f1e', '憶山泉', '憶山泉', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["穿雲落石細湔湔，盡日疑聞弄管弦。","千仞灑來寒碎玉，一泓深去碧涵天。","煙迷葉亂尋難見，月好風清聽不眠。","春雨正多歸未得，只應流恨更潺湲。"]', '["穿云落石細湔湔，尽日疑闻弄管弦。","千仞灑来寒碎玉，一泓深去碧涵天。","煙迷葉亂尋难见，月好风清听不眠。","春雨正多归未得，只應流恨更潺湲。"]', '诗', 'shi', '', NULL, '憶山泉 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b302b0d9-94a6-45ab-9d68-1350fa03b3da', '東歸望華山', '东归望华山', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["碧蓮重疊在青冥，落日垂鞭緩客程。","不奈春煙籠暗澹，可堪秋雨洗分明。","南邊已放三千馬，北面猶標百二城。","只怕仙人撫高掌，年年相見是空行。"]', '["碧蓮重叠在青冥，落日垂鞭緩客程。","不奈春煙籠暗澹，可堪秋雨洗分明。","南邊已放三千马，北面猶標百二城。","只怕仙人撫高掌，年年相见是空行。"]', '诗', 'shi', '', NULL, '東歸望華山 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44189244-22ff-4edb-b651-5d089dc0234c', '遊華州飛泉亭', '游华州飞泉亭', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["走馬街南百畝池，碧蓮花影倒參差。","偶同人去紅塵外，正值僧歸落照時。","萬事已爲春棄置，百憂須賴酒醫治。","殷勤待取前峰月，更倚闌干弄釣絲。"]', '["走马街南百畝池，碧蓮花影倒參差。","偶同人去紅塵外，正值僧归落照时。","万事已爲春棄置，百憂須賴酒醫治。","殷勤待取前峰月，更倚闌干弄釣絲。"]', '诗', 'shi', '', NULL, '遊華州飛泉亭 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7524a652-842f-4083-80f6-17a580bbfa18', '池上雙鳧二首 一', '池上雙鳧二首 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["碧池悠漾小鳧雛，兩兩依依秪自娛。","釣艇忽移還散去，寒鴟有意即相呼。","可憐翡翠歸雲髻，莫羨鴛鴦入畫圖。","幸是羽毛無取處，一生安穩老菰蒲。"]', '["碧池悠漾小鳧雛，兩兩依依秪自娛。","釣艇忽移還散去，寒鴟有意即相呼。","可怜翡翠归云髻，莫羨鴛鴦入畫圖。","幸是羽毛無取处，一生安穩老菰蒲。"]', '诗', 'shi', '', NULL, '池上雙鳧二首 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdeb8466-ed1f-4785-8168-23d964d60fd0', '池上雙鳧二首 二', '池上雙鳧二首 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["雙鳧狎得傍池臺，戲藻銜蒲遠又回。","敢爲稻粱凌險去，幸無鷹隼觸波來。","萬絲春雨眠時亂，一片濃萍浴處開。","不在籠欄夜仍好，月汀星沼剩裴回。"]', '["雙鳧狎得傍池台，戲藻銜蒲远又回。","敢爲稻粱凌險去，幸無鷹隼觸波来。","万絲春雨眠时亂，一片濃萍浴处开。","不在籠欄夜仍好，月汀星沼剩裴回。"]', '诗', 'shi', '', NULL, '池上雙鳧二首 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6819c5a-cece-4e07-a998-9513c2c2851d', '葉落', '葉落', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["紅影飄來翠影微，一辭林表不知歸。","伴愁無色煙猶在，替恨成啼露未晞。","若逐水流應萬里，莫因風起便孤飛。","楚郊千樹秋聲急，日暮紛紛惹客衣。"]', '["紅影飄来翠影微，一辞林表不知归。","伴愁無色煙猶在，替恨成啼露未晞。","若逐水流應万里，莫因风起便孤飞。","楚郊千樹秋声急，日暮紛紛惹客衣。"]', '诗', 'shi', '', NULL, '葉落 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83b8102d-d1f4-405f-9775-f45730ec96f2', '和皮博士赴上京觀中修靈齋贈威儀尊師兼見寄', '和皮博士赴上京观中修靈斋贈威儀尊師兼见寄', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["霓結雙旌羽綴裙，七星壇上拜元君。","精誠有爲天應感，章奏無私鬼怕聞。","鶴馭已從煙際下，鳳膏還向月中焚。","白雲鄉路看看到，好駐流年翊聖文。"]', '["霓結雙旌羽綴裙，七星壇上拜元君。","精誠有爲天應感，章奏無私鬼怕闻。","鹤馭已從煙際下，鳳膏還向月中焚。","白云乡路看看到，好駐流年翊聖文。"]', '诗', 'shi', '', NULL, '和皮博士赴上京觀中修靈齋贈威儀尊師兼見寄 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fd56c8a-8487-4f05-92f9-64f4154e1c3a', '春雨', '春雨', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["霏霏漠漠暗和春，羃翠凝紅色更新。","寒入膩裘濃曉睡，細隨油壁靜香塵。","連雲似織休迷雁，帶柳如啼好贈人。","別有空堦寂寥事，綠苔狼籍落花頻。"]', '["霏霏漠漠暗和春，羃翠凝紅色更新。","寒入膩裘濃晓睡，細隨油壁静香塵。","連云似织休迷雁，带柳如啼好贈人。","別有空堦寂寥事，綠苔狼籍落花頻。"]', '诗', 'shi', '', NULL, '春雨 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb5532f5-1b8e-4d2f-b12a-d4643e45d304', '秋池', '秋池', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["冷涵秋水碧溶溶，一片澄明見底空。","有日晴來雲襯白，幾時吹落葉浮紅。","香啼蓼穗娟娟露，乾動蓮莖淅淅風。","凌曉無端照衰髮，便悲霜雪鏡光中。"]', '["冷涵秋水碧溶溶，一片澄明见底空。","有日晴来云襯白，幾时吹落葉浮紅。","香啼蓼穗娟娟露，乾动蓮莖淅淅风。","凌晓無端照衰髮，便悲霜雪镜光中。"]', '诗', 'shi', '', NULL, '秋池 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52a5e7ce-e78e-4a34-801c-25bef82f469b', '首陽山', '首陽山', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["首陽山枕黃河水，上有兩人曾餓死。","不同天下人爲非，兄弟相看自爲是。","遂令萬古識君心，爲臣貴義不貴身。","精靈長在白雲裏，應笑隨時飽死人。"]', '["首陽山枕黄河水，上有兩人曾餓死。","不同天下人爲非，兄弟相看自爲是。","遂令万古識君心，爲臣貴義不貴身。","精靈长在白云裏，應笑隨时飽死人。"]', '诗', 'shi', '', NULL, '首陽山 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eb6be1f-ca76-4092-89ab-d47677e6abd7', '太湖石歌', '太湖石歌', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["洞庭山下湖波碧，波中萬古生幽石。","鐵索千尋取得來，奇形怪狀誰能識。","初疑朝家正人立，又如戰士方狙擊。","又如防風死後骨，又如於菟活時額。","又如成人楓，又如害癭柏。","雨過上停泓，風來中有隙。","想得沈潛水府時，興雲出雨蟠蛟螭。","今來硉矹林庭上，長恐忽然生白浪。","用時應不稱媧皇，將去也堪隨博望。","噫嘻爾石好憑依，幸有方池幷釣磯。","小山叢桂且爲伴，鍾阜白雲長自歸。","何必豪家甲第裏，玉闌干畔爭光輝。","一朝荆棘忽流落，何異綺羅雲雨飛。"]', '["洞庭山下湖波碧，波中万古生幽石。","鐵索千尋取得来，奇形怪狀誰能識。","初疑朝家正人立，又如戰士方狙擊。","又如防风死後骨，又如於菟活时額。","又如成人楓，又如害癭柏。","雨過上停泓，风来中有隙。","想得沈潛水府时，兴云出雨蟠蛟螭。","今来硉矹林庭上，长恐忽然生白浪。","用时應不稱媧皇，將去也堪隨博望。","噫嘻爾石好憑依，幸有方池幷釣磯。","小山叢桂且爲伴，鍾阜白云长自归。","何必豪家甲第裏，玉闌干畔爭光輝。","一朝荆棘忽流落，何異綺羅云雨飞。"]', '诗', 'shi', '', NULL, '太湖石歌 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1e923ff-5671-438f-8697-08ad1d691fe3', '贈方干處士歌', '贈方干处士歌', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["把筆盡爲詩，何人敵夫子。","句滿天下口，名聒天下耳。","不識朝，不識市。","曠逍遙，閑徙倚。","一桮酒，無萬事。","一葉舟，無千里。","衣裳白雲，坐臥流水。","霜落風高忽相憶，惠然見過留一夕。","一夕聽吟十數篇，水榭林蘿爲岑寂。","拂旦舍我亦不辭，攜筇徑去隨所適。","隨所適，無處覓。","雲半片，鶴一隻。"]', '["把笔尽爲诗，何人敵夫子。","句满天下口，名聒天下耳。","不識朝，不識市。","曠逍遙，闲徙倚。","一桮酒，無万事。","一葉舟，無千里。","衣裳白云，坐臥流水。","霜落风高忽相憶，惠然见過留一夕。","一夕听吟十數篇，水榭林蘿爲岑寂。","拂旦舍我亦不辞，携筇徑去隨所適。","隨所適，無处覓。","云半片，鹤一隻。"]', '诗', 'shi', '', NULL, '贈方干處士歌 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0ecee39-0568-4b54-ab75-249bdc3fab1e', '李周彈箏歌', '李周彈箏歌', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["古人云：絲不如竹，竹不如肉。","乃知此語未必然，李周彈箏聽不足。","聞君七歲八歲時，五音六律皆生知。","就中十三弦最妙，應宮出入年方少。","青騘慣走長楸日，幾度承恩蒙急召。","一字雁行斜御筵，鏘金戛羽凌非煙。","始似五更殘月裏，淒淒切切清露蟬。","又如石罅堆葉下，泠泠瀝瀝蒼崖泉。","鴻門玉斗初向地，織女金梭飛上天。","有時上苑繁花發，有時太液秋波闊。","當頭獨坐摐一聲，滿座好風生拂拂。","天顏開，聖心悅。","紫金白珠霑賜物，出來無暇更還家。","且上青樓醉明月，年將六十藝轉精。","自寫梨園新曲聲，近來一事還惆悵。","故里春荒煙草平，供奉供奉且聽語。","自昔興衰看樂府，秪如伊州與梁州。","盡是太平時歌舞，旦夕君王繼此聲，不要停弦淚如雨。"]', '["古人云：絲不如竹，竹不如肉。","乃知此語未必然，李周彈箏听不足。","闻君七歲八歲时，五音六律皆生知。","就中十三弦最妙，應宮出入年方少。","青騘慣走长楸日，幾度承恩蒙急召。","一字雁行斜御筵，鏘金戛羽凌非煙。","始似五更殘月裏，淒淒切切清露蟬。","又如石罅堆葉下，泠泠瀝瀝蒼崖泉。","鴻门玉斗初向地，织女金梭飞上天。","有时上苑繁花發，有时太液秋波闊。","當头独坐摐一声，满座好风生拂拂。","天顏开，聖心悅。","紫金白珠霑賜物，出来無暇更還家。","且上青楼醉明月，年將六十藝轉精。","自寫梨园新曲声，近来一事還惆悵。","故里春荒煙草平，供奉供奉且听語。","自昔兴衰看乐府，秪如伊州與梁州。","尽是太平时歌舞，旦夕君王繼此声，不要停弦泪如雨。"]', '诗', 'shi', '', NULL, '李周彈箏歌 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f92f296d-2f5b-483f-ae59-5be06c526258', '贈{巩/言}光上人草書歌', '贈{巩/言}光上人草书歌', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["篆書樸，隸書俗，草聖貴在無羈束。","江南有僧名{巩/言}光，紫毫一管能顚狂。","人家好壁試揮拂，瞬目已流三五行。","摘如鉤，挑如撥。","斜如掌，迴如斡。","又如夏禹鏁淮神，波底出來手正拔。","又如朱亥鎚晉鄙，袖中擡起腕欲脫。","有時軟縈盈，一穗秋雲曳空闊。","有時瘦巉岩，百尺枯松露槎枿。","忽然飛動更驚人，一聲霹靂龍虵活。","稽山賀老昔所傳，又聞能者惟張顚。","上人致功應不下，其奈飄飄滄海邊。","可中一入天子國，絡素裁縑灑毫墨。","不繫知之與不知，須言一字千金值。"]', '["篆书樸，隸书俗，草聖貴在無羈束。","江南有僧名{巩/言}光，紫毫一管能顚狂。","人家好壁試揮拂，瞬目已流三五行。","摘如鉤，挑如撥。","斜如掌，迴如斡。","又如夏禹鏁淮神，波底出来手正拔。","又如朱亥鎚晉鄙，袖中擡起腕欲脫。","有时軟縈盈，一穗秋云曳空闊。","有时瘦巉岩，百尺枯松露槎枿。","忽然飞动更驚人，一声霹靂龙虵活。","稽山賀老昔所傳，又闻能者惟張顚。","上人致功應不下，其奈飄飄滄海邊。","可中一入天子国，絡素裁縑灑毫墨。","不繫知之與不知，須言一字千金值。"]', '诗', 'shi', '', NULL, '贈{巩/言}光上人草書歌 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c4387c-bb94-4278-870a-d904b952483d', '贈李長史歌', '贈李长史歌', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["危欄壓溪溪澹碧，翠褭紅飄鶯寂寂。","此日長亭愴別離，座中忽遇吹蘆客。","雙攘輕袖當高軒，含商吐羽凌非煙。","初疑一百尺瀑布，八九月落香爐巔。","又似鮫人爲客罷，迸淚成珠玉盤瀉。","碧珊瑚碎震澤中，金鋃鐺撼龜山下。","鏗訇揭調初驚人，幽咽細聲還感神。","紫鳳將雛叫山月，玄兔喪子啼江春。","咨嗟長史出人藝，如何值此艱難際。","可中長似承平基，肯將此爲閑人吹。","不是東城射雉處，即應南苑鬬雞時。","白櫻桃熟每先賞，紅芍藥開長有詩。","賣珠曾被武皇問，薰香不怕賈公知。","今來流落一何苦，江南江北九寒暑。","翠華猶在橐泉中，一曲梁州淚如雨。","長史長史聽我語，從來藝絕多失所。","羅君贈君兩首詩，半是悲君半自悲。"]', '["危欄壓溪溪澹碧，翠褭紅飄鶯寂寂。","此日长亭愴別離，座中忽遇吹蘆客。","雙攘轻袖當高軒，含商吐羽凌非煙。","初疑一百尺瀑布，八九月落香爐巔。","又似鮫人爲客罷，迸泪成珠玉盤瀉。","碧珊瑚碎震澤中，金鋃鐺撼龟山下。","鏗訇揭調初驚人，幽咽細声還感神。","紫鳳將雛叫山月，玄兔喪子啼江春。","咨嗟长史出人藝，如何值此艱难際。","可中长似承平基，肯將此爲闲人吹。","不是东城射雉处，即應南苑鬬雞时。","白櫻桃熟每先賞，紅芍藥开长有诗。","賣珠曾被武皇问，薰香不怕賈公知。","今来流落一何苦，江南江北九寒暑。","翠华猶在橐泉中，一曲梁州泪如雨。","长史长史听我語，從来藝絕多失所。","羅君贈君兩首诗，半是悲君半自悲。"]', '诗', 'shi', '', NULL, '贈李長史歌 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03b8b065-de20-46ca-a56f-bad0d1e1a5f5', '贈廣利大師歌', '贈廣利大師歌', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["化人之心固甚難，自化之心更不易。","化人可以程限之，自化元須有其志。","在心爲志者何人，今日得之於廣利。","三十年前識師初，正見把筆學草書。","崩雲落日千萬狀，隨手變化生空虛。","海北天南幾回別，每見書蹤轉奇絕。","近來兼解作歌詩，言語明快有氣骨。","堅如百鍊鋼，挺特不可屈。","又如千里馬，脫韁飛滅沒。","好是不雕刻，縱橫衝口發。","昨來示我十餘篇，詠殺江南風與月。","乃知性是天，習是人。","莫輕河邊羖䍽，飛作天上麒麟。","但日新，又日新。","李太白，非通神。"]', '["化人之心固甚难，自化之心更不易。","化人可以程限之，自化元須有其志。","在心爲志者何人，今日得之於廣利。","三十年前識師初，正见把笔学草书。","崩云落日千万狀，隨手变化生空虛。","海北天南幾回別，每见书蹤轉奇絕。","近来兼解作歌诗，言語明快有氣骨。","堅如百鍊鋼，挺特不可屈。","又如千里马，脫韁飞滅沒。","好是不雕刻，縱橫衝口發。","昨来示我十餘篇，詠殺江南风與月。","乃知性是天，習是人。","莫轻河邊羖䍽，飞作天上麒麟。","但日新，又日新。","李太白，非通神。"]', '诗', 'shi', '', NULL, '贈廣利大師歌 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9b068a0-73d9-437b-9a18-3bd314ba138e', '古離別', '古離別', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["紫鸞黃鵠雖別離，一舉千里何難追。","猶聞啼風與叫月，流連斷續令人悲。","賦情更有深繾綣，碧甃千尋尚爲淺。","蟾蜍正向清夜流，蛺蝶須教墮絲罥。","莫道斷絲不可續，丹穴鳳凰膠不遠。","莫道流水不迴波，海上兩潮長自返。"]', '["紫鸾黄鵠雖別離，一舉千里何难追。","猶闻啼风與叫月，流連斷續令人悲。","賦情更有深繾綣，碧甃千尋尚爲淺。","蟾蜍正向清夜流，蛺蝶須教墮絲罥。","莫道斷絲不可續，丹穴鳳凰膠不远。","莫道流水不迴波，海上兩潮长自返。"]', '诗', 'shi', '', NULL, '古離別 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38100dc8-bc59-44f5-9e22-bb12be88d05d', '風雨吟', '风雨吟', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["風騷騷，雨涔涔，長洲苑外荒居深。","門外流水流澶漫，河邊古木鳴蕭森。","敻無禽影，寂無人音。","端然拖愁坐，萬感叢於心。","姑蘇碧瓦十萬戶，中有樓臺與歌舞。","尋常倚月復眠花，莫說斜風兼細雨。","應不知天地造化是何物，亦不知榮辱是何主。","吾囷長滿是太平，吾樂不極是天生。","豈憂天下有大憝，四郊刁斗常錚錚。","官軍擾人甚於賊，將臣怕死唯守城。","又豈復憂朝廷苦弛慢，中官轉縱橫。","李膺勾黨即罹患，竇武忠謀又未行。","又豈憂文臣盡遭束高閣，文教從今日蕭索。","若更無人稍近前，把筆到頭同一惡。","可嘆吳城城中人，無人與我交一言。","蓬蒿滿徑塵一榻，獨此閔閔何其煩。","雖然小或可謀大，[嫠]婦之憂史尚存。","況我長懷丈夫志，今來流落滄溟涘。","有時驚事再咨嗟，因風因雨更憔悴。","只有閑橫膝上琴，怨傷怨恨聊相寄。","伯牙海上感滄溟，何似今朝風雨思。"]', '["风騷騷，雨涔涔，长洲苑外荒居深。","门外流水流澶漫，河邊古木鳴蕭森。","敻無禽影，寂無人音。","端然拖愁坐，万感叢於心。","姑蘇碧瓦十万戶，中有楼台與歌舞。","尋常倚月复眠花，莫说斜风兼細雨。","應不知天地造化是何物，亦不知榮辱是何主。","吾囷长满是太平，吾乐不極是天生。","豈憂天下有大憝，四郊刁斗常錚錚。","官軍擾人甚於賊，將臣怕死唯守城。","又豈复憂朝廷苦弛慢，中官轉縱橫。","李膺勾黨即罹患，竇武忠謀又未行。","又豈憂文臣尽遭束高閣，文教從今日蕭索。","若更無人稍近前，把笔到头同一惡。","可嘆吳城城中人，無人與我交一言。","蓬蒿满徑塵一榻，独此閔閔何其煩。","雖然小或可謀大，[嫠]婦之憂史尚存。","況我长懷丈夫志，今来流落滄溟涘。","有时驚事再咨嗟，因风因雨更憔悴。","只有闲橫膝上琴，怨傷怨恨聊相寄。","伯牙海上感滄溟，何似今朝风雨思。"]', '诗', 'shi', '', NULL, '風雨吟 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a143dca3-283d-4a1f-9d7c-e095562a31db', '江行', '江行', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["來時風，去時雨，蕭蕭颯颯春江浦。","欹欹側側海門帆，軋軋啞啞洞庭櫓。"]', '["来时风，去时雨，蕭蕭颯颯春江浦。","欹欹側側海门帆，軋軋啞啞洞庭櫓。"]', '诗', 'shi', '', NULL, '江行 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b431fa-d330-41da-8ddf-b012b801d894', '壁畫折竹雜言', '壁畫折竹杂言', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["枯纏藤，重欹雪，渭曲逢，湘江別。","不是從來無本根，畫工取勢教摧折。"]', '["枯纏藤，重欹雪，渭曲逢，湘江別。","不是從来無本根，畫工取勢教摧折。"]', '诗', 'shi', '', NULL, '壁畫折竹雜言 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f715bcb-1a10-40b8-a20c-f07634e33273', '古錦裾六韻', '古錦裾六韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["濯水經何日，隨風故有人。","綠衣猶偪畫，丹頂尚迷真。","暗澹雲沈古，青蒼蘚剝新。","暎襟知惹淚，侵韉想縈塵。","掣曳無由睹，流傳久自珍。","武威應認得，牽挽幾當春。"]', '["濯水經何日，隨风故有人。","綠衣猶偪畫，丹頂尚迷真。","暗澹云沈古，青蒼蘚剝新。","暎襟知惹泪，侵韉想縈塵。","掣曳無由睹，流傳久自珍。","武威應認得，牽挽幾當春。"]', '诗', 'shi', '', NULL, '古錦裾六韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a495149f-2c80-452a-a557-283fb578a1fa', '賦得欲曉看妝面', '賦得欲晓看妝面', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["朧朧欲曙色，隱隱辨殘妝。","月始雲中出，花猶霧裏藏。","眉邊全失翠，額畔半留黃。","轉入金屏影，隈侵角枕光。","有蟬隳鬢樣，無燕著𨥁行。","十二峯前夢，如何不斷腸。"]', '["朧朧欲曙色，隐隐辨殘妝。","月始云中出，花猶霧裏藏。","眉邊全失翠，額畔半留黄。","轉入金屏影，隈侵角枕光。","有蟬隳鬢樣，無燕著𨥁行。","十二峯前梦，如何不斷腸。"]', '诗', 'shi', '', NULL, '賦得欲曉看妝面 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecb9b524-ba9d-4f24-b1e9-433ec6964eee', '府試雨夜帝里聞猿聲', '府試雨夜帝里闻猿声', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["雨滴秦中夜，猿聞峽外聲。","已吟何遜恨，還賦屈平情。","暗逐哀鴻淚，遙含禁漏清。","直疑遊萬里，不覺在重城。","霎霎侵燈亂，啾啾入夢驚。","明朝臨曉鏡，別有鬢絲生。"]', '["雨滴秦中夜，猿闻峽外声。","已吟何遜恨，還賦屈平情。","暗逐哀鴻泪，遙含禁漏清。","直疑游万里，不覺在重城。","霎霎侵灯亂，啾啾入梦驚。","明朝臨晓镜，別有鬢絲生。"]', '诗', 'shi', '', NULL, '府試雨夜帝里聞猿聲 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc59ed4d-5cb0-4371-af2d-8970f6630501', '題畫柏', '題畫柏', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["不得月中桂，轉思陵上柏。","閑取畫圖看，煩紆果冰釋。","桂生在青冥，萬古煙霧隔。","下蔭玄兔窟，上暎嫦娥魄。","圓缺且不常，高低圖難測。","若非假羽翰，折攀何由得。","天遠眼虛穿，夜闌頭自白。","未知陵上柏，一定不移易。","有意兼松茂，無情從麝食。","不在是非間，與人爲憤激。","他年上縑素，今日懸屋壁。","靈怪不可知，風雨疑來逼。","明朝歸故園，唯此同所適。","回首寄團枝，無勞惠消息。"]', '["不得月中桂，轉思陵上柏。","闲取畫圖看，煩紆果冰釋。","桂生在青冥，万古煙霧隔。","下蔭玄兔窟，上暎嫦娥魄。","圓缺且不常，高低圖难測。","若非假羽翰，折攀何由得。","天远眼虛穿，夜闌头自白。","未知陵上柏，一定不移易。","有意兼松茂，無情從麝食。","不在是非间，與人爲憤激。","他年上縑素，今日懸屋壁。","靈怪不可知，风雨疑来逼。","明朝归故园，唯此同所適。","回首寄團枝，無勞惠消息。"]', '诗', 'shi', '', NULL, '題畫柏 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca650b3-a08b-4599-97be-2aec53e586b5', '平望蚊子二十六韻', '平望蚊子二十六韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["天下有蚊子，候夜噆人膚。","平望有蚊子，白晝來相屠。","不避風與雨，羣飛出菰蒲。","擾擾蔽天黑，雷然隨舳艫。","利嘴入人肉，微形紅且濡。","振蓬亦不懼，至死貪膏腴。","舟人敢停棹，陸者亦疾趨。","南北百餘里，畏之如虎貙。","噫嘻天地間，萬物各有殊。","陽者陽爲伍，陰者陰爲徒。","蚊蚋是陰物，夜從喧牆隅。","如何正曦赫，吞噬當通衢。","人筋爲爾斷，人力爲爾枯。","衣巾穢且甚，盤饌腥有餘。","豈是陽德衰，不能使消除。","豈是有主者，此鄉宜毒荼。","吾聞蛇能螫，避之則無虞。","吾聞蠆有毒，見之可疾驅。","唯是此蚊子，逢人皆病諸。","江南夏景好，水木多蕭疎。","此中震澤路，風月彌清虛。","前後幾來往，襟懷曾未舒。","朝既蒙襞積，夜仍跧蘧蒢。","雖然好吟嘯，其奈難踟蹰。","人生有不便，天意當何如。","誰能假羽翼，直上言紅鑪。"]', '["天下有蚊子，候夜噆人膚。","平望有蚊子，白晝来相屠。","不避风與雨，羣飞出菰蒲。","擾擾蔽天黑，雷然隨舳艫。","利嘴入人肉，微形紅且濡。","振蓬亦不懼，至死貪膏腴。","舟人敢停棹，陸者亦疾趨。","南北百餘里，畏之如虎貙。","噫嘻天地间，万物各有殊。","陽者陽爲伍，陰者陰爲徒。","蚊蚋是陰物，夜從喧牆隅。","如何正曦赫，吞噬當通衢。","人筋爲爾斷，人力爲爾枯。","衣巾穢且甚，盤饌腥有餘。","豈是陽德衰，不能使消除。","豈是有主者，此乡宜毒荼。","吾闻蛇能螫，避之則無虞。","吾闻蠆有毒，见之可疾驱。","唯是此蚊子，逢人皆病諸。","江南夏景好，水木多蕭疎。","此中震澤路，风月彌清虛。","前後幾来往，襟懷曾未舒。","朝既蒙襞積，夜仍跧蘧蒢。","雖然好吟嘯，其奈难踟蹰。","人生有不便，天意當何如。","誰能假羽翼，直上言紅鑪。"]', '诗', 'shi', '', NULL, '平望蚊子二十六韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec22cba9-2ae4-432a-8ee5-be0b3102d3ab', '桃花', '桃花', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["滿樹和嬌爛漫紅，萬枝丹彩灼春融。","何當結作千年實，將示人間造化工。"]', '["满樹和嬌爛漫紅，万枝丹彩灼春融。","何當結作千年實，將示人间造化工。"]', '诗', 'shi', '', NULL, '桃花 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d975670-5361-4dfa-8dea-a7c9192229b9', '木筆花', '木笔花', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["嫩如新竹管初齊，粉膩紅輕樣可攜。","誰與詩人偎檻看，好於牋墨併分題。"]', '["嫩如新竹管初齊，粉膩紅轻樣可携。","誰與诗人偎檻看，好於牋墨併分題。"]', '诗', 'shi', '', NULL, '木筆花 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd539f8-81df-4b70-ae80-d5178dba4c76', '淛東筵上有寄', '淛东筵上有寄', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["襄王席上一神仙，眼色相當語不傳。","見了又休真似夢，坐來雖近遠於天。","隴禽有意猶能說，江月無心也解圓。","更被東風勸惆悵，落花時節定翩翩。"]', '["襄王席上一神仙，眼色相當語不傳。","见了又休真似梦，坐来雖近远於天。","隴禽有意猶能说，江月無心也解圓。","更被东风勸惆悵，落花时節定翩翩。"]', '诗', 'shi', '', NULL, '淛東筵上有寄 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f911f79-05f7-455b-89d8-84be9d19a0a9', '富水驛東楹有人題詩', '富水驛东楹有人題诗', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["繡纓霞翼兩鴛鴦，金島銀川是故鄉。","只合雙飛便雙死，豈悲相失與相忘。","煙花夜泊紅蕖膩，蘭渚春遊碧草芳。","何事遽驚雲雨別，秦山楚水兩乖張。"]', '["繡纓霞翼兩鴛鴦，金島銀川是故乡。","只合雙飞便雙死，豈悲相失與相忘。","煙花夜泊紅蕖膩，蘭渚春游碧草芳。","何事遽驚云雨別，秦山楚水兩乖張。"]', '诗', 'shi', '', NULL, '富水驛東楹有人題詩 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e2b7d0f-57b1-416f-bcd4-525ba34fd7d1', '上巳日', '上巳日', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["本學多情劉武威，尋花傍水看春暉。","無端遇著傷心事，贏得淒涼索漠歸。"]', '["本学多情劉武威，尋花傍水看春暉。","無端遇著傷心事，贏得淒涼索漠归。"]', '诗', 'shi', '', NULL, '上巳日 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4f49f27-3a23-416f-8e2b-24a1dbdf0445', '隋堤', '隋堤', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["搔首隋堤落日斜，已無餘柳可藏鴉。","岸傍昔道牽龍艦，河底今來走犢車。","曾笑陳家歌玉樹，却隨後主看瓊花。","四方正是無虞日，誰信黎陽有古家。"]', '["搔首隋堤落日斜，已無餘柳可藏鴉。","岸傍昔道牽龙艦，河底今来走犢车。","曾笑陳家歌玉樹，却隨後主看瓊花。","四方正是無虞日，誰信黎陽有古家。"]', '诗', 'shi', '', NULL, '隋堤 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7e99c8f-cda0-4dc3-a195-4b0c015a2e3f', '寄杜先生詩', '寄杜先生诗', '5252d903-5837-4ded-843f-2b12f5c7ea3b', '唐', '["蜀國信難遇，楚鄉心更愁。","我行同范蠡，師舉效浮丘。","他日相逢處，多應在十洲。"]', '["蜀国信难遇，楚乡心更愁。","我行同范蠡，師舉效浮丘。","他日相逢处，多應在十洲。"]', '诗', 'shi', '', NULL, '寄杜先生詩 孫偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17a7cdce-d717-479f-aae5-f1cb79fb2236', '贈南嶽僧全玭', '贈南嶽僧全玭', '5252d903-5837-4ded-843f-2b12f5c7ea3b', '唐', '["窠居過後更何人，傳得如來法印真。","昨日祝融峰下見，草衣便是雪山□。"]', '["窠居過後更何人，傳得如来法印真。","昨日祝融峰下见，草衣便是雪山□。"]', '诗', 'shi', '', NULL, '贈南嶽僧全玭 孫偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e28eaf-9ae7-4e63-842a-339ac012bb77', '荅門生王渙李德鄰趙光胤王拯長句', '荅门生王渙李德鄰趙光胤王拯长句', '5252d903-5837-4ded-843f-2b12f5c7ea3b', '唐', '["謬持文柄得時賢，粉署清華次第遷。","昔歲策名皆健筆，今朝稱職並同年。","各懷器業寧推讓，俱上青霄肯後先。","何事老夫猶賦詠，欲將酬和永留傳。"]', '["謬持文柄得时賢，粉署清华次第遷。","昔歲策名皆健笔，今朝稱職並同年。","各懷器業寧推讓，俱上青霄肯後先。","何事老夫猶賦詠，欲將酬和永留傳。"]', '诗', 'shi', '', NULL, '荅門生王渙李德鄰趙光胤王拯長句 孫偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be8f904b-9a2c-4607-9b72-0c4977713b7c', '句', '句', '5252d903-5837-4ded-843f-2b12f5c7ea3b', '唐', '["好是步虛明月夜，瑞爐蜚下醮壇前。"]', '["好是步虛明月夜，瑞爐蜚下醮壇前。"]', '诗', 'shi', '', NULL, '句 孫偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51079f37-b3f8-4287-9494-3bfda3a83e4c', '禁林聞曉鶯', '禁林闻晓鶯', 'c832b8fd-ba27-4464-b7a5-ef4574615a20', '唐', '["曙色分層漢，鶯聲繞上林。","報花開瑞錦，催柳綻黃金。","斷續隨風遠，間關送月沈。","語當溫樹近，飛覺禁園深。","繡戶驚殘夢，瑤池囀好音。","願將棲息意，從此沃天心。"]', '["曙色分層漢，鶯声繞上林。","報花开瑞錦，催柳綻黄金。","斷續隨风远，间关送月沈。","語當溫樹近，飞覺禁园深。","繡戶驚殘梦，瑤池囀好音。","願將棲息意，從此沃天心。"]', '诗', 'shi', '', NULL, '禁林聞曉鶯 陸扆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b2c6661-3cd4-488e-b671-b75ef2f40418', '句', '句', 'c832b8fd-ba27-4464-b7a5-ef4574615a20', '唐', '["今秋已約天台月。"]', '["今秋已約天台月。"]', '诗', 'shi', '', NULL, '句 陸扆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1469ba6-9f93-46b8-82bd-af8816362dcb', '華州牓寄諸門生', '华州牓寄諸门生', '210f995b-e86f-4ad4-b874-7637e9c3f386', '唐', '["時君過聽委平衡，粉署華燈到曉明。","開卷固難窺浩汗，執衡空欲慕公平。","機雲筆舌臨文健，沈宋章篇發詠清。","自笑觀光輝。"]', '["时君過听委平衡，粉署华灯到晓明。","开卷固难窺浩汗，執衡空欲慕公平。","機云笔舌臨文健，沈宋章篇發詠清。","自笑观光輝。"]', '诗', 'shi', '', NULL, '華州牓寄諸門生 薛昭緯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e5c503f-406c-4bf1-a9b7-e02c65a08818', '謝銀工', '謝銀工', '210f995b-e86f-4ad4-b874-7637e9c3f386', '唐', '["一楪氈根數十皴，盤中猶更有紅鱗。","早知文字多辛苦，悔不當初學冶銀。"]', '["一楪氈根數十皴，盤中猶更有紅鱗。","早知文字多辛苦，悔不當初学冶銀。"]', '诗', 'shi', '', NULL, '謝銀工 薛昭緯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44208aa2-fc56-4fac-a8b2-eb1a52bce8d1', '閑居即事', '闲居即事', '386b0bc5-e3fa-4fec-8478-1817ecd636f6', '唐', '["衰柳迷隋苑，衡門啼暮鴉。","茅廚煙不動，書牖日空斜。","悔下東山石，貧於南阮家。","沈憂損神慮，萱草自開花。"]', '["衰柳迷隋苑，衡门啼暮鴉。","茅廚煙不动，书牖日空斜。","悔下东山石，貧於南阮家。","沈憂損神慮，萱草自开花。"]', '诗', 'shi', '', NULL, '閑居即事 陸翱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f8963b-77e0-4296-97b1-2f81576ca377', '趙氏北樓', '趙氏北楼', '386b0bc5-e3fa-4fec-8478-1817ecd636f6', '唐', '["慇懃趙公子，良夜竟相留。","朗月生東海，仙娥在北樓。","酒闌珠露滴，歌逈石城秋。","本爲愁人設，愁人到曉愁。"]', '["慇懃趙公子，良夜竟相留。","朗月生东海，仙娥在北楼。","酒闌珠露滴，歌逈石城秋。","本爲愁人設，愁人到晓愁。"]', '诗', 'shi', '', NULL, '趙氏北樓 陸翱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a30231d3-d12f-4ca4-809c-31fe9b38cc5f', '題馬嵬驛', '題马嵬驛', '03ab8713-2adc-4f30-a0dd-3629a6cd4ff7', '唐', '["馬嵬煙柳正依依，重見鑾輿幸蜀歸。","泉下阿蠻應有語，這回休更怨楊妃。"]', '["马嵬煙柳正依依，重见鑾輿幸蜀归。","泉下阿蠻應有語，這回休更怨楊妃。"]', '诗', 'shi', '', NULL, '題馬嵬驛 狄歸昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b669fb21-e6e3-472a-aaa5-75cae8e0b60b', '蜀中登第荅李搏六韻', '蜀中登第荅李搏六韻', '96dde2d8-f8ec-4407-aee0-ea6d19d40d35', '唐', '["何勞問我成都事，亦報君知便納降。","蜀柳籠堤煙矗矗，海棠當戶燕雙雙。","富春不並窮師子，濯錦全勝旱曲江。","高捲絳紗揚氏宅，半垂紅袖薛濤牕。","浣花泛鷁詩千首，靜衆尋梅酒百缸。","若說弦歌與風景，主人兼是碧油幢。"]', '["何勞问我成都事，亦報君知便納降。","蜀柳籠堤煙矗矗，海棠當戶燕雙雙。","富春不並窮師子，濯錦全勝旱曲江。","高捲絳紗揚氏宅，半垂紅袖薛濤牕。","浣花泛鷁诗千首，静衆尋梅酒百缸。","若说弦歌與风景，主人兼是碧油幢。"]', '诗', 'shi', '', NULL, '蜀中登第荅李搏六韻 裴廷裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0abe9d3-f8be-4d57-b247-fdc70924165d', '偶題', '偶題', '96dde2d8-f8ec-4407-aee0-ea6d19d40d35', '唐', '["微雨微風寒食節，半開半合木蘭花。","看花倚柱終朝立，却似淒淒不在家。"]', '["微雨微风寒食節，半开半合木蘭花。","看花倚柱終朝立，却似淒淒不在家。"]', '诗', 'shi', '', NULL, '偶題 裴廷裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1a09fd-044a-4a36-9d55-be31dc097352', '閑宵望月', '闲宵望月', 'fb2985f5-396b-495d-82f1-8b68243896c9', '唐', '["卷箔舒紅茵，當軒翫明月。","懿哉深夜中，靜聽歌初發。","苔含殿華濕，竹影蟾光潔。","轉扇來清風，援琴飛白雪。","行愁景候變，坐恐流芳歇。","桂影有餘光，蘭燈任將滅。"]', '["卷箔舒紅茵，當軒翫明月。","懿哉深夜中，静听歌初發。","苔含殿华濕，竹影蟾光潔。","轉扇来清风，援琴飞白雪。","行愁景候变，坐恐流芳歇。","桂影有餘光，蘭灯任將滅。"]', '诗', 'shi', '', NULL, '閑宵望月 李沇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8810649a-95e0-4870-a086-4bc6d5fc3865', '醮詞', '醮词', 'fb2985f5-396b-495d-82f1-8b68243896c9', '唐', '["犬咬天關閉，彩童呼僊吏。","一封紅篆書，爲奏塵寰事。","八極鼇柱傾，四溟龍鬣沸。","長庚冷有芒，文曲澹無氣。","烏輪不再中，黃沙瘞腥鬼。","請帝命真官，臨雲啓金匱。","方與清華宮，重正紫極位。","曠古雨露恩，安得惜沾施。","生人血欲盡，攙搶無飽意。"]', '["犬咬天关閉，彩童呼僊吏。","一封紅篆书，爲奏塵寰事。","八極鼇柱傾，四溟龙鬣沸。","长庚冷有芒，文曲澹無氣。","烏輪不再中，黄沙瘞腥鬼。","請帝命真官，臨云啓金匱。","方與清华宮，重正紫極位。","曠古雨露恩，安得惜沾施。","生人血欲尽，攙搶無飽意。"]', '诗', 'shi', '', NULL, '醮詞 李沇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b339a0db-62c8-4e5d-b380-e3e5228c9347', '巫山高', '巫山高', 'fb2985f5-396b-495d-82f1-8b68243896c9', '唐', '["抉天心，開地脉，俘動凌霄拂藍碧。","襄王端眸望不極，似睹瑤姬長歎息。","巫妝不治獨西望，暗泣紅蕉抱雲帳。","君王妬妾夢荆宮，虛把金泥印仙掌。","江濤迅激如相助，十二獰龍怒行雨。","崑崙謾有通天路，九峰正在天低處。"]', '["抉天心，开地脉，俘动凌霄拂藍碧。","襄王端眸望不極，似睹瑤姬长歎息。","巫妝不治独西望，暗泣紅蕉抱云帳。","君王妬妾梦荆宮，虛把金泥印仙掌。","江濤迅激如相助，十二獰龙怒行雨。","崑崙謾有通天路，九峰正在天低处。"]', '诗', 'shi', '', NULL, '巫山高 李沇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abe0f4f3-884b-4043-a852-7b47911078e2', '夢仙謠', '梦仙謠', 'fb2985f5-396b-495d-82f1-8b68243896c9', '唐', '["海宮蹙浪收殘月，挈壺掌事傳更歇。","銀蟾半墜恨流咽，六鰲披月撼蓬闕。","九炁真翁騎白犀，臨池靜聽雌蛟啼。","桂花浥露曙香冷，八窗玉朗驚晨雞。","裁紗翦羅貼丹鳳，膩霞遠閉瑤山夢。","露乾欲醉芙蕖塘，迴首驅雲朝正陽。"]', '["海宮蹙浪收殘月，挈壺掌事傳更歇。","銀蟾半墜恨流咽，六鰲披月撼蓬闕。","九炁真翁騎白犀，臨池静听雌蛟啼。","桂花浥露曙香冷，八窗玉朗驚晨雞。","裁紗翦羅貼丹鳳，膩霞远閉瑤山梦。","露乾欲醉芙蕖塘，迴首驱云朝正陽。"]', '诗', 'shi', '', NULL, '夢仙謠 李沇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e7730a6-4bfe-445d-a161-c2a9d6e1515a', '秋霖歌', '秋霖歌', 'fb2985f5-396b-495d-82f1-8b68243896c9', '唐', '["西方龍兒口猶乳，初解驅雲學行雨。","縱恣羣陰駕老虬，勺水蹄涔盡奔注。","葉破苔黃未休滴，膩光透長狂莎色。","恨無長劒一千仞，劃斷頑雲看晴碧。"]', '["西方龙兒口猶乳，初解驱云学行雨。","縱恣羣陰駕老虬，勺水蹄涔尽奔注。","葉破苔黄未休滴，膩光透长狂莎色。","恨無长劒一千仞，劃斷頑云看晴碧。"]', '诗', 'shi', '', NULL, '秋霖歌 李沇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee762a37-026e-4a87-b3cf-b1a303316052', '方響歌', '方响歌', 'fb2985f5-396b-495d-82f1-8b68243896c9', '唐', '["敲金扣石聲相凌，遙空冷靜天正澄。","寶缾下井轆轤急，小娃弄索傷清冰。","穿絲透管音未歇，迴風繞指驚泉咽。","季倫怒擊珊瑚摧，靈芸整鬢步搖折。","十六葉中侵素光，寒玲震月雜珮璫。","雲和不覺罷餘怨，蓮峰一夜啼琴姜。","急節寫商商恨促，秦愁越調逡巡足。","夢入仙樓戛殘曲，飛霜稜稜上秋玉。"]', '["敲金扣石声相凌，遙空冷静天正澄。","寶缾下井轆轤急，小娃弄索傷清冰。","穿絲透管音未歇，迴风繞指驚泉咽。","季倫怒擊珊瑚摧，靈芸整鬢步搖折。","十六葉中侵素光，寒玲震月杂珮璫。","云和不覺罷餘怨，蓮峰一夜啼琴姜。","急節寫商商恨促，秦愁越調逡巡足。","梦入仙楼戛殘曲，飞霜稜稜上秋玉。"]', '诗', 'shi', '', NULL, '方響歌 李沇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab07977-848f-4834-a3a2-9ee1d3a97447', '荅王渙', '荅王渙', 'c10761a0-778f-430d-a78e-1e3666d5d487', '唐', '["謬持文柄得時賢，粉署清華次第遷。","昔歲策名皆健筆，今朝稱職並同年。","各懷器業寧推讓，俱上青霄肯後先。","何事老夫猶賦詠，欲將酬和永留傳。"]', '["謬持文柄得时賢，粉署清华次第遷。","昔歲策名皆健笔，今朝稱職並同年。","各懷器業寧推讓，俱上青霄肯後先。","何事老夫猶賦詠，欲將酬和永留傳。"]', '诗', 'shi', '', NULL, '荅王渙 裴贄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95f7bab0-ee45-4175-b1a2-bcbcc9587d88', '薄命妾', '薄命妾', '06928e78-01f3-45b1-a680-29649ecccf79', '唐', '["君恩已斷盡成空，追想嬌歡恨莫窮。","長爲蕣花光曉日，誰知團扇送秋風。","黃金買賦心徒切，清路飛塵信莫通。","閑凭玉欄思舊事，幾回春暮泣殘紅。"]', '["君恩已斷尽成空，追想嬌歡恨莫窮。","长爲蕣花光晓日，誰知團扇送秋风。","黄金買賦心徒切，清路飞塵信莫通。","闲凭玉欄思旧事，幾回春暮泣殘紅。"]', '诗', 'shi', '', NULL, '薄命妾 盧汝弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae14cbbe-4641-4d08-aa99-bc02c48284e0', '秋夕寓居精舍書事', '秋夕寓居精舍书事', '06928e78-01f3-45b1-a680-29649ecccf79', '唐', '["葉滿苔堦杵滿城，此中多恨恨難平。","疎簷看織蠨蛸網，暗隙愁聽蟋蟀聲。","醉臥欲拋羈客思，夢歸偏動故鄉情。","覺來獨步長廊下，半夜西風吹月明。"]', '["葉满苔堦杵满城，此中多恨恨难平。","疎簷看织蠨蛸網，暗隙愁听蟋蟀声。","醉臥欲拋羈客思，梦归偏动故乡情。","覺来独步长廊下，半夜西风吹月明。"]', '诗', 'shi', '', NULL, '秋夕寓居精舍書事 盧汝弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66a93f31-272a-4a2a-acc3-e3e586542d9e', '聞雁', '闻雁', '06928e78-01f3-45b1-a680-29649ecccf79', '唐', '["秋風蕭瑟靜埃氛，邊雁迎風響咽羣。","瀚海應嫌霜下早，湘川偏愛草初薰。","蘆洲宿處依沙岸，榆塞飛時度晚雲。","何處最添羈客恨，竹窗殘月酒醒聞。"]', '["秋风蕭瑟静埃氛，邊雁迎风响咽羣。","瀚海應嫌霜下早，湘川偏愛草初薰。","蘆洲宿处依沙岸，榆塞飞时度晚云。","何处最添羈客恨，竹窗殘月酒醒闻。"]', '诗', 'shi', '', NULL, '聞雁 盧汝弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dee1d3b-d968-43ce-8913-51b25cc2fe9c', '鴛鴦', '鴛鴦', '06928e78-01f3-45b1-a680-29649ecccf79', '唐', '["雙浮雙浴傍苔磯，蓼浦蘭臯繡帳幃。","長羨鷺鷥能潔白，不隨鸂鶒鬬毛衣。","霞侵綠渚香衾暖，樓倚青雲殿瓦飛。","應笑隨陽沙漠雁，洞庭煙暖又思歸。"]', '["雙浮雙浴傍苔磯，蓼浦蘭臯繡帳幃。","长羨鷺鷥能潔白，不隨鸂鶒鬬毛衣。","霞侵綠渚香衾暖，楼倚青云殿瓦飞。","應笑隨陽沙漠雁，洞庭煙暖又思归。"]', '诗', 'shi', '', NULL, '鴛鴦 盧汝弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75aa294d-ec72-4ba9-a8e7-cfced83d3833', '和李秀才邊庭四時怨 一', '和李秀才邊庭四时怨 一', '06928e78-01f3-45b1-a680-29649ecccf79', '唐', '["春風昨夜到榆關，故國煙花想已殘。","少婦不知歸不得，朝朝應上望夫山。"]', '["春风昨夜到榆关，故国煙花想已殘。","少婦不知归不得，朝朝應上望夫山。"]', '诗', 'shi', '', NULL, '和李秀才邊庭四時怨 一 盧汝弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d3cea35-013e-4bb6-bcde-944e9bd4b7bb', '和李秀才邊庭四時怨 二', '和李秀才邊庭四时怨 二', '06928e78-01f3-45b1-a680-29649ecccf79', '唐', '["盧龍塞外草初肥，雁乳平蕪曉不飛。","鄉國近來音信斷，至今猶自著寒衣。"]', '["盧龙塞外草初肥，雁乳平蕪晓不飞。","乡国近来音信斷，至今猶自著寒衣。"]', '诗', 'shi', '', NULL, '和李秀才邊庭四時怨 二 盧汝弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd92f7fc-9acf-4083-94de-28858dc59b6c', '和李秀才邊庭四時怨 三', '和李秀才邊庭四时怨 三', '06928e78-01f3-45b1-a680-29649ecccf79', '唐', '["八月霜飛柳半黃，蓬根吹斷雁南翔。","隴頭流水關山月，泣上龍堆望故鄉。"]', '["八月霜飞柳半黄，蓬根吹斷雁南翔。","隴头流水关山月，泣上龙堆望故乡。"]', '诗', 'shi', '', NULL, '和李秀才邊庭四時怨 三 盧汝弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77561049-4d06-4e15-b0db-12faa3717e20', '和李秀才邊庭四時怨 四', '和李秀才邊庭四时怨 四', '06928e78-01f3-45b1-a680-29649ecccf79', '唐', '["朔風吹雪透刀瘢，飲馬長城窟更寒。","半夜火來知有敵，一時齊保賀蘭山。"]', '["朔风吹雪透刀瘢，饮马长城窟更寒。","半夜火来知有敵，一时齊保賀蘭山。"]', '诗', 'shi', '', NULL, '和李秀才邊庭四時怨 四 盧汝弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06bebd1b-f5db-48a8-95ed-cf8147ca0c30', '山居即事二首 一', '山居即事二首 一', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["君山蒼翠接青冥，東走洮湖上洞庭。","茅屋向陽梳白髮，竹窓深夜誦丹經。","湧泉回泬魚龍氣，怪石驚騰鳥獸形。","爲問前時金馬客，此焉還作少微星。"]', '["君山蒼翠接青冥，东走洮湖上洞庭。","茅屋向陽梳白髮，竹窓深夜誦丹經。","湧泉回泬鱼龙氣，怪石驚腾鸟獸形。","爲问前时金马客，此焉還作少微星。"]', '诗', 'shi', '', NULL, '山居即事二首 一 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cf9d20d-b287-4b47-9779-f201b993f5e6', '山居即事二首 二', '山居即事二首 二', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["不是幽棲矯性靈，從來無意在羶腥。","滿川風物供高枕，四合雲山借畫屏。","五鹿歸來驚嶽嶽，孤鴻飛去入冥冥。","君陽遁叟何爲樂，一炷清香兩卷經。"]', '["不是幽棲矯性靈，從来無意在羶腥。","满川风物供高枕，四合云山借畫屏。","五鹿归来驚嶽嶽，孤鴻飞去入冥冥。","君陽遁叟何爲乐，一炷清香兩卷經。"]', '诗', 'shi', '', NULL, '山居即事二首 二 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('800dcdad-ce26-4afa-aca7-4aa715a84780', '陽羨雜詠十九首 苦竹逕', '陽羨杂詠十九首 苦竹逕', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["山前無數碧琅玕，一逕清森五月寒。","世上何人憐苦節，應須細問子猷看。"]', '["山前無數碧琅玕，一逕清森五月寒。","世上何人怜苦節，應須細问子猷看。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 苦竹逕 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f30743af-3dd9-464d-92cc-4952f5a2e383', '陽羨雜詠十九首 梅花塢', '陽羨杂詠十九首 梅花塢', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["凍蘂凝香色豔新，小山深塢伴幽人。","知君有意凌寒色，羞共千花一樣春。"]', '["凍蘂凝香色豔新，小山深塢伴幽人。","知君有意凌寒色，羞共千花一樣春。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 梅花塢 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6192f742-8d10-4de6-a325-3e53989f23ea', '陽羨雜詠十九首 石兕臺', '陽羨杂詠十九首 石兕台', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["大河波浪激潼關，青兕胡爲伏此山。","遙想楚王雲夢澤，蜺旌羽蓋定空還。"]', '["大河波浪激潼关，青兕胡爲伏此山。","遙想楚王云梦澤，蜺旌羽蓋定空還。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 石兕臺 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14054525-6b59-464a-a56e-998ecbfdb7bd', '陽羨雜詠十九首 講易臺', '陽羨杂詠十九首 講易台', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["年逾知命志尤堅，獨向青山更絕編。","天下有山山有水，養蒙肥遯正翛然。"]', '["年逾知命志尤堅，独向青山更絕編。","天下有山山有水，養蒙肥遯正翛然。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 講易臺 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c45ab6e9-6cb3-4857-87b4-c48311f8ea3d', '陽羨雜詠十九首 觀魚亭', '陽羨杂詠十九首 观鱼亭', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["惠施徒自學多方，謾說觀魚理未長。","不得莊生濠上旨，江湖何以見相忘。"]', '["惠施徒自学多方，謾说观鱼理未长。","不得莊生濠上旨，江湖何以见相忘。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 觀魚亭 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2220dba0-98e7-49d1-9d03-0912fd030a58', '陽羨雜詠十九首 綠雲亭', '陽羨杂詠十九首 綠云亭', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["六月清涼綠樹陰，小亭高臥滌煩襟。","羲皇向上何人到，永日時時弄素琴。"]', '["六月清涼綠樹陰，小亭高臥滌煩襟。","羲皇向上何人到，永日时时弄素琴。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 綠雲亭 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce4483a8-143d-482d-88b8-40b3247c9ad6', '陽羨雜詠十九首 清輝堂', '陽羨杂詠十九首 清輝堂', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["野人心地本無機，爲愛茅簷倚翠微。","盡日尊前誰是客，秋山含水有清輝。"]', '["野人心地本無機，爲愛茅簷倚翠微。","尽日尊前誰是客，秋山含水有清輝。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 清輝堂 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c998f57-01cf-4aa1-bc2f-eaa34135cde5', '陽羨雜詠十九首 觀妙庵', '陽羨杂詠十九首 观妙庵', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["妙理難觀旨甚深，欲知無欲是無心。","茅庵不異人間世，河上真人自可尋。"]', '["妙理难观旨甚深，欲知無欲是無心。","茅庵不異人间世，河上真人自可尋。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 觀妙庵 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36aa1b8b-216c-4585-b643-8c7ba73aaf15', '陽羨雜詠十九首 西陽亭', '陽羨杂詠十九首 西陽亭', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["隔林殘日照孤亭，玄[晏]先生酒未醒。","入夜莫愁迷下路，昔人猶在逐流螢。"]', '["隔林殘日照孤亭，玄[晏]先生酒未醒。","入夜莫愁迷下路，昔人猶在逐流螢。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 西陽亭 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c3232f-d3e4-4b94-b8e5-512c5c8b999b', '陽羨雜詠十九首 弄雲亭', '陽羨杂詠十九首 弄云亭', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["自知無業致吾君，只向春山弄白雲。","已共此山私斷當，不須轉轍重移文。"]', '["自知無業致吾君，只向春山弄白云。","已共此山私斷當，不須轉轍重移文。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 弄雲亭 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad6c32b3-a437-4571-912a-4fdda5bdf8fd', '陽羨雜詠十九首 伏龜堂', '陽羨杂詠十九首 伏龟堂', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["盤崖蹙縮似靈龜，鬼谷先生隱遁時。","不獨卷懷經世志，白雲流水是心期。"]', '["盤崖蹙縮似靈龟，鬼谷先生隐遁时。","不独卷懷經世志，白云流水是心期。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 伏龜堂 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcb67ad9-7fc7-41a8-a309-bf750154b940', '陽羨雜詠十九首 桃花谷', '陽羨杂詠十九首 桃花谷', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["君陽山下足春風，滿谷仙桃照水紅。","何必武陵源上去，澗邊好過落花中。"]', '["君陽山下足春风，满谷仙桃照水紅。","何必武陵源上去，澗邊好過落花中。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 桃花谷 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24a890c4-ba5a-4015-9f0a-ee9d090cf577', '陽羨雜詠十九首 含桃圃', '陽羨杂詠十九首 含桃圃', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["小圃初晴風露光，含桃花發滿山香。","看花對酒心無事，倍覺春來白日長。"]', '["小圃初晴风露光，含桃花發满山香。","看花对酒心無事，倍覺春来白日长。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 含桃圃 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9341ff8a-0a80-4ada-b691-cf807756f540', '陽羨雜詠十九首 茗坡', '陽羨杂詠十九首 茗坡', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["二月山家穀雨天，半坡芳茗露華鮮。","春醒酒病兼消渴，惜取新芽旋摘煎。"]', '["二月山家穀雨天，半坡芳茗露华鲜。","春醒酒病兼消渴，惜取新芽旋摘煎。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 茗坡 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6df65f7d-a903-47ef-b862-6fe3c40e6ebc', '陽羨雜詠十九首 松嶺', '陽羨杂詠十九首 松嶺', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["嶺上青松手自栽，已能蒼翠映莓苔。","歲寒本是君家事，好送清風月下來。"]', '["嶺上青松手自栽，已能蒼翠映莓苔。","歲寒本是君家事，好送清风月下来。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 松嶺 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae3a3d33-932e-4691-a17a-cacfe9c6dbc7', '陽羨雜詠十九首 桃溪', '陽羨杂詠十九首 桃溪', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["芳草霏霏遍地齊，桃花脉脉自成谿。","也知百舌多言語，任向春風盡意啼。"]', '["芳草霏霏遍地齊，桃花脉脉自成谿。","也知百舌多言語，任向春风尽意啼。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 桃溪 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02dcd9ba-5798-428a-bfa1-0014f397bba4', '陽羨雜詠十九首 李徑', '陽羨杂詠十九首 李徑', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["一徑穠芳萬蘂攢，風吹雨打未摧殘。","憐君盡向高枝發，應爲行人要整冠。"]', '["一徑穠芳万蘂攢，风吹雨打未摧殘。","怜君尽向高枝發，應爲行人要整冠。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 李徑 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9d20f81-2971-483f-a8a0-976229f31a78', '陽羨雜詠十九首 鴻盤', '陽羨杂詠十九首 鴻盤', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["落落飛鴻漸始盤，青雲起處剩須看。","如今天路多矰繳，縱使銜蘆去也難。"]', '["落落飞鴻漸始盤，青云起处剩須看。","如今天路多矰繳，縱使銜蘆去也难。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 鴻盤 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ddc6155-8760-4ca6-b1f0-7d8a8427202c', '陽羨雜詠十九首 偃月嶺', '陽羨杂詠十九首 偃月嶺', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["山嶺依稀偃月形，數層倚石疊空青。","幾迴雪夜寒光積，直似金光照戶庭。"]', '["山嶺依稀偃月形，數層倚石叠空青。","幾迴雪夜寒光積，直似金光照戶庭。"]', '诗', 'shi', '', NULL, '陽羨雜詠十九首 偃月嶺 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e6d77e-c59c-4936-ab38-0438aa343531', '寄{巩/言}光上人', '寄{巩/言}光上人', '0342516d-ff26-4911-be34-fff98e49cfd0', '唐', '["筆下龍蛇似有神，天池雷雨變逡巡。","寄言昔日不龜手，應念江頭洴澼人。"]', '["笔下龙蛇似有神，天池雷雨变逡巡。","寄言昔日不龟手，應念江头洴澼人。"]', '诗', 'shi', '', NULL, '寄{巩/言}光上人 陸希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9530bc5-739e-463e-9443-e6d2f962b859', '喜杜荀鶴及第', '喜杜荀鹤及第', '1a6b49b1-9ee3-45c2-abcb-1a913fe64f2e', '唐', '["深巖貧復病，榜到見君名。","貧病渾如失，山川頓覺清。","一春新酒興，四海舊詩聲。","日使能吟者，西來步步輕。"]', '["深巖貧复病，榜到见君名。","貧病渾如失，山川頓覺清。","一春新酒兴，四海旧诗声。","日使能吟者，西来步步轻。"]', '诗', 'shi', '', NULL, '喜杜荀鶴及第 李昭象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c273f671-d8df-4616-82ab-fd76a4e56412', '赴舉出山留寄山居鄭參軍', '赴舉出山留寄山居鄭參軍', '1a6b49b1-9ee3-45c2-abcb-1a913fe64f2e', '唐', '["還如費冠卿，向此振高名。","肯羨魚鬚美，長誇鶴氅輕。","理琴寒指倦，試藥黑髭生。","時泰難雲臥，隨看急詔行。"]', '["還如費冠卿，向此振高名。","肯羨鱼鬚美，长誇鹤氅轻。","理琴寒指倦，試藥黑髭生。","时泰难云臥，隨看急詔行。"]', '诗', 'shi', '', NULL, '赴舉出山留寄山居鄭參軍 李昭象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ad567df-9680-46a8-86f8-f15ee202e990', '題顧正字谿居', '題顧正字谿居', '1a6b49b1-9ee3-45c2-abcb-1a913fe64f2e', '唐', '["高敞吟軒近釣灣，塵中來似出人間。","若教明月休生桂，應得危時共掩關。","春酒夜棊難放客，短籬疎竹不遮山。","莫誇恬淡勝榮祿，雁引行高未許閑。"]', '["高敞吟軒近釣灣，塵中来似出人间。","若教明月休生桂，應得危时共掩关。","春酒夜棊难放客，短籬疎竹不遮山。","莫誇恬淡勝榮祿，雁引行高未許闲。"]', '诗', 'shi', '', NULL, '題顧正字谿居 李昭象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c3a8555-4d37-4f36-ae6d-a043f6e71302', '寄獻山中顧公員外', '寄獻山中顧公員外', '1a6b49b1-9ee3-45c2-abcb-1a913fe64f2e', '唐', '["抽却朝簪著釣蓑，近來聲迹轉巍峩。","祥麟避網雖山野，丹鳳銜書即薜蘿。","乍隱文章情更逸，久閑經濟術翻多。","深慙未副吹噓力，竟困風埃爭奈何。"]', '["抽却朝簪著釣蓑，近来声迹轉巍峩。","祥麟避網雖山野，丹鳳銜书即薜蘿。","乍隐文章情更逸，久闲經濟術翻多。","深慙未副吹噓力，竟困风埃爭奈何。"]', '诗', 'shi', '', NULL, '寄獻山中顧公員外 李昭象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ed9d896-ba61-4976-bd43-d78f2b60c2e1', '山中寄崔諫議', '山中寄崔諫議', '1a6b49b1-9ee3-45c2-abcb-1a913fe64f2e', '唐', '["半生猨鳥共山居，吟月吟風兩鬢疎。","新句未嘗忘教化，上才爭忍不吹噓。","全家欲去干戈後，大國中興禮樂初。","從此升騰休說命，秪希公道數封書。"]', '["半生猨鸟共山居，吟月吟风兩鬢疎。","新句未嘗忘教化，上才爭忍不吹噓。","全家欲去干戈後，大国中兴禮乐初。","從此升腾休说命，秪希公道數封书。"]', '诗', 'shi', '', NULL, '山中寄崔諫議 李昭象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b182de3-f12c-43dd-808f-2bc42a3d7d0a', '學仙詞寄顧雲', '学仙词寄顧云', '1a6b49b1-9ee3-45c2-abcb-1a913fe64f2e', '唐', '["記得初傳九轉方，碧雲峰下祝虛皇。","丹砂未熟心徒切，白日難留鬢欲蒼。","無路洞天尋穆滿，有時人世美劉郎。","仙人恩重何由報，焚盡星壇午夜香。"]', '["記得初傳九轉方，碧云峰下祝虛皇。","丹砂未熟心徒切，白日难留鬢欲蒼。","無路洞天尋穆满，有时人世美劉郎。","仙人恩重何由報，焚尽星壇午夜香。"]', '诗', 'shi', '', NULL, '學仙詞寄顧雲 李昭象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1687cdb4-4e08-4573-8b9e-a20e5d811564', '寄尉遲侍御', '寄尉遲侍御', '1a6b49b1-9ee3-45c2-abcb-1a913fe64f2e', '唐', '["我眠青嶂弄澄潭，君戴貂蟬白玉篸。","應向謝公樓上望，九華山色在西南。"]', '["我眠青嶂弄澄潭，君戴貂蟬白玉篸。","應向謝公楼上望，九华山色在西南。"]', '诗', 'shi', '', NULL, '寄尉遲侍御 李昭象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4d9dd37-c469-4587-be44-f3b7d15fa9cd', '招西洞道者', '招西洞道者', '1a6b49b1-9ee3-45c2-abcb-1a913fe64f2e', '唐', '["危峰抹黛夾晴川，樹簇紅英草碧煙。","樵客雲僧兩無事，此中堪去覓靈仙。"]', '["危峰抹黛夾晴川，樹簇紅英草碧煙。","樵客云僧兩無事，此中堪去覓靈仙。"]', '诗', 'shi', '', NULL, '招西洞道者 李昭象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a47958f5-3dba-4ef8-abca-4c0eafbfb390', '句', '句', '1a6b49b1-9ee3-45c2-abcb-1a913fe64f2e', '唐', '["投文得仕而今少，佩印還家古所榮。"]', '["投文得仕而今少，佩印還家古所榮。"]', '诗', 'shi', '', NULL, '句 李昭象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71f45efb-b1f0-4ca9-af27-f5eaefb6b872', '夏雨', '夏雨', '9a23bff2-b883-4702-bb77-a8084c235acb', '唐', '["非惟消旱暑，且喜救生民。","天地如蒸濕，園林似却春。","洗風清枕簟，換夜失埃塵。","又作豐年望，田夫笑向人。"]', '["非惟消旱暑，且喜救生民。","天地如蒸濕，园林似却春。","洗风清枕簟，換夜失埃塵。","又作豐年望，田夫笑向人。"]', '诗', 'shi', '', NULL, '夏雨 王駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a0693c-971f-4f3d-959d-01dcf02f00f8', '古意', '古意', '9a23bff2-b883-4702-bb77-a8084c235acb', '唐', '["夫戍蕭關妾在吳，西風吹妾妾憂夫。","一行書信千行淚，寒到君邊衣到無。"]', '["夫戍蕭关妾在吳，西风吹妾妾憂夫。","一行书信千行泪，寒到君邊衣到無。"]', '诗', 'shi', '', NULL, '古意 王駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3e0e059-b731-486e-9932-4e410ca59707', '社日', '社日', '9a23bff2-b883-4702-bb77-a8084c235acb', '唐', '["鵝湖山下稻粱肥，豚柵雞棲半掩扉。","桑柘影斜春社散，家家扶得醉人歸。"]', '["鵝湖山下稻粱肥，豚柵雞棲半掩扉。","桑柘影斜春社散，家家扶得醉人归。"]', '诗', 'shi', '', NULL, '社日 王駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef12d1aa-b50f-4bf6-a5e1-b1c3a92aecab', '雨晴', '雨晴', '9a23bff2-b883-4702-bb77-a8084c235acb', '唐', '["雨前初見花間蘂，雨後兼無葉裏花。","蛺蝶飛來過墻去，却疑春色在鄰家。"]', '["雨前初见花间蘂，雨後兼無葉裏花。","蛺蝶飞来過墻去，却疑春色在鄰家。"]', '诗', 'shi', '', NULL, '雨晴 王駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8711393b-5b9e-490f-9f61-6d30e5b101b2', '亂後曲江', '亂後曲江', '9a23bff2-b883-4702-bb77-a8084c235acb', '唐', '["憶昔爭遊曲水濱，未春長有探春人。","遊春人盡空池在，直至春深不似春。"]', '["憶昔爭游曲水濱，未春长有探春人。","游春人尽空池在，直至春深不似春。"]', '诗', 'shi', '', NULL, '亂後曲江 王駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a75d708-2ce5-4b0f-8108-a1c67e394bf5', '過故友居', '過故友居', '9a23bff2-b883-4702-bb77-a8084c235acb', '唐', '["鄰笛寒吹日落初，舊居今已別人居。","亂來兒姪皆分散，惆悵僧房認得書。"]', '["鄰笛寒吹日落初，旧居今已別人居。","亂来兒姪皆分散，惆悵僧房認得书。"]', '诗', 'shi', '', NULL, '過故友居 王駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0cd0195-afa4-4392-b8f1-a67da7843bc9', '上裴侍郎', '上裴侍郎', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["青衿七十牓三年，建禮含香次第遷。","珠彩下連星錯落，桂花曾對月嬋娟。","玉經磨琢多成器，劍拔沈埋更倚天。","應念銜恩最深者，春來爲壽拜尊前。"]', '["青衿七十牓三年，建禮含香次第遷。","珠彩下連星錯落，桂花曾对月嬋娟。","玉經磨琢多成器，劍拔沈埋更倚天。","應念銜恩最深者，春来爲壽拜尊前。"]', '诗', 'shi', '', NULL, '上裴侍郎 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a5c5ce7-5788-4286-8b7d-d7db10c8a7b3', '悼亡', '悼亡', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["春來得病夏來加，深掩粧窗臥碧紗。","爲怯暗藏秦女扇，怕驚愁度阿香車。","腰肢暗想風欺柳，粉態難忘露洗花。","今日青門葬君處，亂蟬衰草夕陽斜。"]', '["春来得病夏来加，深掩粧窗臥碧紗。","爲怯暗藏秦女扇，怕驚愁度阿香车。","腰肢暗想风欺柳，粉態难忘露洗花。","今日青门葬君处，亂蟬衰草夕陽斜。"]', '诗', 'shi', '', NULL, '悼亡 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1529dd5b-e0dc-4dd0-9712-b220d6247679', '惆悵詩十二首 一', '惆悵诗十二首 一', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["八蠶薄絮鴛鴦綺，半夜佳期並枕眠。","鐘動紅娘喚歸去，對人勻淚拾金鈿。"]', '["八蠶薄絮鴛鴦綺，半夜佳期並枕眠。","鐘动紅娘喚归去，对人勻泪拾金鈿。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 一 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67a3b70f-73a9-464c-9b49-2a47f65418f5', '惆悵詩十二首 二', '惆悵诗十二首 二', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["李夫人病已經秋，漢武看來不舉頭。","得所濃華銷歇盡，楚魂湘血一生休。"]', '["李夫人病已經秋，漢武看来不舉头。","得所濃华銷歇尽，楚魂湘血一生休。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 二 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('513394b7-8453-4433-b57a-fadc5741b1a4', '惆悵詩十二首 三', '惆悵诗十二首 三', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["謝家池館花籠月，蕭寺房廊竹颭風。","夜半酒醒憑檻立，所思多在別離中。"]', '["謝家池館花籠月，蕭寺房廊竹颭风。","夜半酒醒憑檻立，所思多在別離中。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 三 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2bbbd83-77c2-4da0-910b-4d0e7501f968', '惆悵詩十二首 四', '惆悵诗十二首 四', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["隋師戰艦欲亡陳，國破應難保此身。","訣別徐郎淚如雨，鏡鸞分後屬何人。"]', '["隋師戰艦欲亡陳，国破應难保此身。","訣別徐郎泪如雨，镜鸾分後屬何人。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 四 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57752e11-7bd5-4a19-9ac7-ff9dbc9315e2', '惆悵詩十二首 五', '惆悵诗十二首 五', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["七夕瓊筵隨事陳，兼花連蔕共傷神。","蜀王殿裏三更月，不見驪山私語人。"]', '["七夕瓊筵隨事陳，兼花連蔕共傷神。","蜀王殿裏三更月，不见驪山私語人。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 五 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61089543-ac89-40b9-9937-941e2dea2d3f', '惆悵詩十二首 六', '惆悵诗十二首 六', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["夜寒春病不勝懷，玉瘦花啼萬事乖。","薄倖檀郎斷芳信，驚嗟猶夢合歡鞋。"]', '["夜寒春病不勝懷，玉瘦花啼万事乖。","薄倖檀郎斷芳信，驚嗟猶梦合歡鞋。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 六 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f92fe766-715c-4c2f-a670-26733f93ae86', '惆悵詩十二首 七', '惆悵诗十二首 七', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["嗚咽離聲管吹秋，妾身今日爲君休。","齊奴不說平生事，忍看花枝謝玉樓。"]', '["嗚咽離声管吹秋，妾身今日爲君休。","齊奴不说平生事，忍看花枝謝玉楼。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 七 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19f59a00-3f8e-40fa-8da9-82006389ae09', '惆悵詩十二首 八', '惆悵诗十二首 八', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["青絲一綹墮雲鬟，金翦刀鳴不忍看。","持謝君王寄幽怨，可能從此住人間。"]', '["青絲一綹墮云鬟，金翦刀鳴不忍看。","持謝君王寄幽怨，可能從此住人间。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 八 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a78c4ea2-8b9a-45a1-bf78-0d359d7f05ba', '惆悵詩十二首 九', '惆悵诗十二首 九', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["陳宮興廢事難期，三閣空餘綠草基。","狎客淪亡麗華死，他年江令獨來時。"]', '["陳宮兴廢事难期，三閣空餘綠草基。","狎客淪亡丽华死，他年江令独来时。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 九 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a96ed3a-d4cb-4a50-bc67-e1caada90086', '惆悵詩十二首 十', '惆悵诗十二首 十', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["晨肇重來路已迷，碧桃花謝武陵溪。","仙山目斷無尋處，流水潺湲日漸西。"]', '["晨肇重来路已迷，碧桃花謝武陵溪。","仙山目斷無尋处，流水潺湲日漸西。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 十 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec9adba0-d22c-4eec-ab55-fdf3db6c6522', '惆悵詩十二首 十一', '惆悵诗十二首 十一', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["少卿降北子卿還，朔野離觴慘別顏。","却到茂陵唯一慟，節毛零落鬢毛斑。"]', '["少卿降北子卿還，朔野離觴慘別顏。","却到茂陵唯一慟，節毛零落鬢毛斑。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 十一 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76c71596-50f6-4177-9271-78ac738e5156', '惆悵詩十二首 十二', '惆悵诗十二首 十二', '991df421-3693-47c3-a909-ff2078f5361e', '唐', '["夢裏分明入漢宮，覺來燈背錦屏空。","紫臺月落關山曉，腸斷君恩信畫工。"]', '["梦裏分明入漢宮，覺来灯背錦屏空。","紫台月落关山晓，腸斷君恩信畫工。"]', '诗', 'shi', '', NULL, '惆悵詩十二首 十二 王渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6600c2b0-ba46-44c2-a192-c7f572af908f', '江上雨', '江上雨', '0249c25e-f9cf-4154-af1d-0c8dd6f129ca', '唐', '["非不欲前去，此情非自由。","星辰照何處，風雨送涼秋。","寒鎖空江夢，聲隨黃葉愁。","蕭蕭猶未已，早晚去蘋洲。"]', '["非不欲前去，此情非自由。","星辰照何处，风雨送涼秋。","寒鎖空江梦，声隨黄葉愁。","蕭蕭猶未已，早晚去蘋洲。"]', '诗', 'shi', '', NULL, '江上雨 戴司顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4c4aa1a-063e-41fa-a7da-5caf06bcb263', '塞上', '塞上', '0249c25e-f9cf-4154-af1d-0c8dd6f129ca', '唐', '["空蹟晝蒼茫，沙腥古戰場。","逢春多霰雪，生計在牛羊。","冷角吹鄉淚，乾榆落夢牀。","從來山水客，誰謂到漁陽。"]', '["空蹟晝蒼茫，沙腥古戰場。","逢春多霰雪，生計在牛羊。","冷角吹乡泪，乾榆落梦牀。","從来山水客，誰謂到漁陽。"]', '诗', 'shi', '', NULL, '塞上 戴司顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e453ccc-033a-460c-bc34-6297096d2a3e', '句', '句', '0249c25e-f9cf-4154-af1d-0c8dd6f129ca', '唐', '["遠來朝鳳闕，歸去戀元侯。"]', '["远来朝鳳闕，归去戀元侯。"]', '诗', 'shi', '', NULL, '句 戴司顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6225148-9783-4fae-a11a-638a836c3345', '投謝錢武肅', '投謝錢武肅', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["東門上相好知音，數盡臺前郭隗金。","累重雖然容食椹，力微無計報焚林。","弊貂不稱芙蓉幕，衰朽仍慚玳瑁簪。","十里溪光一山月，可堪從此負歸心。"]', '["东门上相好知音，數尽台前郭隗金。","累重雖然容食椹，力微無計報焚林。","弊貂不稱芙蓉幕，衰朽仍慚玳瑁簪。","十里溪光一山月，可堪從此負归心。"]', '诗', 'shi', '', NULL, '投謝錢武肅 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7300777-f722-492e-9120-8b302e16f40e', '客路', '客路', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["人寰急景如波委，客路浮雲似蓋輕。","回首故山天外碧，十年無計却歸耕。"]', '["人寰急景如波委，客路浮云似蓋轻。","回首故山天外碧，十年無計却归耕。"]', '诗', 'shi', '', NULL, '客路 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce95ef0c-d519-4048-a95d-6331cbc069e1', '南徐題友人郊居', '南徐題友人郊居', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["門前樵徑連江寺，岸下漁磯繫海槎。","待到秋深好時節，與君長醉隱侯家。"]', '["门前樵徑連江寺，岸下漁磯繫海槎。","待到秋深好时節，與君长醉隐侯家。"]', '诗', 'shi', '', NULL, '南徐題友人郊居 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('def00dc7-7fef-4d6f-8608-fadfd4833412', '讀度人經寄鄭仁表', '读度人經寄鄭仁表', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["身雖一旦塵中老，名擬三清會裏題。","二午九齋餘日在，請君相伴醉如泥。"]', '["身雖一旦塵中老，名擬三清會裏題。","二午九斋餘日在，請君相伴醉如泥。"]', '诗', 'shi', '', NULL, '讀度人經寄鄭仁表 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f0a9186-8536-4c5b-9fc6-ad83a41eea17', '秋日聽僧彈琴', '秋日听僧彈琴', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["金徽玉軫韻泠然，言下浮生指下泉。","恰稱秋風西北起，一時吹入碧湘煙。"]', '["金徽玉軫韻泠然，言下浮生指下泉。","恰稱秋风西北起，一时吹入碧湘煙。"]', '诗', 'shi', '', NULL, '秋日聽僧彈琴 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64db94a8-e2ac-4d22-bb87-89cdf4d9c655', '賈誼', '賈誼', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["扶持一疏滿遺編，漢陛前頭正少年。","誰道恃才輕絳灌，却將惆悵弔湘川。"]', '["扶持一疏满遺編，漢陛前头正少年。","誰道恃才轻絳灌，却將惆悵弔湘川。"]', '诗', 'shi', '', NULL, '賈誼 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72547543-820f-4314-ae4a-63bca51c0e94', '春雪', '春雪', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["雪霽凝光入坐寒，天明猶自臥袁安。","貂裘穿後鶴氅敝，自此風流不足看。"]', '["雪霽凝光入坐寒，天明猶自臥袁安。","貂裘穿後鹤氅敝，自此风流不足看。"]', '诗', 'shi', '', NULL, '春雪 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c18f51bc-a96d-4c5f-81cb-698da227a65a', '衰柳', '衰柳', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["金風漸利露珠團，廣陌長堤黛色殘。","水殿狂遊隋煬帝，一千餘里可堪看。"]', '["金风漸利露珠團，廣陌长堤黛色殘。","水殿狂游隋煬帝，一千餘里可堪看。"]', '诗', 'shi', '', NULL, '衰柳 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b24e45-1bc4-4181-bec5-5f9b899e1665', '鳳仙花', '鳳仙花', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["香紅嫩綠正開時，冷蝶飢蜂兩不知。","此際最宜何處看，朝陽初上碧梧枝。"]', '["香紅嫩綠正开时，冷蝶飢蜂兩不知。","此際最宜何处看，朝陽初上碧梧枝。"]', '诗', 'shi', '', NULL, '鳳仙花 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06069c87-167e-4ed7-9ea7-dd39018557e6', '金錢花', '金錢花', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["淺絳濃香幾朵勻，日鎔金鑄萬家新。","堪疑劉寵遺芳在，不許山陰父老貧。"]', '["淺絳濃香幾朵勻，日鎔金鑄万家新。","堪疑劉寵遺芳在，不許山陰父老貧。"]', '诗', 'shi', '', NULL, '金錢花 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('780f813e-5083-4589-91a4-fba8b1093425', '錢塘鶴', '錢塘鹤', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["人間路靄青天半，鼇岫雲生碧海涯。","雖抱雕籠密扃鑰，可能長在叔倫家。"]', '["人间路靄青天半，鼇岫云生碧海涯。","雖抱雕籠密扃鑰，可能长在叔倫家。"]', '诗', 'shi', '', NULL, '錢塘鶴 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08cccaa5-b327-45e6-8ffa-e1c23cb57a2a', '句', '句', '0e00f753-ea09-4b95-951c-4ba61ff3a886', '唐', '["爲惜苔錢妨換砌，因憐山色旋開尊。","高閣煙霞禪客睡，滿城塵土世人忙。","五龍金角向星斗，三洞玉音愁鬼神。","蒲草薄裁連蒂白，臙脂濃染半葩紅。"]', '["爲惜苔錢妨換砌，因怜山色旋开尊。","高閣煙霞禪客睡，满城塵土世人忙。","五龙金角向星斗，三洞玉音愁鬼神。","蒲草薄裁連蒂白，臙脂濃染半葩紅。"]', '诗', 'shi', '', NULL, '句 吳仁璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('368046e7-dbdf-49ce-a257-5cab88ef84e7', '奉試麥壟多秀色', '奉試麦壟多秀色', '2d8ba47a-ebb1-4b40-99ba-85ab7aac44b6', '唐', '["南陌生岐穗，農家樂事多。","塍畦交茂綠，苗實際清和。","日布玲瓏影，風翻浩蕩波。","來牟知帝力，含哺有衢歌。"]', '["南陌生岐穗，農家乐事多。","塍畦交茂綠，苗實際清和。","日布玲瓏影，风翻浩蕩波。","来牟知帝力，含哺有衢歌。"]', '诗', 'shi', '', NULL, '奉試麥壟多秀色 汪極 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c8ff73f-54be-4139-bd74-11429936dc7b', '下第戲狀元崔昭緯', '下第戲狀元崔昭緯', 'bb3aa3f2-888f-4b5a-97da-0104e38f8deb', '唐', '["千里江山陪驥尾，五更風水失龍鱗。","昨夜浣花溪上雨，綠楊芳草爲何人。"]', '["千里江山陪驥尾，五更风水失龙鱗。","昨夜浣花溪上雨，綠楊芳草爲何人。"]', '诗', 'shi', '', NULL, '下第戲狀元崔昭緯 張曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9bb8fc-e694-459b-aa97-2a4f892e1e87', '贈天台王處士', '贈天台王处士', 'b709dc91-7f99-4b89-b9e3-1c0caf1811e5', '唐', '["深隱天台不記秋，琴臺長別一何愁。","茶煙巖外雲初起，新月潭心釣未收。","映宇異花叢發好，穿松孤鶴一聲幽。","赤城不掩高宗夢，寧久懸冠枕瀑流。"]', '["深隐天台不記秋，琴台长別一何愁。","茶煙巖外云初起，新月潭心釣未收。","映宇異花叢發好，穿松孤鹤一声幽。","赤城不掩高宗梦，寧久懸冠枕瀑流。"]', '诗', 'shi', '', NULL, '贈天台王處士 林嵩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eaf97fd-82bb-4651-9dde-9a5a6f78182c', '春宮怨', '春宮怨', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["早被嬋娟誤，欲妝臨鏡慵。","承恩不在貌，教妾若爲容。","風暖鳥聲碎，日高花影重。","年年越溪女，相憶採芙蓉。"]', '["早被嬋娟誤，欲妝臨镜慵。","承恩不在貌，教妾若爲容。","风暖鸟声碎，日高花影重。","年年越溪女，相憶採芙蓉。"]', '诗', 'shi', '', NULL, '春宮怨 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b605213-400a-4fae-8b02-d5f020fff1f9', '訪道者不遇', '訪道者不遇', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["寂寂白雲門，尋真不遇真。","祗應松上鶴，便是洞中人。","藥圃花香異，沙泉鹿跡新。","題詩留姓字，他日此相親。"]', '["寂寂白云门，尋真不遇真。","祗應松上鹤，便是洞中人。","藥圃花香異，沙泉鹿跡新。","題诗留姓字，他日此相親。"]', '诗', 'shi', '', NULL, '訪道者不遇 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f48efb6-6e46-4294-8a8c-0dfabe1c926b', '送人遊吳', '送人游吳', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["君到姑蘇見，人家盡枕河。","古宮閑地少，水港小橋多。","夜市賣菱藕，春船載綺羅。","遙知未眠月，鄉思在漁歌。"]', '["君到姑蘇见，人家尽枕河。","古宮闲地少，水港小橋多。","夜市賣菱藕，春船載綺羅。","遙知未眠月，乡思在漁歌。"]', '诗', 'shi', '', NULL, '送人遊吳 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec25b07d-83a2-4fc7-9b44-a2d021f3c61d', '送陳昈歸麻川', '送陳昈归麻川', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["麻川清見底，似入武陵溪。","兩岸山相向，三春鳥亂啼。","酒旗和柳動，僧屋與雲齊。","即此吾鄉路，懷君夢不迷。"]', '["麻川清见底，似入武陵溪。","兩岸山相向，三春鸟亂啼。","酒旗和柳动，僧屋與云齊。","即此吾乡路，懷君梦不迷。"]', '诗', 'shi', '', NULL, '送陳昈歸麻川 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3c0ea30-598d-4d92-ab6e-9c45bff99661', '出山', '出山', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["病眼看春牓，文場公道開。","朋人登第盡，白髮出山來。","處世曾無過，惟天合是媒。","長安不覺遠，期遂一名迴。"]', '["病眼看春牓，文場公道开。","朋人登第尽，白髮出山来。","处世曾無過，惟天合是媒。","长安不覺远，期遂一名迴。"]', '诗', 'shi', '', NULL, '出山 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3977c028-671d-4e5b-b03c-42c156de4ee1', '浙中逢詩友', '浙中逢诗友', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["到處有同人，多爲賦與文。","詩中難得友，湖畔喜逢君。","凍把城根雪，風開嶽面雲。","苦吟吟不足，爭忍話離羣。"]', '["到处有同人，多爲賦與文。","诗中难得友，湖畔喜逢君。","凍把城根雪，风开嶽面云。","苦吟吟不足，爭忍話離羣。"]', '诗', 'shi', '', NULL, '浙中逢詩友 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb18e4f7-84a7-4ab9-a170-e53f8f769697', '送友遊吳越', '送友游吳越', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["去越從吳過，吳疆與越連。","有園多種橘，無水不生蓮。","夜市橋邊火，春風寺外船。","此中偏重客，君去必經年。"]', '["去越從吳過，吳疆與越連。","有园多種橘，無水不生蓮。","夜市橋邊火，春风寺外船。","此中偏重客，君去必經年。"]', '诗', 'shi', '', NULL, '送友遊吳越 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0c19ec0-06b5-457e-9325-405c59c76dfb', '出常山界使回有寄', '出常山界使回有寄', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["自小即南北，未如今日離。","封疆初盡處，人使却回時。","開口有所忌，此心無以爲。","行行復垂淚，不稱是男兒。"]', '["自小即南北，未如今日離。","封疆初尽处，人使却回时。","开口有所忌，此心無以爲。","行行复垂泪，不稱是男兒。"]', '诗', 'shi', '', NULL, '出常山界使回有寄 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf6b268-1434-4b9f-b12e-68c5836e72ab', '經廢宅', '經廢宅', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["人生當貴盛，修德可延之。","不慮有今日，爭教無破時。","蘚斑題字壁，花發帶巢枝。","何況蒿原上，荒墳與折碑。"]', '["人生當貴盛，修德可延之。","不慮有今日，爭教無破时。","蘚斑題字壁，花發带巢枝。","何況蒿原上，荒墳與折碑。"]', '诗', 'shi', '', NULL, '經廢宅 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b8aac21-df6b-451f-96d3-3303f1971874', '登天台寺', '登天台寺', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一到天台寺，高低景旋生。","共僧巖上坐，見客海邊行。","野色人耕破，山根浪打鳴。","忙時向閑處，不覺有閑情。"]', '["一到天台寺，高低景旋生。","共僧巖上坐，见客海邊行。","野色人耕破，山根浪打鳴。","忙时向闲处，不覺有闲情。"]', '诗', 'shi', '', NULL, '登天台寺 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fc179c0-ecd1-4fa6-9ebd-f39b40c315b5', '途中春', '途中春', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["馬上覽春色，丈夫慙淚垂。","一生看却老，五字未逢知。","酒力不能久，愁根無可醫。","明年到今日，公道與誰期。"]', '["马上覽春色，丈夫慙泪垂。","一生看却老，五字未逢知。","酒力不能久，愁根無可醫。","明年到今日，公道與誰期。"]', '诗', 'shi', '', NULL, '途中春 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0614bcec-5657-44c7-b153-220240a21948', '入關歷陽道中却寄舍弟', '入关歷陽道中却寄舍弟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["求名日苦辛，日望日榮親。","落葉山中路，秋霖馬上人。","晨昏知汝道，詩酒衛吾身。","自笑拋麋鹿，長安擬醉春。"]', '["求名日苦辛，日望日榮親。","落葉山中路，秋霖马上人。","晨昏知汝道，诗酒衛吾身。","自笑拋麋鹿，长安擬醉春。"]', '诗', 'shi', '', NULL, '入關歷陽道中却寄舍弟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecc59628-86cd-4a41-9d6b-31398e405830', '贈歐陽明府', '贈歐陽明府', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["賢宰宰斯邑，政聞閭里間。","都緣民訟少，長覺吏徒閑。","帆落樽前浦，鐘鳴枕上山。","回舟却惆悵，數宿釣魚灣。"]', '["賢宰宰斯邑，政闻閭里间。","都緣民訟少，长覺吏徒闲。","帆落樽前浦，鐘鳴枕上山。","回舟却惆悵，數宿釣鱼灣。"]', '诗', 'shi', '', NULL, '贈歐陽明府 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab7d5d6e-a749-4393-a7b3-403e09c2bce5', '贈臨上人', '贈臨上人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["不計禪兼律，終須入悟門。","解空非有自，所得是無言。","眼豁浮生夢，心澄大道源。","今來習師者，多鏁教中猿。"]', '["不計禪兼律，終須入悟门。","解空非有自，所得是無言。","眼豁浮生梦，心澄大道源。","今来習師者，多鏁教中猿。"]', '诗', 'shi', '', NULL, '贈臨上人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('664c1d81-714c-4d8f-9481-1f69c86dbda7', '題戰島僧居', '題戰島僧居', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["師愛無塵地，江心島上居。","接船求化慣，登陸赴齋疎。","載士春栽樹，拋生日餧魚。","入雲蕭帝寺，畢竟欲何如。"]', '["師愛無塵地，江心島上居。","接船求化慣，登陸赴斋疎。","載士春栽樹，拋生日餧鱼。","入云蕭帝寺，畢竟欲何如。"]', '诗', 'shi', '', NULL, '題戰島僧居 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('661af006-05d8-4fa1-92ef-aff15bfb2f9f', '別衡州牧', '別衡州牧', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["朝別使君門，暮投江上村。","從來無舊分，臨去望何恩。","行計自不定，此心誰與論。","秋猿叫寒月，祗欲斷人魂。"]', '["朝別使君门，暮投江上村。","從来無旧分，臨去望何恩。","行計自不定，此心誰與論。","秋猿叫寒月，祗欲斷人魂。"]', '诗', 'shi', '', NULL, '別衡州牧 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a44861d-2a13-4fa1-9fa7-80d051301fb3', '送人遊江南', '送人游江南', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["滿酌勸君酒，勸君君莫辭。","能禁幾度別，即到白頭時。","晚岫無雲蔽，春帆有燕隨。","男兒兩行淚，不欲等閑垂。"]', '["满酌勸君酒，勸君君莫辞。","能禁幾度別，即到白头时。","晚岫無云蔽，春帆有燕隨。","男兒兩行泪，不欲等闲垂。"]', '诗', 'shi', '', NULL, '送人遊江南 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cbb68bc-894d-44cc-a54b-8d0ca9a776ae', '遊茅山', '游茅山', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["步步入山門，仙家鳥徑分。","漁樵不到處，麋鹿自成羣。","石面迸出水，松頭穿破雲。","道人星月下，相次禮茅君。"]', '["步步入山门，仙家鸟徑分。","漁樵不到处，麋鹿自成羣。","石面迸出水，松头穿破云。","道人星月下，相次禮茅君。"]', '诗', 'shi', '', NULL, '遊茅山 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d0b986f-9d42-437b-8997-32f45f171678', '讀友人詩卷', '读友人诗卷', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["冰齒味瑤軸，祗應神鬼知。","坐當羣靜後，吟到月沈時。","雪峽猿聲健，風檉鶴立危。","篇篇一字字，誰復更言詩。"]', '["冰齒味瑤軸，祗應神鬼知。","坐當羣静後，吟到月沈时。","雪峽猿声健，风檉鹤立危。","篇篇一字字，誰复更言诗。"]', '诗', 'shi', '', NULL, '讀友人詩卷 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('755686a4-c246-4f4a-8aa3-1ed6ed237c73', '寄從叔', '寄從叔', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["三族不當路，長年猶布衣。","苦吟天與性，直道世將非。","雁夜愁癡坐，漁鄉老憶歸。","爲儒皆可立，自是拙時機。"]', '["三族不當路，长年猶布衣。","苦吟天與性，直道世將非。","雁夜愁癡坐，漁乡老憶归。","爲儒皆可立，自是拙时機。"]', '诗', 'shi', '', NULL, '寄從叔 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bf3e4fc-67b5-47e6-8f04-91f10b60f541', '寄李溥', '寄李溥', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["如我如君者，不妨身晚成。","但從時輩笑，自得古人情。","共莫更初志，俱期立後名。","男兒且如此，何用歎平生。"]', '["如我如君者，不妨身晚成。","但從时輩笑，自得古人情。","共莫更初志，俱期立後名。","男兒且如此，何用歎平生。"]', '诗', 'shi', '', NULL, '寄李溥 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad644ef-316c-4093-8218-58ace0bc7cda', '郊居即事投李給事', '郊居即事投李給事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["無祿奉晨昏，閑居幾度春。","江湖苦吟士，天地最窮人。","書劒同三友，蓬蒿外四鄰。","相知不相薦，何以自謀身。"]', '["無祿奉晨昏，闲居幾度春。","江湖苦吟士，天地最窮人。","书劒同三友，蓬蒿外四鄰。","相知不相薦，何以自謀身。"]', '诗', 'shi', '', NULL, '郊居即事投李給事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3209a29-b661-4495-adeb-204b0b088579', '寄詩友', '寄诗友', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["別來春又春，相憶喜相親。","與我爲同志，如君能幾人。","何時吟得力，漸老事關身。","惟有前溪水，年年濯客塵。"]', '["別来春又春，相憶喜相親。","與我爲同志，如君能幾人。","何时吟得力，漸老事关身。","惟有前溪水，年年濯客塵。"]', '诗', 'shi', '', NULL, '寄詩友 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dd3d04b-5231-405c-8df1-32b785c03913', '題田翁家', '題田翁家', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["田翁真快活，婚嫁不離村。","州縣供輸罷，追隨鼓笛喧。","盤飧同老少，家計共田園。","自說身無事，應官有子孫。"]', '["田翁真快活，婚嫁不離村。","州縣供輸罷，追隨鼓笛喧。","盤飧同老少，家計共田园。","自说身無事，應官有子孫。"]', '诗', 'shi', '', NULL, '題田翁家 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63adc562-56c5-4942-ac1b-4371970a5f50', '長安冬日', '长安冬日', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["近臘饒風雪，閑房凍坐時。","書生教到此，天意轉難知。","吟苦猿三叫，形枯柏一枝。","還應公道在，未忍與山期。"]', '["近臘饒风雪，闲房凍坐时。","书生教到此，天意轉难知。","吟苦猿三叫，形枯柏一枝。","還應公道在，未忍與山期。"]', '诗', 'shi', '', NULL, '長安冬日 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a793755-5fbd-447b-91cd-3197e2bcb419', '霽後登唐興寺水閣', '霽後登唐兴寺水閣', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一雨三秋色，蕭條古寺間。","無端登水閣，有處似家山。","白日生新事，何時得暫閑。","將知老僧意，未必戀松關。"]', '["一雨三秋色，蕭條古寺间。","無端登水閣，有处似家山。","白日生新事，何时得暫闲。","將知老僧意，未必戀松关。"]', '诗', 'shi', '', NULL, '霽後登唐興寺水閣 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a072d2b4-4e1c-4397-a587-00baf9d0869d', '山中寄友人', '山中寄友人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["深山多隙地，無力及耕桑。","不是營生拙，都緣覓句忙。","破窗風翳燭，穿屋月侵牀。","吾友應相笑，辛勤道未光。"]', '["深山多隙地，無力及耕桑。","不是營生拙，都緣覓句忙。","破窗风翳燭，穿屋月侵牀。","吾友應相笑，辛勤道未光。"]', '诗', 'shi', '', NULL, '山中寄友人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c32accd-b526-401b-9b76-9f9760b7be31', '自述', '自述', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["四海欲行遍，不知終遇誰。","用心常合道，出語或傷時。","擬作閑人老，慙無識者嗤。","如今已無計，祗得苦于詩。"]', '["四海欲行遍，不知終遇誰。","用心常合道，出語或傷时。","擬作闲人老，慙無識者嗤。","如今已無計，祗得苦于诗。"]', '诗', 'shi', '', NULL, '自述 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d37fc5bd-0158-4e52-a7bb-274688287f02', '題江山寺', '題江山寺', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["江上山頭寺，景留吟客船。","遍遊銷一日，重到是何年。","沙鳥多翹足，巖僧半露肩。","爲詩多語澀，喜此得終篇。"]', '["江上山头寺，景留吟客船。","遍游銷一日，重到是何年。","沙鸟多翹足，巖僧半露肩。","爲诗多語澀，喜此得終篇。"]', '诗', 'shi', '', NULL, '題江山寺 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1871aca0-705a-4455-bbbf-3a19886913c8', '秋日旅舍臥病呈所知', '秋日旅舍臥病呈所知', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["秋色上庭枝，愁懷切向誰。","青雲無勢日，華髮有狂時。","枕上聞風雨，江南繫別離。","如何吟到此，此道不聞知。"]', '["秋色上庭枝，愁懷切向誰。","青云無勢日，华髮有狂时。","枕上闻风雨，江南繫別離。","如何吟到此，此道不闻知。"]', '诗', 'shi', '', NULL, '秋日旅舍臥病呈所知 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('010ec73b-a49e-4ab8-b373-74d281f178ea', '秋宿山館', '秋宿山館', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["山館坐待曉，夜長吟役神。","斜風吹敗葉，寒燭照愁人。","蘊蓄天然性，澆訛世惡真。","男兒出門志，不獨爲謀身。"]', '["山館坐待晓，夜长吟役神。","斜风吹敗葉，寒燭照愁人。","蘊蓄天然性，澆訛世惡真。","男兒出门志，不独爲謀身。"]', '诗', 'shi', '', NULL, '秋宿山館 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8261aa49-fb44-4912-ba0f-de93d45a11ae', '贈老僧', '贈老僧', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["衆僧尊夏臘，靈嶽遍曾登。","度水手中杖，行山溪畔藤。","心空默是印，眉白雪爲稜。","自得巡方道，棲禪老未能。"]', '["衆僧尊夏臘，靈嶽遍曾登。","度水手中杖，行山溪畔藤。","心空默是印，眉白雪爲稜。","自得巡方道，棲禪老未能。"]', '诗', 'shi', '', NULL, '贈老僧 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfe260e-7b9d-4049-9286-d8dca992910e', '別舍弟', '別舍弟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["欲住住不得，出門天氣秋。","惟知偷拭淚，不忍更回頭。","此日祗愁老，況身方遠遊。","孤寒將五字，何以動諸侯。"]', '["欲住住不得，出门天氣秋。","惟知偷拭泪，不忍更回头。","此日祗愁老，況身方远游。","孤寒將五字，何以动諸侯。"]', '诗', 'shi', '', NULL, '別舍弟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b25d54ad-5eee-44db-bf82-29f5a798090e', '雪中別詩友', '雪中別诗友', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["酒寒無小戶，請滿酌行杯。","若待雪消去，自然春到來。","出城人跡少，向暮鳥聲哀。","未遇應關命，侯門處處開。"]', '["酒寒無小戶，請满酌行杯。","若待雪消去，自然春到来。","出城人跡少，向暮鸟声哀。","未遇應关命，侯门处处开。"]', '诗', 'shi', '', NULL, '雪中別詩友 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb5cb3d-ff60-4ef0-91cb-61b829982f6a', '題嶽麓寺', '題嶽麓寺', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一簇楚江山，江山勝此難。","覓人來畫取，到處得吟看。","鶴隱松聲盡，魚沈檻影寒。","自知心未了，閑話亦多端。"]', '["一簇楚江山，江山勝此难。","覓人来畫取，到处得吟看。","鹤隐松声尽，鱼沈檻影寒。","自知心未了，闲話亦多端。"]', '诗', 'shi', '', NULL, '題嶽麓寺 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d50a21-82b8-4566-bc01-33b5816f6a93', '懷廬嶽書齋', '懷廬嶽书斋', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["長憶在廬嶽，免低塵土顏。","煮茶窗底水，採藥屋頭山。","是境皆遊遍，誰人不羨閑。","無何一名繫，引出白雲間。"]', '["长憶在廬嶽，免低塵土顏。","煮茶窗底水，採藥屋头山。","是境皆游遍，誰人不羨闲。","無何一名繫，引出白云间。"]', '诗', 'shi', '', NULL, '懷廬嶽書齋 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc402ed-a84a-40ec-a1a3-d75514b6c2ff', '題唐興寺小松', '題唐兴寺小松', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["雖小天然別，難將衆木同。","侵僧半窗月，向客滿襟風。","枝拂行苔鶴，聲分叫砌蟲。","如今未堪看，須是雪霜中。"]', '["雖小天然別，难將衆木同。","侵僧半窗月，向客满襟风。","枝拂行苔鹤，声分叫砌蟲。","如今未堪看，須是雪霜中。"]', '诗', 'shi', '', NULL, '題唐興寺小松 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f52c79e-0c51-45f5-b0cc-41c0dcccfea4', '與友人話別', '與友人話別', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["客路行多少，干人無易顏。","未成終老計，難致此身閑。","月兔走入海，日烏飛出山。","流年留不得，半在別離間。"]', '["客路行多少，干人無易顏。","未成終老計，难致此身闲。","月兔走入海，日烏飞出山。","流年留不得，半在別離间。"]', '诗', 'shi', '', NULL, '與友人話別 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9e7d25f-39ca-40ba-8472-9d5e27449dd1', '贈廬嶽隱者', '贈廬嶽隐者', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["自見來如此，未嘗離洞門。","結茅遮雨雪，採藥給晨昏。","古樹藤纏殺，春泉鹿過渾。","悠悠無一事，不似屬乾坤。"]', '["自见来如此，未嘗離洞门。","結茅遮雨雪，採藥給晨昏。","古樹藤纏殺，春泉鹿過渾。","悠悠無一事，不似屬乾坤。"]', '诗', 'shi', '', NULL, '贈廬嶽隱者 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c486f4d3-20ac-4191-b9c6-7d0fc28919ae', '懷紫閣隱者', '懷紫閣隐者', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["紫閣白雲端，雲中有地仙。","未歸蓬島上，猶隱國門前。","洞口人無跡，花陰鹿自眠。","焚香賦詩罷，星月冷遙天。"]', '["紫閣白云端，云中有地仙。","未归蓬島上，猶隐国门前。","洞口人無跡，花陰鹿自眠。","焚香賦诗罷，星月冷遙天。"]', '诗', 'shi', '', NULL, '懷紫閣隱者 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ffbe4bf-1ad9-4398-a614-0054df35be58', '題會上人院', '題會上人院', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["鼓角城中寺，師居日得閑。","必能行大道，何用在深山。","破衲新添線，空門夜不關。","心知與眼見，終取到無間。"]', '["鼓角城中寺，師居日得闲。","必能行大道，何用在深山。","破衲新添線，空门夜不关。","心知與眼见，終取到無间。"]', '诗', 'shi', '', NULL, '題會上人院 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cff0074-8a17-49d7-b673-c4cc8b03c550', '送黃補闕南遷', '送黄補闕南遷', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["得罪非天意，分明謫去身。","一心貪諫主，開口不防人。","自古有遷客，何朝無直臣。","喧然公論在，雖滯楚南春。"]', '["得罪非天意，分明謫去身。","一心貪諫主，开口不防人。","自古有遷客，何朝無直臣。","喧然公論在，雖滯楚南春。"]', '诗', 'shi', '', NULL, '送黃補闕南遷 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f32673ca-e5cb-4fad-bbc5-d17809e15ebb', '送賓貢登第後歸海東', '送賓貢登第後归海东', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["歸捷中華第，登船鬢未絲。","直應天上桂，別有海東枝。","國界波窮處，鄉心日出時。","西風送君去，莫慮到家遲。"]', '["归捷中华第，登船鬢未絲。","直應天上桂，別有海东枝。","国界波窮处，乡心日出时。","西风送君去，莫慮到家遲。"]', '诗', 'shi', '', NULL, '送賓貢登第後歸海東 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f977aa5-e2a2-4932-bacb-92ff9dc6c802', '近試投所知', '近試投所知', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["白髮隨梳落，吟懷說向誰。","敢辭成事晚，自是出山遲。","擬動如浮海，凡言似課詩。","終身事知己，此外復何爲。"]', '["白髮隨梳落，吟懷说向誰。","敢辞成事晚，自是出山遲。","擬动如浮海，凡言似課诗。","終身事知己，此外复何爲。"]', '诗', 'shi', '', NULL, '近試投所知 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4264bd54-fce8-4af6-8bd6-4a94e02e4864', '送友人牧江州', '送友人牧江州', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["本國兵戈後，難官在此時。","遠分天子命，深要使君知。","但遂生靈願，當應雨露隨。","江山勝他郡，閑賦庾樓詩。"]', '["本国兵戈後，难官在此时。","远分天子命，深要使君知。","但遂生靈願，當應雨露隨。","江山勝他郡，闲賦庾楼诗。"]', '诗', 'shi', '', NULL, '送友人牧江州 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11e23596-baf3-429c-84e0-e3d7f7223e7a', '辭座主侍郎', '辞座主侍郎', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一飯尚懷感，況攀高桂枝。","此恩無報處，故國遠歸時。","祗恐兵戈隔，再趨門館遲。","茅堂拜親後，特地淚雙垂。"]', '["一飯尚懷感，況攀高桂枝。","此恩無報处，故国远归时。","祗恐兵戈隔，再趨门館遲。","茅堂拜親後，特地泪雙垂。"]', '诗', 'shi', '', NULL, '辭座主侍郎 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44fa2020-c545-4187-b545-bb2c47954c6b', '別從叔', '別從叔', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["立馬不忍上，醉醒天氣寒。","都緣在門易，直似別家難。","世路既如此，客心須自寬。","江村亦飢凍，爭及問長安。"]', '["立马不忍上，醉醒天氣寒。","都緣在门易，直似別家难。","世路既如此，客心須自寬。","江村亦飢凍，爭及问长安。"]', '诗', 'shi', '', NULL, '別從叔 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2244b0fa-b552-435c-8fcb-4b730aea1152', '送人南遊', '送人南游', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["凡遊南國者，未有不蹉跎。","到海路難盡，挂帆人更多。","潮沙分象跡，花洞響蠻歌。","縱有投文處，於君能幾何。"]', '["凡游南国者，未有不蹉跎。","到海路难尽，挂帆人更多。","潮沙分象跡，花洞响蠻歌。","縱有投文处，於君能幾何。"]', '诗', 'shi', '', NULL, '送人南遊 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b6741c8-e5b3-431c-a5d7-528e376b0a15', '經賈島墓', '經賈島墓', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["謫宦自麻衣，銜冤至死時。","山根三尺墓，人口數聯詩。","仙桂終無分，皇天似有私。","暗松風雨夜，空使老猿悲。"]', '["謫宦自麻衣，銜冤至死时。","山根三尺墓，人口數聯诗。","仙桂終無分，皇天似有私。","暗松风雨夜，空使老猿悲。"]', '诗', 'shi', '', NULL, '經賈島墓 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('682fa1bf-f06b-4959-af3d-986091b2b07e', '秋夜晚泊', '秋夜晚泊', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一望一蒼然，蕭騷起暮天。","遠山橫落日，歸鳥度平川。","家是去秋別，月當今夕圓。","漁翁似相伴，徹曉葦叢邊。"]', '["一望一蒼然，蕭騷起暮天。","远山橫落日，归鸟度平川。","家是去秋別，月當今夕圓。","漁翁似相伴，徹晓葦叢邊。"]', '诗', 'shi', '', NULL, '秋夜晚泊 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ce9adf-8dec-4e72-a7ee-138bf1f474ab', '送舍弟', '送舍弟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["我受羈棲慣，客情方細知。","好看前路事，不比在家時。","勉汝言須記，聞人善即師。","旅中無廢業，時作一篇詩。"]', '["我受羈棲慣，客情方細知。","好看前路事，不比在家时。","勉汝言須記，闻人善即師。","旅中無廢業，时作一篇诗。"]', '诗', 'shi', '', NULL, '送舍弟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cceb2ffd-85fe-433a-9a89-27cc5ff3e2c0', '將歸山逢友人', '將归山逢友人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["儒爲君子儒，儒道不妨孤。","白髮多生矣，青山可住乎。","徉狂寧是事，巧達又非夫。","祗此平生願，他人肯信無。"]', '["儒爲君子儒，儒道不妨孤。","白髮多生矣，青山可住乎。","徉狂寧是事，巧達又非夫。","祗此平生願，他人肯信無。"]', '诗', 'shi', '', NULL, '將歸山逢友人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b148096a-7f8a-4e94-9628-c742f3d816b2', '經九華費徵君墓', '經九华費徵君墓', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["凡弔先生者，多傷荆棘間。","不知三尺墓，高却九華山。","天地有何外，子孫無亦閑。","當時若徵起，未必得身還。"]', '["凡弔先生者，多傷荆棘间。","不知三尺墓，高却九华山。","天地有何外，子孫無亦闲。","當时若徵起，未必得身還。"]', '诗', 'shi', '', NULL, '經九華費徵君墓 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13672c02-dba9-49b6-9260-4c0e68ced953', '溪居叟', '溪居叟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["溪翁居靜處，溪鳥入門飛。","早起釣魚去，夜深乘月歸。","見君無事老，覺我有求非。","不說風霜苦，三冬一草衣。"]', '["溪翁居静处，溪鸟入门飞。","早起釣鱼去，夜深乘月归。","见君無事老，覺我有求非。","不说风霜苦，三冬一草衣。"]', '诗', 'shi', '', NULL, '溪居叟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a8bc6b-aa3b-4790-9a88-977741bbb7b8', '與友人對酒吟', '與友人对酒吟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["憑君滿酌酒，聽我醉中吟。","客路如天遠，侯門似海深。","新墳侵古道，白髮戀黃金。","共有人間事，須懷濟物心。"]', '["憑君满酌酒，听我醉中吟。","客路如天远，侯门似海深。","新墳侵古道，白髮戀黄金。","共有人间事，須懷濟物心。"]', '诗', 'shi', '', NULL, '與友人對酒吟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41322a5c-165c-4abe-a151-6a787737d52e', '送僧', '送僧', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["道了亦未了，言閑今且閑。","從來無住處，此去向何山。","片石樹陰下，斜陽潭影間。","請師留偈別，恐不到人寰。"]', '["道了亦未了，言闲今且闲。","從来無住处，此去向何山。","片石樹陰下，斜陽潭影间。","請師留偈別，恐不到人寰。"]', '诗', 'shi', '', NULL, '送僧 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db9c0369-a780-4819-89e9-d9eab8627aaa', '送九華道士遊茅山', '送九华道士游茅山', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["忽起地仙興，飄然出舊山。","於身無切事，在世有餘閑。","日月浮生外，乾坤大醉間。","故園華表上，誰得見君還。"]', '["忽起地仙兴，飄然出旧山。","於身無切事，在世有餘闲。","日月浮生外，乾坤大醉间。","故园华表上，誰得见君還。"]', '诗', 'shi', '', NULL, '送九華道士遊茅山 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39761c8a-19ce-4d99-9571-4627e5d7f3d7', '寄舍弟', '寄舍弟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["世亂信難通，鄉心日萬重。","弟兄皆嚮善，天地合相容。","大野陰雲重，連城殺氣濃。","家山白雲裏，臥得最高峰。"]', '["世亂信难通，乡心日万重。","弟兄皆嚮善，天地合相容。","大野陰云重，連城殺氣濃。","家山白云裏，臥得最高峰。"]', '诗', 'shi', '', NULL, '寄舍弟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8b0b730-c92f-4906-8fc3-0342b571fc2e', '下第投所知', '下第投所知', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["若以名場內，誰無一軸詩。","縱饒生白髮，豈敢怨明時。","知己雖然切，春官未必私。","寧教讀書眼，不有看花期。"]', '["若以名場內，誰無一軸诗。","縱饒生白髮，豈敢怨明时。","知己雖然切，春官未必私。","寧教读书眼，不有看花期。"]', '诗', 'shi', '', NULL, '下第投所知 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('690b6c13-eb9a-4dbd-8407-bbebf4c61ea2', '寄顧雲', '寄顧云', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["省得前年別，蘋洲旅館中。","亂離身不定，彼此信難通。","侯國兵雖斂，吾鄉業已空。","秋來憶君夢，夜夜逐征鴻。"]', '["省得前年別，蘋洲旅館中。","亂離身不定，彼此信难通。","侯国兵雖斂，吾乡業已空。","秋来憶君梦，夜夜逐征鴻。"]', '诗', 'shi', '', NULL, '寄顧雲 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f54bd80-7158-4f7c-9508-dbc73aba5284', '贈宣城麋明府', '贈宣城麋明府', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["天下爲官者，無君一軸詩。","數聯同我得，當代遇誰知。","年齒吟將老，生涯說可悲。","何當拋手板，鄰隱過危時。"]', '["天下爲官者，無君一軸诗。","數聯同我得，當代遇誰知。","年齒吟將老，生涯说可悲。","何當拋手板，鄰隐過危时。"]', '诗', 'shi', '', NULL, '贈宣城麋明府 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fbda051-6db7-4c68-91b1-a4b76cf10d3e', '望遠', '望远', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["門前通大道，望遠上高臺。","落日人行盡，窮邊信不來。","還聞戰得勝，未見敕招回。","却入機中坐，新愁織不開。"]', '["门前通大道，望远上高台。","落日人行尽，窮邊信不来。","還闻戰得勝，未见敕招回。","却入機中坐，新愁织不开。"]', '诗', 'shi', '', NULL, '望遠 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a647c9e5-c418-432f-aadf-4afe1c0390c8', '冬末投長沙裴侍郎', '冬末投长沙裴侍郎', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["欲露塵中事，其如不易言。","家山一離別，草樹匝春暄。","吹夢風天角，啼愁雪嶽猿。","佇思心覺滿，何以遠門軒。"]', '["欲露塵中事，其如不易言。","家山一離別，草樹匝春暄。","吹梦风天角，啼愁雪嶽猿。","佇思心覺满，何以远门軒。"]', '诗', 'shi', '', NULL, '冬末投長沙裴侍郎 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('767f4dc8-65b6-456a-84f5-9d25088f7b09', '贈秋浦金明府長', '贈秋浦金明府长', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["倚郭難爲宰，非君即有私。","惟憑野老口，不立政聲碑。","苦甚求名日，貧於未選時。","溪山竟如此，利得且吟詩。"]', '["倚郭难爲宰，非君即有私。","惟憑野老口，不立政声碑。","苦甚求名日，貧於未選时。","溪山竟如此，利得且吟诗。"]', '诗', 'shi', '', NULL, '贈秋浦金明府長 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('869c5375-ce65-4175-a511-0bab1c08ad43', '和高祕書早春對雪登樓見寄之什', '和高祕书早春对雪登楼见寄之什', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["天有惜花意，恐花開染塵。","先教微雪下，始放滿城春。","且醉登樓客，重期出郭人。","因酬郢中律，霜鬢數莖新。"]', '["天有惜花意，恐花开染塵。","先教微雪下，始放满城春。","且醉登楼客，重期出郭人。","因酬郢中律，霜鬢數莖新。"]', '诗', 'shi', '', NULL, '和高祕書早春對雪登樓見寄之什 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da4a96af-baf1-4f4e-917c-a71ab915ce77', '亂後山中作', '亂後山中作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["自從天下亂，日晚別庭闈。","兄弟團圞樂，羈孤遠近歸。","文章甘世薄，耕種喜山肥。","直待中興後，方應出隱扉。"]', '["自從天下亂，日晚別庭闈。","兄弟團圞乐，羈孤远近归。","文章甘世薄，耕種喜山肥。","直待中兴後，方應出隐扉。"]', '诗', 'shi', '', NULL, '亂後山中作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('220a1748-b3ec-477e-8c07-38afd845c091', '旅寓書事', '旅寓书事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["日日驚身事，悽悽欲斷魂。","時清不自立，髮白傍誰門。","中路殘秋雨，空山一夜猿。","公卿得見面，懷抱細難言。"]', '["日日驚身事，悽悽欲斷魂。","时清不自立，髮白傍誰门。","中路殘秋雨，空山一夜猿。","公卿得见面，懷抱細难言。"]', '诗', 'shi', '', NULL, '旅寓書事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('433d63b9-0886-43a3-a01a-caa0357caaf5', '舟行晚泊江上寺', '舟行晚泊江上寺', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["久勞風水上，禪客喜相依。","挂衲雖無分，修心未覺非。","日沈山虎出，鐘動寺禽歸。","月上潮平後，談空漸入微。"]', '["久勞风水上，禪客喜相依。","挂衲雖無分，修心未覺非。","日沈山虎出，鐘动寺禽归。","月上潮平後，談空漸入微。"]', '诗', 'shi', '', NULL, '舟行晚泊江上寺 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d50246a-6dbd-4f01-95bc-5eab472a908f', '長林山中聞賊退寄孟明府', '长林山中闻賊退寄孟明府', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一縣今如此，殘民數不多。","也知賢宰切，爭奈亂兵何。","皆自干戈達，咸思雨露和。","應憐住山者，頭白未登科。"]', '["一縣今如此，殘民數不多。","也知賢宰切，爭奈亂兵何。","皆自干戈達，咸思雨露和。","應怜住山者，头白未登科。"]', '诗', 'shi', '', NULL, '長林山中聞賊退寄孟明府 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93c3dc05-659b-484c-943f-1a42b3e3dd1b', '泗上客思', '泗上客思', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["痛飲復高歌，愁終不奈何。","家山隨日遠，身事逐年多。","沒鴈雲橫楚，兼蟬柳夾河。","此心閑未得，到處被詩磨。"]', '["痛饮复高歌，愁終不奈何。","家山隨日远，身事逐年多。","沒鴈云橫楚，兼蟬柳夾河。","此心闲未得，到处被诗磨。"]', '诗', 'shi', '', NULL, '泗上客思 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4efca65d-3235-44c4-bf81-cc97b0fc9f18', '寄同人', '寄同人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["盡與貧爲患，唯余即不然。","四方無靜處，百口度荒年。","白髮生閑事，新詩出數聯。","時情竟如此，不免却歸田。"]', '["尽與貧爲患，唯余即不然。","四方無静处，百口度荒年。","白髮生闲事，新诗出數聯。","时情竟如此，不免却归田。"]', '诗', 'shi', '', NULL, '寄同人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed826213-f49f-4046-8b39-de8fe3ced6ae', '下第出關投鄭拾遺', '下第出关投鄭拾遺', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["丹霄桂有枝，未折未爲遲。","況是孤寒士，兼行苦澀詩。","杏園人醉日，關路獨歸時。","更卜深知意，將來擬薦誰。"]', '["丹霄桂有枝，未折未爲遲。","況是孤寒士，兼行苦澀诗。","杏园人醉日，关路独归时。","更卜深知意，將来擬薦誰。"]', '诗', 'shi', '', NULL, '下第出關投鄭拾遺 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dabdda7d-66b2-44aa-9677-91e6a3a99a6f', '塞上', '塞上', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["草白河冰合，蕃戎出掠頻。","戍樓三號火，探馬一條塵。","戰士風霜老，將軍雨露新。","封侯不由此，何以慰征人。"]', '["草白河冰合，蕃戎出掠頻。","戍楼三號火，探马一條塵。","戰士风霜老，將軍雨露新。","封侯不由此，何以慰征人。"]', '诗', 'shi', '', NULL, '塞上 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a298514-238c-4fcb-953d-10338e9fcdd4', '別敬侍郎', '別敬侍郎', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["交道有寒暑，在人無古今。","與君中夜話，盡我一生心。","所向未得志，豈惟空解吟。","何當重相見，舊隱白雲深。"]', '["交道有寒暑，在人無古今。","與君中夜話，尽我一生心。","所向未得志，豈惟空解吟。","何當重相见，旧隐白云深。"]', '诗', 'shi', '', NULL, '別敬侍郎 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f214a50f-967c-4ef7-afd4-9e48ece722c2', '送青陽李明府', '送青陽李明府', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["善政無慙色，吟歸似等閑。","惟將六幅絹，寫得九華山。","求理頭空白，離京債未還。","仍聞猿與鶴，都在一船間。"]', '["善政無慙色，吟归似等闲。","惟將六幅絹，寫得九华山。","求理头空白，離京債未還。","仍闻猿與鹤，都在一船间。"]', '诗', 'shi', '', NULL, '送青陽李明府 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('260130c0-fc85-47c4-b892-cb49a2b690ce', '將遊湘湖有作', '將游湘湖有作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一家相別意，不得不澘然。","遠作南方客，初登上水船。","嶽鐘思冷夢，湘月少殘篇。","便有歸來計，風波亦隔年。"]', '["一家相別意，不得不澘然。","远作南方客，初登上水船。","嶽鐘思冷梦，湘月少殘篇。","便有归来計，风波亦隔年。"]', '诗', 'shi', '', NULL, '將遊湘湖有作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d769297-a0ad-4ec0-992b-4b2a25cdb5ef', '送姚庭珪', '送姚庭珪', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["脫衣將換酒，對酌話何之。","雨後秋蕭索，天涯晚別離。","人生無此恨，鬢色不成絲。","未得重相見，看君馬上詩。"]', '["脫衣將換酒，对酌話何之。","雨後秋蕭索，天涯晚別離。","人生無此恨，鬢色不成絲。","未得重相见，看君马上诗。"]', '诗', 'shi', '', NULL, '送姚庭珪 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('014e1e17-1bd0-4ece-9655-abffca2eb5a4', '投李大夫', '投李大夫', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["自小僻於詩，篇篇恨不奇。","苦吟無暇日，華髮有多時。","進取門難見，升沈命未知。","秋風夜來急，還恐到京遲。"]', '["自小僻於诗，篇篇恨不奇。","苦吟無暇日，华髮有多时。","進取门难见，升沈命未知。","秋风夜来急，還恐到京遲。"]', '诗', 'shi', '', NULL, '投李大夫 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc2264b-c19d-44ee-938b-dc26326f6568', '貽里中同志', '貽里中同志', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["鄉里爲儒者，唯君見我心。","詩書常共讀，雨雪亦相尋。","貧賤志氣在，子孫交契深。","古人猶晚達，況未鬢霜侵。"]', '["乡里爲儒者，唯君见我心。","诗书常共读，雨雪亦相尋。","貧賤志氣在，子孫交契深。","古人猶晚達，況未鬢霜侵。"]', '诗', 'shi', '', NULL, '貽里中同志 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58c4dd07-c8f9-49b8-8bcc-0cd65f75c533', '江上送韋彖先輩', '江上送韋彖先輩', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["不易爲離抱，江天即見鴻。","暮帆何處落，涼月與誰同。","木葉新霜後，漁燈夜浪中。","時難慎行止，吾道利于窮。"]', '["不易爲離抱，江天即见鴻。","暮帆何处落，涼月與誰同。","木葉新霜後，漁灯夜浪中。","时难慎行止，吾道利于窮。"]', '诗', 'shi', '', NULL, '江上送韋彖先輩 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8929d09-035b-4ee0-bc25-8c26387d0ad3', '維揚逢詩友張喬', '維揚逢诗友張喬', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["天下方多事，逢君得話詩。","直應吾道在，未覺國風衰。","生計吟消日，人情醉過時。","雅篇三百首，留作後來師。"]', '["天下方多事，逢君得話诗。","直應吾道在，未覺国风衰。","生計吟消日，人情醉過时。","雅篇三百首，留作後来師。"]', '诗', 'shi', '', NULL, '維揚逢詩友張喬 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b00d2479-4f54-4ae6-b47c-d2ed34bfdc8a', '秋晨有感', '秋晨有感', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["木葉落時節，旅人初夢驚。","鐘才枕上盡，事已眼前生。","吟髮不長黑，世交無久情。","且將公道約，未忍便歸耕。"]', '["木葉落时節，旅人初梦驚。","鐘才枕上尽，事已眼前生。","吟髮不长黑，世交無久情。","且將公道約，未忍便归耕。"]', '诗', 'shi', '', NULL, '秋晨有感 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57c5e421-f3d7-4856-928d-244a05e3737c', '秋日山中寄李處士', '秋日山中寄李处士', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["吾輩道何窮，寒山細雨中。","兒童書懶讀，果粟樹將空。","言論關時務，篇章見國風。","昇平猶可用，應不廢爲公。"]', '["吾輩道何窮，寒山細雨中。","兒童书懶读，果粟樹將空。","言論关时務，篇章见国风。","昇平猶可用，應不廢爲公。"]', '诗', 'shi', '', NULL, '秋日山中寄李處士 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e63c833e-2bc6-43c9-90da-b882cd6f161d', '晚泊金陵水亭', '晚泊金陵水亭', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["江亭當廢國，秋景倍蕭騷。","夕照殘荒壘，寒潮漲古濠。","就田看鶴劣，隔水見僧高。","無限前朝事，醒吟易覺勞。"]', '["江亭當廢国，秋景倍蕭騷。","夕照殘荒壘，寒潮漲古濠。","就田看鹤劣，隔水见僧高。","無限前朝事，醒吟易覺勞。"]', '诗', 'shi', '', NULL, '晚泊金陵水亭 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a42c0077-db45-40da-bddc-500cb50fe908', '錢塘別羅隱', '錢塘別羅隐', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["故國看看遠，前程計在誰。","五更聽角後，一葉渡江時。","吾道天寧喪，人情日可疑。","西陵向西望，雙淚爲君垂。"]', '["故国看看远，前程計在誰。","五更听角後，一葉渡江时。","吾道天寧喪，人情日可疑。","西陵向西望，雙泪爲君垂。"]', '诗', 'shi', '', NULL, '錢塘別羅隱 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c78a9c4-4281-454b-b668-9567730ad4d7', '山中貽同志', '山中貽同志', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["君貧我亦貧，爲善喜爲鄰。","到老如今日，無心媿古人。","閉門非傲世，守道是謀身。","別有同山者，其如未可親。"]', '["君貧我亦貧，爲善喜爲鄰。","到老如今日，無心媿古人。","閉门非傲世，守道是謀身。","別有同山者，其如未可親。"]', '诗', 'shi', '', NULL, '山中貽同志 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6731fd16-4db5-4e56-a1f0-0c4c0fdecdaa', '秋日懷九華舊居', '秋日懷九华旧居', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["吾道在五字，吾身寧陸沈。","涼生中夜雨，病起故山心。","燭共寒酸影，蛩添苦楚吟。","何當遂歸去，一徑入松林。"]', '["吾道在五字，吾身寧陸沈。","涼生中夜雨，病起故山心。","燭共寒酸影，蛩添苦楚吟。","何當遂归去，一徑入松林。"]', '诗', 'shi', '', NULL, '秋日懷九華舊居 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('140fb84a-43a1-4799-af8f-4ba8eb5d2991', '江岸秋思', '江岸秋思', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["驅馬傍江行，鄉愁步步生。","舉鞭揮柳色，隨手失蟬聲。","秋稼緣長道，寒雲約古城。","家貧遇豐歲，無地可歸耕。"]', '["驱马傍江行，乡愁步步生。","舉鞭揮柳色，隨手失蟬声。","秋稼緣长道，寒云約古城。","家貧遇豐歲，無地可归耕。"]', '诗', 'shi', '', NULL, '江岸秋思 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2c6dc49-caa5-4bd7-8ddc-a2b75ad21253', '哭劉德仁', '哭劉德仁', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["賈島還如此，生前不見春。","豈能詩苦者，便是命羈人。","家事因吟失，時情礙國親。","多應銜恨骨，千古不爲塵。"]', '["賈島還如此，生前不见春。","豈能诗苦者，便是命羈人。","家事因吟失，时情礙国親。","多應銜恨骨，千古不爲塵。"]', '诗', 'shi', '', NULL, '哭劉德仁 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9417dc6f-70e0-4801-a605-e630080d0fcd', '經青山弔李翰林', '經青山弔李翰林', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["何爲先生死，先生道日新。","青山明月夜，千古一詩人。","天地空銷骨，聲名不傍身。","誰移耒陽冢，來此作吟鄰。"]', '["何爲先生死，先生道日新。","青山明月夜，千古一诗人。","天地空銷骨，声名不傍身。","誰移耒陽冢，来此作吟鄰。"]', '诗', 'shi', '', NULL, '經青山弔李翰林 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('174566e0-5b17-455e-a222-a242e916176f', '下第東歸別友人', '下第东归別友人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["不得同君住，當春別帝鄉。","年華落第老，岐路出關長。","芳草緣流水，殘花向夕陽。","懷親暫歸去，非是釣滄浪。"]', '["不得同君住，當春別帝乡。","年华落第老，岐路出关长。","芳草緣流水，殘花向夕陽。","懷親暫归去，非是釣滄浪。"]', '诗', 'shi', '', NULL, '下第東歸別友人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eee00d39-c4d2-4313-8700-9744834105e7', '秋宿詩僧雲英房因贈', '秋宿诗僧云英房因贈', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["賈島憐無可，都緣數句詩。","君雖是後輩，我謂過當時。","溪浪和星動，松陰帶鶴移。","同吟到明坐，此道淡誰知。"]', '["賈島怜無可，都緣數句诗。","君雖是後輩，我謂過當时。","溪浪和星动，松陰带鹤移。","同吟到明坐，此道淡誰知。"]', '诗', 'shi', '', NULL, '秋宿詩僧雲英房因贈 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71690dfa-cc0e-450a-87ee-2e9857761e1d', '送人宰吳縣', '送人宰吳縣', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["海漲兵荒後，爲官合動情。","字人無異術，至論不如清。","草履隨船賣，綾梭隔水鳴。","唯持古人意，千里贈君行。"]', '["海漲兵荒後，爲官合动情。","字人無異術，至論不如清。","草履隨船賣，綾梭隔水鳴。","唯持古人意，千里贈君行。"]', '诗', 'shi', '', NULL, '送人宰吳縣 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bf2a0a2-2758-4a5c-ae0f-90984d986977', '讀友人詩', '读友人诗', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["君詩通大雅，吟覺古風生。","外却浮華景，中含教化情。","名應高日月，道可潤公卿。","莫以孤寒恥，孤寒達更榮。"]', '["君诗通大雅，吟覺古风生。","外却浮华景，中含教化情。","名應高日月，道可潤公卿。","莫以孤寒恥，孤寒達更榮。"]', '诗', 'shi', '', NULL, '讀友人詩 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6be081e2-4953-4c5b-9c8e-5bea90695012', '登山寺', '登山寺', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["山半一山寺，野人秋日登。","就中偏愛石，獨上最高層。","有果猿攀樹，無齋鴿看僧。","儒門自多事，來此復何能。"]', '["山半一山寺，野人秋日登。","就中偏愛石，独上最高層。","有果猿攀樹，無斋鴿看僧。","儒门自多事，来此复何能。"]', '诗', 'shi', '', NULL, '登山寺 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a2d317c-6042-4fec-bdcd-7251042925b7', '辭九江李郎中入關', '辞九江李郎中入关', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["帝里無相識，何門跡可親。","願開言重口，薦與分深人。","卷許新詩出，家憐舊業貧。","今從九江去，應免更迷津。"]', '["帝里無相識，何门跡可親。","願开言重口，薦與分深人。","卷許新诗出，家怜旧業貧。","今從九江去，應免更迷津。"]', '诗', 'shi', '', NULL, '辭九江李郎中入關 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d390068-5fc7-45f6-a101-3ad9467b03c5', '江南逢李先輩', '江南逢李先輩', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["李杜復李杜，彼時逢此時。","干戈侵帝里，流落向天涯。","歲月消於酒，平生斷在詩。","懷才不得志，祗恐滿頭絲。"]', '["李杜复李杜，彼时逢此时。","干戈侵帝里，流落向天涯。","歲月消於酒，平生斷在诗。","懷才不得志，祗恐满头絲。"]', '诗', 'shi', '', NULL, '江南逢李先輩 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f8b868-9279-4aef-8027-e4359e5622f4', '秋日寄吟友', '秋日寄吟友', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["閑坐細思量，唯吟不可忘。","食無三畝地，衣絕一株桑。","蟬樹生寒色，漁潭落曉光。","青雲舊知己，未許釣滄浪。"]', '["闲坐細思量，唯吟不可忘。","食無三畝地，衣絕一株桑。","蟬樹生寒色，漁潭落晓光。","青云旧知己，未許釣滄浪。"]', '诗', 'shi', '', NULL, '秋日寄吟友 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125644ed-3dea-42c7-8713-1732c4598734', '江上與從弟話別', '江上與從弟話別', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["相逢盡說歸，早晚遂歸期。","流水多通處，孤舟少住時。","干人不得已，非我欲爲之。","及此終無媿，其如道在茲。"]', '["相逢尽说归，早晚遂归期。","流水多通处，孤舟少住时。","干人不得已，非我欲爲之。","及此終無媿，其如道在茲。"]', '诗', 'shi', '', NULL, '江上與從弟話別 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa62401e-eca6-464c-b807-cbd7567cabe0', '送友人遊南海', '送友人游南海', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["南海南邊路，君遊祗爲貧。","山川多少地，郡邑幾何人。","花鳥名皆別，寒暄氣不均。","相期早晚見，莫待瘴侵身。"]', '["南海南邊路，君游祗爲貧。","山川多少地，郡邑幾何人。","花鸟名皆別，寒暄氣不均。","相期早晚见，莫待瘴侵身。"]', '诗', 'shi', '', NULL, '送友人遊南海 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eb94fe9-8c0d-42d1-a4e0-ff86659c3c37', '贈聶尊師', '贈聶尊師', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["詩道將仙分，求之不可求。","非關從小學，應是數生修。","蟾桂雲梯折，鰲山鶴駕遊。","他年兩成事，堪喜是鄰州。"]', '["诗道將仙分，求之不可求。","非关從小学，應是數生修。","蟾桂云梯折，鰲山鹤駕游。","他年兩成事，堪喜是鄰州。"]', '诗', 'shi', '', NULL, '贈聶尊師 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acaf168a-cf37-45d7-a44d-b76893a3182f', '旅感', '旅感', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["白髮根叢出，鑷頻愁不開。","自憐空老去，誰信苦吟來。","客路東西闊，家山早晚回。","翻思釣魚處，一雨一層苔。"]', '["白髮根叢出，鑷頻愁不开。","自怜空老去，誰信苦吟来。","客路东西闊，家山早晚回。","翻思釣鱼处，一雨一層苔。"]', '诗', 'shi', '', NULL, '旅感 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8a4ac3e-246d-4405-a3da-700bd8d75912', '寄益陽武灌明府', '寄益陽武灌明府', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["縣稱詩人理，無嫌日寂寥。","溪山入城郭，戶口半漁樵。","月滿彈琴夜，花香漉酒朝。","相思不相見，煙水路迢迢。"]', '["縣稱诗人理，無嫌日寂寥。","溪山入城郭，戶口半漁樵。","月满彈琴夜，花香漉酒朝。","相思不相见，煙水路迢迢。"]', '诗', 'shi', '', NULL, '寄益陽武灌明府 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d9d95bf-fdcc-49ae-9332-ec0aa00d18ef', '湘中秋日呈所知', '湘中秋日呈所知', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["四海無寸土，一生惟苦吟。","虛垂異鄉淚，不滴別人心。","雨色凋湘樹，灘聲下塞禽。","求歸歸未得，不是擲光陰。"]', '["四海無寸土，一生惟苦吟。","虛垂異乡泪，不滴別人心。","雨色凋湘樹，灘声下塞禽。","求归归未得，不是擲光陰。"]', '诗', 'shi', '', NULL, '湘中秋日呈所知 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f66da26c-2005-4b50-9046-f47bd0f19254', '苦吟', '苦吟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["世間何事好，最好莫過詩。","一句我自得，四方人已知。","生應無輟日，死是不吟時。","始擬歸山去，林泉道在茲。"]', '["世间何事好，最好莫過诗。","一句我自得，四方人已知。","生應無輟日，死是不吟时。","始擬归山去，林泉道在茲。"]', '诗', 'shi', '', NULL, '苦吟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0035baa-de78-49c8-87c9-536d079d3b14', '閩中別所知', '閩中別所知', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["觸目生歸思，那堪路七千。","臘中離此地，馬上見明年。","郡邑溪山巧，寒暄日月偏。","自疑雙鬢雪，不似到南天。"]', '["觸目生归思，那堪路七千。","臘中離此地，马上见明年。","郡邑溪山巧，寒暄日月偏。","自疑雙鬢雪，不似到南天。"]', '诗', 'shi', '', NULL, '閩中別所知 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bed77bb-252a-4347-8551-ff8325807709', '塞上傷戰士', '塞上傷戰士', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["戰士說辛勤，書生不忍聞。","三邊遠天子，一命信將軍。","野火燒人骨，陰風捲陣雲。","其如禁城裏，何以重要勳。"]', '["戰士说辛勤，书生不忍闻。","三邊远天子，一命信將軍。","野火燒人骨，陰风捲陣云。","其如禁城裏，何以重要勳。"]', '诗', 'shi', '', NULL, '塞上傷戰士 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c68962-9649-433b-9d64-01d78e024a07', '春日訪獨孤處士', '春日訪独孤处士', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["地僻春來靜，深宜長者居。","好花都待晚，修竹不妨疎。","鴈入湘江食，人侵曉色鋤。","似君無學處，頭白道如初。"]', '["地僻春来静，深宜长者居。","好花都待晚，修竹不妨疎。","鴈入湘江食，人侵晓色鋤。","似君無学处，头白道如初。"]', '诗', 'shi', '', NULL, '春日訪獨孤處士 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cebe6dbc-5e11-4c51-9b32-1f6d6171eed2', '哭友人', '哭友人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["病向名場得，終爲善誤身。","無兒承後嗣，有女托何人。","葬禮難求備，交情好者貧。","惟餘舊文集，一覽一沾巾。"]', '["病向名場得，終爲善誤身。","無兒承後嗣，有女托何人。","葬禮难求備，交情好者貧。","惟餘旧文集，一覽一沾巾。"]', '诗', 'shi', '', NULL, '哭友人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bea0575-51aa-4266-a425-90732518949a', '新栽竹', '新栽竹', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["斸破蒼苔色，因栽十數莖。","窗風從此冷，詩思當時清。","酒入杯中影，棊添局上聲。","不同桃與李，瀟灑伴書生。"]', '["斸破蒼苔色，因栽十數莖。","窗风從此冷，诗思當时清。","酒入杯中影，棊添局上声。","不同桃與李，瀟灑伴书生。"]', '诗', 'shi', '', NULL, '新栽竹 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf0e4552-5b53-44ae-bbf9-0afdd38a8a54', '送吳蛻下第入蜀', '送吳蛻下第入蜀', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["下第言之蜀，那愁舉別杯。","難兄方在幕，上相復憐才。","鳥徑盤春靄，龍湫發夜雷。","臨邛無久戀，高桂待君回。"]', '["下第言之蜀，那愁舉別杯。","难兄方在幕，上相复怜才。","鸟徑盤春靄，龙湫發夜雷。","臨邛無久戀，高桂待君回。"]', '诗', 'shi', '', NULL, '送吳蛻下第入蜀 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('471c6fe2-3962-4407-8e2d-46f89ca7982c', '亂後歸山', '亂後归山', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["亂世歸山谷，征鼙喜不聞。","詩書猶滿架，弟姪未爲軍。","山犬眠紅葉，樵童唱白雲。","此心非此志，終擬致明君。"]', '["亂世归山谷，征鼙喜不闻。","诗书猶满架，弟姪未爲軍。","山犬眠紅葉，樵童唱白云。","此心非此志，終擬致明君。"]', '诗', 'shi', '', NULL, '亂後歸山 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9142cf3-9f9d-4332-9c85-15a1ca7fc706', '題著禪師', '題著禪師', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["大道本無幻，常情自有魔。","人皆迷著此，師獨悟如何。","爲岳開窗闊，因蟲長草多。","說空空說得，空得到維摩。"]', '["大道本無幻，常情自有魔。","人皆迷著此，師独悟如何。","爲岳开窗闊，因蟲长草多。","说空空说得，空得到維摩。"]', '诗', 'shi', '', NULL, '題著禪師 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91eb65fd-05d4-4228-8d8d-f5c7c7b97acc', '春日閑居即事', '春日闲居即事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["未得青雲志，春同秋日情。","花開如葉落，鶯語似蟬鳴。","道合和貧守，詩堪與命爭。","飢寒是吾事，斷定不歸耕。"]', '["未得青云志，春同秋日情。","花开如葉落，鶯語似蟬鳴。","道合和貧守，诗堪與命爭。","飢寒是吾事，斷定不归耕。"]', '诗', 'shi', '', NULL, '春日閑居即事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8bd2b40-4e81-480e-a726-c5ba3a68e3c2', '秋宿棲賢寺懷友人', '秋宿棲賢寺懷友人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一宿三秋寺，閑忙與曉分。","細泉山半落，孤客夜深聞。","鶴去巢盛月，龍潛穴擁雲。","苦吟方見景，多恨不同君。"]', '["一宿三秋寺，闲忙與晓分。","細泉山半落，孤客夜深闻。","鹤去巢盛月，龙潛穴擁云。","苦吟方见景，多恨不同君。"]', '诗', 'shi', '', NULL, '秋宿棲賢寺懷友人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7554ed9-f336-4379-8a8a-481107bf3af1', '亂後再逢汪處士', '亂後再逢汪处士', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["如君真道者，亂世有閑情。","每別不知處，見來長後生。","藥非因病服，酒不爲愁傾。","笑我於身苦，吟髭白數莖。"]', '["如君真道者，亂世有闲情。","每別不知处，见来长後生。","藥非因病服，酒不爲愁傾。","笑我於身苦，吟髭白數莖。"]', '诗', 'shi', '', NULL, '亂後再逢汪處士 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c529dac2-c230-43ed-8c6f-aa36e922e842', '山中喜與故交宿話', '山中喜與故交宿話', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["遠地能相訪，何慙事力微。","山中深夜坐，海內故交稀。","村酒沽來濁，溪魚釣得肥。","貧家只如此，未可便言歸。"]', '["远地能相訪，何慙事力微。","山中深夜坐，海內故交稀。","村酒沽来濁，溪鱼釣得肥。","貧家只如此，未可便言归。"]', '诗', 'shi', '', NULL, '山中喜與故交宿話 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d38a6f3-05ed-41a6-a59b-08b4f60bcf54', '觀碁', '观碁', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["對面不相見，用心同用兵。","算人常欲殺，顧己自貪生。","得勢侵吞遠，乘危打劫贏。","有時逢敵手，當局到深更。"]', '["对面不相见，用心同用兵。","算人常欲殺，顧己自貪生。","得勢侵吞远，乘危打劫贏。","有时逢敵手，當局到深更。"]', '诗', 'shi', '', NULL, '觀碁 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('852d4a66-247b-4804-9182-ef4c09c01396', '送人宰德清', '送人宰德清', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["亂世人多事，耕桑或失時。","不聞寬賦斂，因此轉流離。","天意未如是，君心無自欺。","能依四十字，可立德清碑。"]', '["亂世人多事，耕桑或失时。","不闻寬賦斂，因此轉流離。","天意未如是，君心無自欺。","能依四十字，可立德清碑。"]', '诗', 'shi', '', NULL, '送人宰德清 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fba50569-b399-4132-b3a0-7ed030819799', '寄竇處士', '寄竇处士', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["漳水醉中別，今來猶未醒。","半生因酒廢，大國幾時寧。","海畔將軍柳，天邊處士星。","遊人不可見，春入亂山青。"]', '["漳水醉中別，今来猶未醒。","半生因酒廢，大国幾时寧。","海畔將軍柳，天邊处士星。","游人不可见，春入亂山青。"]', '诗', 'shi', '', NULL, '寄竇處士 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31295832-4533-4197-a1eb-56f3100b77bb', '題歷山舜祠', '題歷山舜祠', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["昔舜曾耕地，遺風日寂寥。","世人那肯祭，大聖不興妖。","殿宇秋霖壞，杉松野火燒。","時訛競淫祀，絲竹醉山魈。"]', '["昔舜曾耕地，遺风日寂寥。","世人那肯祭，大聖不兴妖。","殿宇秋霖壞，杉松野火燒。","时訛競淫祀，絲竹醉山魈。"]', '诗', 'shi', '', NULL, '題歷山舜祠 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21b2008e-4601-4595-ada2-fc353e4d20bd', '贈李蒙叟', '贈李蒙叟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["在我成何事，逢君更勸吟。","縱饒不得力，猶勝別勞心。","凡事有興廢，詩名無古今。","百年能幾日，忍不惜光陰。"]', '["在我成何事，逢君更勸吟。","縱饒不得力，猶勝別勞心。","凡事有兴廢，诗名無古今。","百年能幾日，忍不惜光陰。"]', '诗', 'shi', '', NULL, '贈李蒙叟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddea20a3-2860-4bfb-84b3-7e82005f250a', '維揚冬末寄幕中二從事', '維揚冬末寄幕中二從事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["聞道長溪尉，相留一館閑。","□□□□□，尚隔幾重山。","爲旅春風外，懷人夜雨間。","年來疎覽鏡，怕見減朱顏。"]', '["闻道长溪尉，相留一館闲。","□□□□□，尚隔幾重山。","爲旅春风外，懷人夜雨间。","年来疎覽镜，怕见減朱顏。"]', '诗', 'shi', '', NULL, '維揚冬末寄幕中二從事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b319e46c-66eb-41a4-a006-25b7df145bde', '和吳太守罷郡山村偶題二首 一', '和吳太守罷郡山村偶題二首 一', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["罷郡饒山興，村家不惜過。","官情隨日薄，詩思入秋多。","野獸眠低草，池禽浴動荷。","眼前餘政在，不似有干戈。"]', '["罷郡饒山兴，村家不惜過。","官情隨日薄，诗思入秋多。","野獸眠低草，池禽浴动荷。","眼前餘政在，不似有干戈。"]', '诗', 'shi', '', NULL, '和吳太守罷郡山村偶題二首 一 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f6ac250-3980-4bd1-baac-9bd8b69312e5', '和吳太守罷郡山村偶題二首 二', '和吳太守罷郡山村偶題二首 二', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["快活田翁輩，常言化育時。","縱饒稽歲月，猶說向孫兒。","茅屋梁和節，茶盤果帶枝。","相傳終不忘，何必立生祠。"]', '["快活田翁輩，常言化育时。","縱饒稽歲月，猶说向孫兒。","茅屋梁和節，茶盤果带枝。","相傳終不忘，何必立生祠。"]', '诗', 'shi', '', NULL, '和吳太守罷郡山村偶題二首 二 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3897d27c-48a4-4be7-af91-84a5e74333b3', '亂後送友人歸湘中', '亂後送友人归湘中', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["家枕三湘岸，門前即釣磯。","漁竿壯歲別，鶴髮亂時歸。","岳暖無猿叫，江春有燕飛。","平生書劒在，莫便學忘機。"]', '["家枕三湘岸，门前即釣磯。","漁竿壯歲別，鹤髮亂时归。","岳暖無猿叫，江春有燕飞。","平生书劒在，莫便学忘機。"]', '诗', 'shi', '', NULL, '亂後送友人歸湘中 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d50d7fa4-9a51-49a8-bdbb-b2f306957976', '送紫陽僧歸廬岳舊寺', '送紫陽僧归廬岳旧寺', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["紫衣明主贈，歸寺感先師。","受業恩難報，開堂影不知。","松風欹枕夜，山雪下樓時。","此際無人會，微吟復歛眉。"]', '["紫衣明主贈，归寺感先師。","受業恩难報，开堂影不知。","松风欹枕夜，山雪下楼时。","此際無人會，微吟复歛眉。"]', '诗', 'shi', '', NULL, '送紫陽僧歸廬岳舊寺 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e64b010c-8cc4-4ff1-b8c6-eaedb42376ee', '和劉評事送海禪和歸山', '和劉評事送海禪和归山', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["衲外元無象，言尋那路尋。","問禪將底說，傳印得何心。","未了羣山淺，難休一室深。","伏魔寧是獸，巢頂亦非禽。","觀色風驅霧，聽聲雪灑林。","凡歸是歸處，不必指高岑。"]', '["衲外元無象，言尋那路尋。","问禪將底说，傳印得何心。","未了羣山淺，难休一室深。","伏魔寧是獸，巢頂亦非禽。","观色风驱霧，听声雪灑林。","凡归是归处，不必指高岑。"]', '诗', 'shi', '', NULL, '和劉評事送海禪和歸山 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b00a57f-55ca-4e88-91e8-5e4e6e8a2b29', '御溝柳', '御溝柳', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["律到御溝春，溝邊柳色新。","細籠穿禁水，輕拂入朝人。","日近韶光早，天低聖澤勻。","谷鶯棲未穩，宮女畫難真。","楚國空搖浪，隋堤暗惹塵。","如何帝城裏，先得覆龍津。"]', '["律到御溝春，溝邊柳色新。","細籠穿禁水，轻拂入朝人。","日近韶光早，天低聖澤勻。","谷鶯棲未穩，宮女畫难真。","楚国空搖浪，隋堤暗惹塵。","如何帝城裏，先得覆龙津。"]', '诗', 'shi', '', NULL, '御溝柳 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9de8077-8661-4700-be78-a33b1338d7a7', '冬末同友人泛瀟湘', '冬末同友人泛瀟湘', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["殘臘泛舟何處好，最多吟興是瀟湘。","就船買得魚偏美，踏雪沽來酒倍香。","猿到夜深啼嶽麓，鴈知春近別衡陽。","與君剩採江山景，裁取新詩入帝鄉。"]', '["殘臘泛舟何处好，最多吟兴是瀟湘。","就船買得鱼偏美，踏雪沽来酒倍香。","猿到夜深啼嶽麓，鴈知春近別衡陽。","與君剩採江山景，裁取新诗入帝乡。"]', '诗', 'shi', '', NULL, '冬末同友人泛瀟湘 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e27b8c42-7060-46aa-a48d-adcda16cc561', '贈李鐔', '贈李鐔', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["君行君文天合知，見君如此我興悲。","秪殘三口兵戈後，纔到孤村雨雪時。","著臥衣裳難辦洗，旋求糧食莫供炊。","地鑪不暖柴枝濕，猶把蒙求授小兒。"]', '["君行君文天合知，见君如此我兴悲。","秪殘三口兵戈後，纔到孤村雨雪时。","著臥衣裳难辦洗，旋求糧食莫供炊。","地鑪不暖柴枝濕，猶把蒙求授小兒。"]', '诗', 'shi', '', NULL, '贈李鐔 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b534ee6-5767-4853-9f66-f1927c36da70', '旅中臥病', '旅中臥病', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["秋來誰料病相縈，枕上心猶算去程。","風射破窗燈易滅，月穿疎屋夢難成。","故園何啻三千里，新鴈纔聞一兩聲。","我自與人無舊分，非干人與我無情。"]', '["秋来誰料病相縈，枕上心猶算去程。","风射破窗灯易滅，月穿疎屋梦难成。","故园何啻三千里，新鴈纔闻一兩声。","我自與人無旧分，非干人與我無情。"]', '诗', 'shi', '', NULL, '旅中臥病 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb61bcc7-a89e-4301-ad2d-e9134a6b03ec', '旅泊遇郡中叛亂示同志', '旅泊遇郡中叛亂示同志', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["握手相看誰敢言，軍家刀劒在腰邊。","遍搜寶貨無藏處，亂殺平人不怕天。","古寺拆爲修寨木，荒墳開作甃城塼。","郡侯逐出渾閑事，正是鑾輿幸蜀年。"]', '["握手相看誰敢言，軍家刀劒在腰邊。","遍搜寶貨無藏处，亂殺平人不怕天。","古寺拆爲修寨木，荒墳开作甃城塼。","郡侯逐出渾闲事，正是鑾輿幸蜀年。"]', '诗', 'shi', '', NULL, '旅泊遇郡中叛亂示同志 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cf56c99-0beb-42a8-806b-1609e28180a7', '贈秋浦張明府', '贈秋浦張明府', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["君爲秋浦三年宰，萬慮關心兩鬢知。","人事旋生當路縣，吏才難展用兵時。","農夫背上題軍號，賈客船頭插戰旗。","他日親知問官況，但教吟取杜家詩。"]', '["君爲秋浦三年宰，万慮关心兩鬢知。","人事旋生當路縣，吏才难展用兵时。","農夫背上題軍號，賈客船头插戰旗。","他日親知问官況，但教吟取杜家诗。"]', '诗', 'shi', '', NULL, '贈秋浦張明府 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fccf441-09ef-4974-b6d8-8615bbe567b7', '雪', '雪', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["風攪長空寒骨生，光於曉色報窗明。","江湖不見飛禽影，巖谷時聞折竹聲。","巢穴幾多相似處，路岐兼得一般平。","擁袍公子休言冷，中有樵夫跣足行。"]', '["风攪长空寒骨生，光於晓色報窗明。","江湖不见飞禽影，巖谷时闻折竹声。","巢穴幾多相似处，路岐兼得一般平。","擁袍公子休言冷，中有樵夫跣足行。"]', '诗', 'shi', '', NULL, '雪 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('093dd01f-1a80-48a7-ae02-e27eb2a113e7', '題廬嶽劉處士草堂', '題廬嶽劉处士草堂', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["仙境閑尋採藥翁，草堂留話一宵同。","若看山下雲深處，直是人間路不通。","泉領藕花來洞口，月將松影過溪東。","求名心在閑難遂，明日馬蹄塵土中。"]', '["仙境闲尋採藥翁，草堂留話一宵同。","若看山下云深处，直是人间路不通。","泉領藕花来洞口，月將松影過溪东。","求名心在闲难遂，明日马蹄塵土中。"]', '诗', 'shi', '', NULL, '題廬嶽劉處士草堂 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbda0ac7-3684-4d28-a82f-54f7d992625e', '山中寄詩友', '山中寄诗友', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["山深長恨少同人，覽景無時不憶君。","庭果自從霜後熟，野猿頻向屋邊聞。","琴臨秋水彈明月，酒就東山酌白雲。","仙桂算攀攀合得，平生心力盡於文。"]', '["山深长恨少同人，覽景無时不憶君。","庭果自從霜後熟，野猿頻向屋邊闻。","琴臨秋水彈明月，酒就东山酌白云。","仙桂算攀攀合得，平生心力尽於文。"]', '诗', 'shi', '', NULL, '山中寄詩友 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a404f717-91a7-45d8-8d02-964f3ba588ce', '秋宿臨江驛', '秋宿臨江驛', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["南來北去二三年，年去年來兩鬢斑。","舉世盡從愁裏老，誰人肯向死前閑。","漁舟火影寒歸浦，驛路鈴聲夜過山。","身事未成歸未得，聽猿鞭馬入長關。"]', '["南来北去二三年，年去年来兩鬢斑。","舉世尽從愁裏老，誰人肯向死前闲。","漁舟火影寒归浦，驛路鈴声夜過山。","身事未成归未得，听猿鞭马入长关。"]', '诗', 'shi', '', NULL, '秋宿臨江驛 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ecd3fc-511a-4b49-9137-34b1e1a7786f', '題瓦棺寺真上人院矮檜', '題瓦棺寺真上人院矮檜', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["天生仙檜是長材，栽檜希逢此最低。","一自舊山來砌畔，幾番凡木與雲齊。","迴無斜影教僧踏，免有閑枝引鶴棲。","今日偶題題似着，不知題後更誰題。"]', '["天生仙檜是长材，栽檜希逢此最低。","一自旧山来砌畔，幾番凡木與云齊。","迴無斜影教僧踏，免有闲枝引鹤棲。","今日偶題題似着，不知題後更誰題。"]', '诗', 'shi', '', NULL, '題瓦棺寺真上人院矮檜 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5255d88-2dd1-45ad-806c-f8fda1bd2d43', '江下初秋寓泊', '江下初秋寓泊', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["濛濛煙雨蔽江村，江館愁人好斷魂。","自別家來生白髮，爲侵星起謁朱門。","也知柳欲開春眼，爭奈萍無入土根。","兄弟無書鴈歸北，一聲聲覺苦於猿。"]', '["濛濛煙雨蔽江村，江館愁人好斷魂。","自別家来生白髮，爲侵星起謁朱门。","也知柳欲开春眼，爭奈萍無入土根。","兄弟無书鴈归北，一声声覺苦於猿。"]', '诗', 'shi', '', NULL, '江下初秋寓泊 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('541e8bfe-cadd-41e9-8f35-dea5a065d888', '投從叔補闕', '投從叔補闕', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["吾宗不謁謁詩宗，常仰門風繼國風。","空有篇章傳海內，更無親族在朝中。","其來雖媿源流淺，所得須憐雅頌同。","三十年吟到今日，不妨私薦亦成公。"]', '["吾宗不謁謁诗宗，常仰门风繼国风。","空有篇章傳海內，更無親族在朝中。","其来雖媿源流淺，所得須怜雅頌同。","三十年吟到今日，不妨私薦亦成公。"]', '诗', 'shi', '', NULL, '投從叔補闕 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d884c2e5-8cda-4bc4-991b-6225c2072424', '贈張員外兒', '贈張員外兒', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["張公一子才三歲，聞客吟聲便出來。","喚物舌頭猶未穩，誦詩心孔迥然開。","天生便是成家慶，年長終爲間世才。","月裏桂枝知有分，不勞諸丈作梯媒。"]', '["張公一子才三歲，闻客吟声便出来。","喚物舌头猶未穩，誦诗心孔迥然开。","天生便是成家慶，年长終爲间世才。","月裏桂枝知有分，不勞諸丈作梯媒。"]', '诗', 'shi', '', NULL, '贈張員外兒 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee446c46-8054-4928-854c-228b46d9e16a', '重陽日有作', '重陽日有作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一爲重陽上古臺，亂時誰見菊花開。","偷𢸧白髮真堪笑，牢鏁黃金實可哀。","是箇少年皆老去，爭知荒塚不榮來。","大家拍手高聲唱，日未沈山且莫迴。"]', '["一爲重陽上古台，亂时誰见菊花开。","偷𢸧白髮真堪笑，牢鏁黄金實可哀。","是箇少年皆老去，爭知荒塚不榮来。","大家拍手高声唱，日未沈山且莫迴。"]', '诗', 'shi', '', NULL, '重陽日有作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b76a0f4-ff08-4038-b195-e253b44efaeb', '入關寄九華友人', '入关寄九华友人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["坐牀難穩露蟬新，便作東西馬上身。","醲酒却輸耽睡客，好山翻對不吟人。","無多志氣禁離別，強半年光屬苦辛。","篋裏篇章頭上雪，未知誰戀杏園春。"]', '["坐牀难穩露蟬新，便作东西马上身。","醲酒却輸耽睡客，好山翻对不吟人。","無多志氣禁離別，強半年光屬苦辛。","篋裏篇章头上雪，未知誰戀杏园春。"]', '诗', 'shi', '', NULL, '入關寄九華友人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9feef88b-7433-477b-856b-3e8b8d2491cb', '送李鐔遊新安', '送李鐔游新安', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["邯鄲李鐔才崢嶸，酒狂詩逸難干名。","氣直不與兒輩洽，醉來擬共天公爭。","孤店夜燒枯葉坐，亂時秋踏早霜行。","一間茅屋住不穩，剛出爲人平不平。"]', '["邯鄲李鐔才崢嶸，酒狂诗逸难干名。","氣直不與兒輩洽，醉来擬共天公爭。","孤店夜燒枯葉坐，亂时秋踏早霜行。","一间茅屋住不穩，剛出爲人平不平。"]', '诗', 'shi', '', NULL, '送李鐔遊新安 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45c3b6bd-bcd2-4eca-a5cd-ed31b6c12034', '冬末自長沙遊桂嶺留獻所知', '冬末自长沙游桂嶺留獻所知', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["家隔重湖歸未期，更堪南去別深知。","前程笑到山多處，上馬愁逢歲盡時。","四海內無容足地，一生中有苦心詩。","朱門秪見朱門事，獨把孤寒問阿誰。"]', '["家隔重湖归未期，更堪南去別深知。","前程笑到山多处，上马愁逢歲尽时。","四海內無容足地，一生中有苦心诗。","朱门秪见朱门事，独把孤寒问阿誰。"]', '诗', 'shi', '', NULL, '冬末自長沙遊桂嶺留獻所知 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af9a3730-053c-4b11-881c-b3b760b67470', '送福昌周繇少府歸寧兼謀隱', '送福昌周繇少府归寧兼謀隐', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["少見古人無遠慮，如君真得古人情。","登科作尉官雖小，避世安親祿已榮。","一路水雲生隱思，幾山猿鳥認吟聲。","知君未作終焉計，要著文章待太平。"]', '["少见古人無远慮，如君真得古人情。","登科作尉官雖小，避世安親祿已榮。","一路水云生隐思，幾山猿鸟認吟声。","知君未作終焉計，要著文章待太平。"]', '诗', 'shi', '', NULL, '送福昌周繇少府歸寧兼謀隱 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fdfa53c-8575-4c68-aec2-9a67274c4ac4', '賀顧雲侍御府主與子弟奏官', '賀顧云侍御府主與子弟奏官', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["青桂朱袍不賀兄，賀兄榮是見兒榮。","孝經始向堂前徹，官誥當從幕下迎。","戲把藍袍包果子，嬌將竹笏惱先生。","自慙亂世無知己，弟姪鞭牛傍隴耕。"]', '["青桂朱袍不賀兄，賀兄榮是见兒榮。","孝經始向堂前徹，官誥當從幕下迎。","戲把藍袍包果子，嬌將竹笏惱先生。","自慙亂世無知己，弟姪鞭牛傍隴耕。"]', '诗', 'shi', '', NULL, '賀顧雲侍御府主與子弟奏官 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9258cfae-35aa-40a6-81a2-1feeeeb7403e', '舟行即事', '舟行即事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["年少髭鬚雪欲侵，別家三日幾般心。","朝隨賈客憂風色，夜逐漁翁宿葦林。","秋水鷺飛紅蓼晚，暮山猿叫白雲深。","重陽酒熟茱萸紫，却向江頭倚棹吟。"]', '["年少髭鬚雪欲侵，別家三日幾般心。","朝隨賈客憂风色，夜逐漁翁宿葦林。","秋水鷺飞紅蓼晚，暮山猿叫白云深。","重陽酒熟茱萸紫，却向江头倚棹吟。"]', '诗', 'shi', '', NULL, '舟行即事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1962eeeb-5152-4ff1-84c4-91e9ebf347ab', '亂後山居', '亂後山居', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["從亂移家擬傍山，今來方辦買山錢。","九州有路休爲客，百歲無愁即是仙。","野叟竝田鋤暮雨，溪禽同石立寒煙。","他人似我還應少，如此安貧亦荷天。"]', '["從亂移家擬傍山，今来方辦買山錢。","九州有路休爲客，百歲無愁即是仙。","野叟竝田鋤暮雨，溪禽同石立寒煙。","他人似我還應少，如此安貧亦荷天。"]', '诗', 'shi', '', NULL, '亂後山居 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cca2f682-f5ca-400c-8bdb-2913ea9713d0', '山居寄同志', '山居寄同志', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["茅齋深僻絕輪蹄，門徑緣莎細接溪。","垂釣石臺依竹壘，待賓茶竈就巖泥。","風生谷口猿相叫，月照松頭鶴竝棲。","不是無端過時日，擬從窗下躡雲梯。"]', '["茅斋深僻絕輪蹄，门徑緣莎細接溪。","垂釣石台依竹壘，待賓茶竈就巖泥。","风生谷口猿相叫，月照松头鹤竝棲。","不是無端過时日，擬從窗下躡云梯。"]', '诗', 'shi', '', NULL, '山居寄同志 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17613c91-f1ba-41ba-b718-c295bd27d900', '將入關安陸遇兵寇', '將入关安陸遇兵寇', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["家貧無計早離家，離得家來蹇滯多。","已是數程行雨雪，更堪中路阻兵戈。","幾州戶口看成血，一旦天心却許和。","四面煙塵少無處，不知吾土自如何。"]', '["家貧無計早離家，離得家来蹇滯多。","已是數程行雨雪，更堪中路阻兵戈。","幾州戶口看成血，一旦天心却許和。","四面煙塵少無处，不知吾土自如何。"]', '诗', 'shi', '', NULL, '將入關安陸遇兵寇 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cf12da0-6e86-42bb-82c4-22b9f14f1b2d', '夏日登友人書齋林亭', '夏日登友人书斋林亭', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["暑天長似秋天冷，帶郭林亭畫不如。","蟬噪檻前遮日竹，鷺窺池面弄萍魚。","拋山野客橫琴醉，種藥家僮踏雪鋤。","衆惜君才堪上第，莫因居此與名疎。"]', '["暑天长似秋天冷，带郭林亭畫不如。","蟬噪檻前遮日竹，鷺窺池面弄萍鱼。","拋山野客橫琴醉，種藥家僮踏雪鋤。","衆惜君才堪上第，莫因居此與名疎。"]', '诗', 'shi', '', NULL, '夏日登友人書齋林亭 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e51fa3c9-90ca-4234-b688-531140b9f5ad', '寄臨海姚中丞', '寄臨海姚中丞', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["夏辭旌斾已秋深，永夕思量淚滿襟。","風月易斑搜句鬢，星霜難改感恩心。","尋花洞裏連春醉，望海樓中徹曉吟。","雖有夢魂知處所，去來多被角聲侵。"]', '["夏辞旌斾已秋深，永夕思量泪满襟。","风月易斑搜句鬢，星霜难改感恩心。","尋花洞裏連春醉，望海楼中徹晓吟。","雖有梦魂知处所，去来多被角声侵。"]', '诗', 'shi', '', NULL, '寄臨海姚中丞 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbdbaeba-abe5-4309-9d92-6c0e74026981', '秋日閑居寄先達', '秋日闲居寄先達', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["到頭身事欲何爲，窗下工夫鬢上知。","乍可百年無稱意，難教一日不吟詩。","風驅早鴈衝湖色，雨挫殘蟬點柳枝。","自古書生也如此，獨堪惆悵是明時。"]', '["到头身事欲何爲，窗下工夫鬢上知。","乍可百年無稱意，难教一日不吟诗。","风驱早鴈衝湖色，雨挫殘蟬点柳枝。","自古书生也如此，独堪惆悵是明时。"]', '诗', 'shi', '', NULL, '秋日閑居寄先達 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2803d624-a72d-4560-9aad-f8feec6329c3', '題覺禪和', '題覺禪和', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["少見修行得似師，茅堂佛像亦隨時。","禪衣衲後雲藏線，夏臘高來雪印眉。","耕地誡侵連塚土，伐薪教護帶巢枝。","有時問着經中事，却道山僧總不知。"]', '["少见修行得似師，茅堂佛像亦隨时。","禪衣衲後云藏線，夏臘高来雪印眉。","耕地誡侵連塚土，伐薪教護带巢枝。","有时问着經中事，却道山僧總不知。"]', '诗', 'shi', '', NULL, '題覺禪和 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f992df1-2c49-4b4e-861b-4ce2e217608f', '感秋', '感秋', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["年年名路謾辛勤，襟袖空多馬上塵。","畫戟門前難作客，釣魚船上易安身。","冷煙黏柳蟬聲老，寒渚澄星雁叫新。","自是儂家無住處，不關天地窄於人。"]', '["年年名路謾辛勤，襟袖空多马上塵。","畫戟门前难作客，釣鱼船上易安身。","冷煙黏柳蟬声老，寒渚澄星雁叫新。","自是儂家無住处，不关天地窄於人。"]', '诗', 'shi', '', NULL, '感秋 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e556de9-4f5d-4c89-b62b-3706ca72b464', '題德玄上人院', '題德玄上人院', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["刳得心來忙處閑，閑中方寸闊於天。","浮生自是無空性，長壽何曾有百年。","罷定磬敲松罅月，解眠茶煮石根泉。","我雖未似師披衲，此理同師悟了然。"]', '["刳得心来忙处闲，闲中方寸闊於天。","浮生自是無空性，长壽何曾有百年。","罷定磬敲松罅月，解眠茶煮石根泉。","我雖未似師披衲，此理同師悟了然。"]', '诗', 'shi', '', NULL, '題德玄上人院 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81170ea7-4553-4bce-813d-f8bbd8265e1b', '春日山居寄友人', '春日山居寄友人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["野吟何處最相宜，春景暄和好入詩。","高下麥苗新雨後，淺深山色晚晴時。","半巖雲脚風牽斷，平野花枝鳥踏垂。","倒載干戈是何日，近來麋鹿欲相隨。"]', '["野吟何处最相宜，春景暄和好入诗。","高下麦苗新雨後，淺深山色晚晴时。","半巖云脚风牽斷，平野花枝鸟踏垂。","倒載干戈是何日，近来麋鹿欲相隨。"]', '诗', 'shi', '', NULL, '春日山居寄友人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('930dd667-3b03-4929-b072-162f39835bc5', '懷廬嶽舊隱', '懷廬嶽旧隐', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一別三年長在夢，夢中時躡石稜層。","泉聲入夜方堪聽，山色逢秋始好登。","巖鹿慣隨鋤藥叟，溪鷗不怕洗苔僧。","人間有許多般事，求要身閑直未能。"]', '["一別三年长在梦，梦中时躡石稜層。","泉声入夜方堪听，山色逢秋始好登。","巖鹿慣隨鋤藥叟，溪鷗不怕洗苔僧。","人间有許多般事，求要身闲直未能。"]', '诗', 'shi', '', NULL, '懷廬嶽舊隱 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6665c96d-592e-43fe-9982-e2e5b0d69578', '投長沙裴侍郎', '投长沙裴侍郎', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["此身雖賤道長存，非謁朱門謁孔門。","秪望至公將卷讀，不求朝士致書論。","垂綸雨結漁鄉思，吹木風傳鴈夜魂。","男子受恩須有地，平生不受等閑恩。"]', '["此身雖賤道长存，非謁朱门謁孔门。","秪望至公將卷读，不求朝士致书論。","垂綸雨結漁乡思，吹木风傳鴈夜魂。","男子受恩須有地，平生不受等闲恩。"]', '诗', 'shi', '', NULL, '投長沙裴侍郎 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19f32680-eea2-48d2-b17c-65cdd4fc5e4c', '和友人見題山居', '和友人见題山居', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["避時多喜葺居成，七字君題萬象清。","開戶曉雲連地白，訪人秋月滿山明。","庭前樹瘦霜來影，洞口泉噴雨後聲。","有景供吟且如此，算來何必躁於名。"]', '["避时多喜葺居成，七字君題万象清。","开戶晓云連地白，訪人秋月满山明。","庭前樹瘦霜来影，洞口泉噴雨後声。","有景供吟且如此，算来何必躁於名。"]', '诗', 'shi', '', NULL, '和友人見題山居 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2993bfb9-fde3-4802-8dd4-25a1261fa22f', '獻長沙王侍郎', '獻长沙王侍郎', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["文星漸見射台星，皆仰爲霖沃衆情。","天澤逼來逢聖主，辭林盛去得書生。","雲粧嶽色供吟景，月浩湘流遞政聲。","美化事多難諷誦，未如耕釣口分明。"]', '["文星漸见射台星，皆仰爲霖沃衆情。","天澤逼来逢聖主，辞林盛去得书生。","云粧嶽色供吟景，月浩湘流遞政声。","美化事多难諷誦，未如耕釣口分明。"]', '诗', 'shi', '', NULL, '獻長沙王侍郎 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('147519d6-fcd8-4f85-b24c-a439aded4190', '春日登樓遇雨', '春日登楼遇雨', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["忽地晴天作雨天，全無暑氣似秋間。","看看水沒來時路，漸漸雲藏望處山。","風趁鷺鷥雙出葦，浪催漁父盡歸灣。","一心準擬閑登眺，却被詩情使不閑。"]', '["忽地晴天作雨天，全無暑氣似秋间。","看看水沒来时路，漸漸云藏望处山。","风趁鷺鷥雙出葦，浪催漁父尽归灣。","一心準擬闲登眺，却被诗情使不闲。"]', '诗', 'shi', '', NULL, '春日登樓遇雨 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae6e4fe6-1b49-4c2c-b0ae-1692a59b9072', '春日行次錢塘却寄台州姚中丞', '春日行次錢塘却寄台州姚中丞', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["豈爲無心求上第，難安帝里爲家貧。","江南江北閑爲客，潮去潮來老却人。","兩岸雨收鶯語柳，一樓風滿角吹春。","花前不獨垂鄉淚，曾是朱門寄食身。"]', '["豈爲無心求上第，难安帝里爲家貧。","江南江北闲爲客，潮去潮来老却人。","兩岸雨收鶯語柳，一楼风满角吹春。","花前不独垂乡泪，曾是朱门寄食身。"]', '诗', 'shi', '', NULL, '春日行次錢塘却寄台州姚中丞 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c89c8f-c977-4348-a5cd-daee299ce601', '投江上崔尚書', '投江上崔尚书', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["此生何路出塵埃，猶把中才謁上才。","閉戶十年專筆硯，仰天無處認梯媒。","馬前霜葉催歸去，枕上邊鴻喚覺來。","若許登門換鬐鬣，必應辛苦事風雷。"]', '["此生何路出塵埃，猶把中才謁上才。","閉戶十年專笔硯，仰天無处認梯媒。","马前霜葉催归去，枕上邊鴻喚覺来。","若許登门換鬐鬣，必應辛苦事风雷。"]', '诗', 'shi', '', NULL, '投江上崔尚書 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aa3fb25-59cc-4143-acaf-7ebae6b32afb', '書事投所知', '书事投所知', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["古陌寒風來去吹，馬蹄塵旋上麻衣。","雖然干祿無休意，爭奈趨時不見機。","詩思趁雲從嶽涌，鄉心隨鴈遶湖飛。","肯將骨肉輕離別，未遇人知未得歸。"]', '["古陌寒风来去吹，马蹄塵旋上麻衣。","雖然干祿無休意，爭奈趨时不见機。","诗思趁云從嶽涌，乡心隨鴈遶湖飞。","肯將骨肉轻離別，未遇人知未得归。"]', '诗', 'shi', '', NULL, '書事投所知 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58fe6dd6-acb1-4032-99fb-6c72c94d2f23', '秋日湖外書事', '秋日湖外书事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["十五年來筆硯功，秪今猶在苦貧中。","三秋客路湖光外，萬里鄉關楚邑東。","鳥逕杖藜山翳雨，猿林欹枕樹搖風。","朱門處處若相似，此命到頭通不通。"]', '["十五年来笔硯功，秪今猶在苦貧中。","三秋客路湖光外，万里乡关楚邑东。","鸟逕杖藜山翳雨，猿林欹枕樹搖风。","朱门处处若相似，此命到头通不通。"]', '诗', 'shi', '', NULL, '秋日湖外書事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1c67ddb-23e0-494b-9399-8329061c0713', '題宗上人舊院', '題宗上人旧院', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["此院重來事事乖，半欹茅屋草侵堦。","啄生鴉憶啼松枿，接果猿思嘯石崖。","壁上塵黏蒲葉扇，牀前苔爛筍皮鞋。","分明記得談空日，不向秋風更愴懷。"]', '["此院重来事事乖，半欹茅屋草侵堦。","啄生鴉憶啼松枿，接果猿思嘯石崖。","壁上塵黏蒲葉扇，牀前苔爛筍皮鞋。","分明記得談空日，不向秋风更愴懷。"]', '诗', 'shi', '', NULL, '題宗上人舊院 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acf78547-a9c5-414d-be78-4d25a84e17e8', '亂後出山逢高員外', '亂後出山逢高員外', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["自從亂後別京關，一入煙蘿十五年。","重出故山生白髮，却裝新卷謁清賢。","窗迴旅夢城頭角，柳結鄉愁雨後蟬。","名姓暗投心暗祝，永期收拾向門前。"]', '["自從亂後別京关，一入煙蘿十五年。","重出故山生白髮，却裝新卷謁清賢。","窗迴旅梦城头角，柳結乡愁雨後蟬。","名姓暗投心暗祝，永期收拾向门前。"]', '诗', 'shi', '', NULL, '亂後出山逢高員外 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('052ba7a8-54b8-4ee6-947e-70f6644fba0b', '贈友人罷舉赴交趾辟命', '贈友人罷舉赴交趾辟命', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["罷却名場擬入秦，南行無罪似流人。","縱經商嶺非馳驛，須過長沙弔逐臣。","舶載海奴鐶硾耳，象駝蠻女綵纏身。","如何待取丹霄桂，別赴嘉招作上賓。"]', '["罷却名場擬入秦，南行無罪似流人。","縱經商嶺非驰驛，須過长沙弔逐臣。","舶載海奴鐶硾耳，象駝蠻女綵纏身。","如何待取丹霄桂，別赴嘉招作上賓。"]', '诗', 'shi', '', NULL, '贈友人罷舉赴交趾辟命 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('293466f5-27ef-4a4c-8c90-75eefb445669', '山中寡婦', '山中寡婦', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["夫因兵死守蓬茅，麻苧衣衫鬢髮焦。","桑柘廢來猶納稅，田園荒後尚徵苗。","時挑野菜和根煮，旋斫生柴帶葉燒。","任是深山更深處，也應無計避征徭。"]', '["夫因兵死守蓬茅，麻苧衣衫鬢髮焦。","桑柘廢来猶納稅，田园荒後尚徵苗。","时挑野菜和根煮，旋斫生柴带葉燒。","任是深山更深处，也應無計避征徭。"]', '诗', 'shi', '', NULL, '山中寡婦 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e8386a3-3292-4ca2-b50f-f61207641dba', '訪蔡融因題', '訪蔡融因題', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["杖藜時復過荒郊，來到君家不忍拋。","每見苦心修好事，未嘗開口怨平交。","一溪寒色漁收網，半樹斜陽鳥傍巢。","必若天工主人事，肯交吾子委衡茅。"]', '["杖藜时复過荒郊，来到君家不忍拋。","每见苦心修好事，未嘗开口怨平交。","一溪寒色漁收網，半樹斜陽鸟傍巢。","必若天工主人事，肯交吾子委衡茅。"]', '诗', 'shi', '', NULL, '訪蔡融因題 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93c6ab71-b30d-4a95-ae38-99024518c486', '閑居書事', '闲居书事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["竹門茅屋帶村居，數畝生涯自有餘。","鬢白祗應秋鍊句，眼昏多爲夜抄書。","鴈驚風浦漁燈動，猿叫霜林橡實疎。","待得功成即西去，時清不問命何如。"]', '["竹门茅屋带村居，數畝生涯自有餘。","鬢白祗應秋鍊句，眼昏多爲夜抄书。","鴈驚风浦漁灯动，猿叫霜林橡實疎。","待得功成即西去，时清不问命何如。"]', '诗', 'shi', '', NULL, '閑居書事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5de5f40d-33bc-44e3-96be-4b89ea5c4676', '友人贈舍弟依韻戲和', '友人贈舍弟依韻戲和', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["吾家此弟有何知，多媿君開道業基。","不覺裹頭成大漢，昨來竹馬作童兒。","還緣世遇兵戈鬧，祗恐身修禮樂遲。","及見和詩詩自好，碢公不到更何時。"]', '["吾家此弟有何知，多媿君开道業基。","不覺裹头成大漢，昨来竹马作童兒。","還緣世遇兵戈鬧，祗恐身修禮乐遲。","及见和诗诗自好，碢公不到更何时。"]', '诗', 'shi', '', NULL, '友人贈舍弟依韻戲和 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96e68215-27c3-42b5-9055-308a852fdcdb', '亂後逢村叟', '亂後逢村叟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["經亂衰翁居破村，村中何事不傷魂。","因供寨木無桑柘，爲著鄉兵絕子孫。","還似平寧徵賦稅，未嘗州縣畧安存。","至於雞犬皆星散，日落前山獨倚門。"]', '["經亂衰翁居破村，村中何事不傷魂。","因供寨木無桑柘，爲著乡兵絕子孫。","還似平寧徵賦稅，未嘗州縣畧安存。","至於雞犬皆星散，日落前山独倚门。"]', '诗', 'shi', '', NULL, '亂後逢村叟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dac1baa2-4987-4aa6-af91-fb9b536a9cb9', '贈元上人', '贈元上人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["多少僧中僧行高，偈成流落遍僧抄。","經窗月靜灘聲到，石逕人稀蘚色交。","垂露竹黏蟬落殼，窣雲松載鶴棲巢。","煮茶童子閑勝我，猶得依時把磬敲。"]', '["多少僧中僧行高，偈成流落遍僧抄。","經窗月静灘声到，石逕人稀蘚色交。","垂露竹黏蟬落殼，窣云松載鹤棲巢。","煮茶童子闲勝我，猶得依时把磬敲。"]', '诗', 'shi', '', NULL, '贈元上人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb87380a-59c2-4109-9151-c8a5228328ca', '下第東歸道中作', '下第东归道中作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一迴落第一寧親，多是途中過却春。","心火不銷雙鬢雪，眼泉難濯滿衣塵。","苦吟風月唯添病，遍識公卿未免貧。","馬壯金多有官者，榮歸却笑讀書人。"]', '["一迴落第一寧親，多是途中過却春。","心火不銷雙鬢雪，眼泉难濯满衣塵。","苦吟风月唯添病，遍識公卿未免貧。","马壯金多有官者，榮归却笑读书人。"]', '诗', 'shi', '', NULL, '下第東歸道中作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0950174c-6529-49b6-b5dd-9965784d246a', '夏日留題張山人林亭', '夏日留題張山人林亭', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["此中偏稱夏中遊，時有風來暑氣收。","澗底松搖千尺雨，庭中竹撼一窗秋。","求猿句寄山深寺，乞鶴書傳海畔洲。","閑與先生話身事，浮名薄宦總悠悠。"]', '["此中偏稱夏中游，时有风来暑氣收。","澗底松搖千尺雨，庭中竹撼一窗秋。","求猿句寄山深寺，乞鹤书傳海畔洲。","闲與先生話身事，浮名薄宦總悠悠。"]', '诗', 'shi', '', NULL, '夏日留題張山人林亭 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e356125-1079-41a1-abf1-b32d8e7c7db9', '傷病馬', '傷病马', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["此馬堪憐力壯時，細勻行步恐塵知。","騎來未省將鞭觸，病後長教覓藥醫。","顧主強擡和淚眼，就人輕刷帶瘡皮。","祗今筋骨渾全在，春暖莎青放未遲。"]', '["此马堪怜力壯时，細勻行步恐塵知。","騎来未省將鞭觸，病後长教覓藥醫。","顧主強擡和泪眼，就人轻刷带瘡皮。","祗今筋骨渾全在，春暖莎青放未遲。"]', '诗', 'shi', '', NULL, '傷病馬 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e93f84e-9fa3-4fad-b21a-6a5768771072', '館舍秋夕', '館舍秋夕', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["寒雨蕭蕭燈焰青，燈前孤客難爲情。","兵戈鬧日別鄉國，鴻鴈過時思弟兄。","冷極睡無離枕夢，苦多吟有徹雲聲。","出門便作還家計，直至如今計未成。"]', '["寒雨蕭蕭灯焰青，灯前孤客难爲情。","兵戈鬧日別乡国，鴻鴈過时思弟兄。","冷極睡無離枕梦，苦多吟有徹云声。","出门便作還家計，直至如今計未成。"]', '诗', 'shi', '', NULL, '館舍秋夕 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e9c1f46-dd0f-4913-b7e2-22dc9a6047c5', '送僧赴黃山沐湯泉兼參禪宗長老', '送僧赴黄山沐湯泉兼參禪宗长老', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["聞有湯泉獨去尋，一缾一鉢一無金。","不愁亂世兵相害，却喜寒山路入深。","野老禱神鴉噪廟，獵人衝雪鹿驚林。","患身是幻逢禪主，水洗皮膚語洗心。"]', '["闻有湯泉独去尋，一缾一鉢一無金。","不愁亂世兵相害，却喜寒山路入深。","野老禱神鴉噪廟，獵人衝雪鹿驚林。","患身是幻逢禪主，水洗皮膚語洗心。"]', '诗', 'shi', '', NULL, '送僧赴黃山沐湯泉兼參禪宗長老 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a40e035d-c6f5-4ec1-90f9-7093e6839754', '哭山友', '哭山友', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["十載同棲廬嶽雲，寒燒枯葉夜論文。","在生未識公卿面，至死不離麋鹿羣。","從見蓬蒿叢壞屋，長憂雨雪透荒墳。","把君詩句高聲讀，想得天高也合聞。"]', '["十載同棲廬嶽云，寒燒枯葉夜論文。","在生未識公卿面，至死不離麋鹿羣。","從见蓬蒿叢壞屋，长憂雨雪透荒墳。","把君诗句高声读，想得天高也合闻。"]', '诗', 'shi', '', NULL, '哭山友 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce31f5b8-c783-4414-8a42-38a80b22e85c', '獻池州牧', '獻池州牧', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["池陽今日似漁陽，大變凶年作小康。","江路靜來通客貨，郡城安後絕戎裝。","分開野色收新麥，驚斷鶯聲摘嫩桑。","縱有逋民歸未得，遠聞仁政旋還鄉。"]', '["池陽今日似漁陽，大变凶年作小康。","江路静来通客貨，郡城安後絕戎裝。","分开野色收新麦，驚斷鶯声摘嫩桑。","縱有逋民归未得，远闻仁政旋還乡。"]', '诗', 'shi', '', NULL, '獻池州牧 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('901264bd-279f-4dca-9746-60ef0ed6201c', '送韋書記歸京', '送韋书記归京', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["韋杜相逢眼自明，事連恩地倍牽情。","聞歸帝里愁攀送，知到師門話姓名。","朝客半修前輩禮，古人多重晚年榮。","從來有淚非無淚，未似今朝淚滿纓。"]', '["韋杜相逢眼自明，事連恩地倍牽情。","闻归帝里愁攀送，知到師门話姓名。","朝客半修前輩禮，古人多重晚年榮。","從来有泪非無泪，未似今朝泪满纓。"]', '诗', 'shi', '', NULL, '送韋書記歸京 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('755476e7-25ff-4b69-97f9-d23e47933b2d', '獻鄭給事', '獻鄭給事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["化行邦域二年春，樵唱漁歌日日新。","未降詔書酬善政，不知天澤答何人。","秋登嶽寺雲隨步，夜宴江樓月滿身。","他日朱門恐難掃，沙堤新築必無塵。"]', '["化行邦域二年春，樵唱漁歌日日新。","未降詔书酬善政，不知天澤答何人。","秋登嶽寺云隨步，夜宴江楼月满身。","他日朱门恐难掃，沙堤新築必無塵。"]', '诗', 'shi', '', NULL, '獻鄭給事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c93aef2-f707-4710-9602-c4c706941159', '贈休禪和', '贈休禪和', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["爲僧難得不爲僧，僧戒僧儀未是能。","弟子自知心了了，吾師應爲醉騰騰。","多生覺悟非關衲，一點分明不在燈。","祗道詩人無佛性，長將二雅入三乘。"]', '["爲僧难得不爲僧，僧戒僧儀未是能。","弟子自知心了了，吾師應爲醉腾腾。","多生覺悟非关衲，一点分明不在灯。","祗道诗人無佛性，长將二雅入三乘。"]', '诗', 'shi', '', NULL, '贈休禪和 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbf0b3ff-a5d9-4006-bca5-9c862f0a8132', '送李先輩從知塞上', '送李先輩從知塞上', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["去草軍書出帝鄉，便從城外學戎裝。","好隨漢將收胡土，莫遣胡兵近漢疆。","灑磧雪黏旗力重，凍河風揭角聲長。","此行也是男兒事，莫向征人恃桂香。"]', '["去草軍书出帝乡，便從城外学戎裝。","好隨漢將收胡土，莫遣胡兵近漢疆。","灑磧雪黏旗力重，凍河风揭角声长。","此行也是男兒事，莫向征人恃桂香。"]', '诗', 'shi', '', NULL, '送李先輩從知塞上 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('219c32a2-a69b-4a10-b669-1dfbee8179e9', '和友人送弟', '和友人送弟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["君說無家祗弟兄，此中言別若爲情。","干戈鬧日分頭去，山水寒時信路行。","月下斷猿空有影，雪中孤鴈却無聲。","我今骨肉雖飢凍，幸喜團圓過亂兵。"]', '["君说無家祗弟兄，此中言別若爲情。","干戈鬧日分头去，山水寒时信路行。","月下斷猿空有影，雪中孤鴈却無声。","我今骨肉雖飢凍，幸喜團圓過亂兵。"]', '诗', 'shi', '', NULL, '和友人送弟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0c76639-6c4e-4268-8e14-993b3c1f9e39', '酬張員外見寄', '酬張員外见寄', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["分應天與吟詩老，如此兵戈不廢詩。","生在世間人不識，死於泉下鬼應知。","啼花蜀鳥春同苦，叫雪巴猿晝共飢。","今日逢君惜分手，一枝何校一年遲。"]', '["分應天與吟诗老，如此兵戈不廢诗。","生在世间人不識，死於泉下鬼應知。","啼花蜀鸟春同苦，叫雪巴猿晝共飢。","今日逢君惜分手，一枝何校一年遲。"]', '诗', 'shi', '', NULL, '酬張員外見寄 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3c4d3a9-a464-4180-9e88-a3528dc138f2', '獻新安于尚書', '獻新安于尚书', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["九土雄師竟若何，未如良牧與天和。","月留清俸資家少，歲計陰功及物多。","四野綠雲籠稼穡，千山明月靜干戈。","行人耳滿新安事，盡是無愁父老歌。"]', '["九土雄師竟若何，未如良牧與天和。","月留清俸資家少，歲計陰功及物多。","四野綠云籠稼穡，千山明月静干戈。","行人耳满新安事，尽是無愁父老歌。"]', '诗', 'shi', '', NULL, '獻新安于尚書 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('464dc5bf-95c9-48a4-8777-86b1cb387a1a', '亂後書事寄同志', '亂後书事寄同志', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["九土如今盡用兵，短戈長戟困書生。","思量在世頭堪白，畫度歸山計未成。","皇澤正霑新將士，侯門不是舊公卿。","到頭詩卷須藏却，各向漁樵混姓名。"]', '["九土如今尽用兵，短戈长戟困书生。","思量在世头堪白，畫度归山計未成。","皇澤正霑新將士，侯门不是旧公卿。","到头诗卷須藏却，各向漁樵混姓名。"]', '诗', 'shi', '', NULL, '亂後書事寄同志 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('560f281d-f1a9-4d9c-acd9-3064bd77ca13', '中山臨上人院觀牡丹寄諸從事', '中山臨上人院观牡丹寄諸從事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["閑來吟遶牡丹叢，花豔人生事畧同。","半雨半風三月內，多愁多病百年中。","開當韶景何妨好，落向僧家即是空。","一境別無唯此有，忍教醒坐對支公。"]', '["闲来吟遶牡丹叢，花豔人生事畧同。","半雨半风三月內，多愁多病百年中。","开當韶景何妨好，落向僧家即是空。","一境別無唯此有，忍教醒坐对支公。"]', '诗', 'shi', '', NULL, '中山臨上人院觀牡丹寄諸從事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e4ce87e-08a8-4403-959c-a32cf569ef96', '投宣諭張侍郎亂後遇毘陵', '投宣諭張侍郎亂後遇毘陵', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["此生今日似前生，重著麻衣特地行。","經亂後囊新卷軸，出山來見舊公卿。","雨籠蛬壁吟燈影，風觸蟬枝噪浪聲。","聞道中興重人物，不妨西去馬蹄輕。"]', '["此生今日似前生，重著麻衣特地行。","經亂後囊新卷軸，出山来见旧公卿。","雨籠蛬壁吟灯影，风觸蟬枝噪浪声。","闻道中兴重人物，不妨西去马蹄轻。"]', '诗', 'shi', '', NULL, '投宣諭張侍郎亂後遇毘陵 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a43832b9-03a7-4462-bd2d-5520298165e0', '下第投所知', '下第投所知', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["落第愁生曉鼓初，地寒才薄欲何如。","不辭更寫公卿卷，却是難修骨肉書。","御苑早鶯啼暖樹，釣鄉春水浸貧居。","擬離門館東歸去，又恐重來事轉疎。"]', '["落第愁生晓鼓初，地寒才薄欲何如。","不辞更寫公卿卷，却是难修骨肉书。","御苑早鶯啼暖樹，釣乡春水浸貧居。","擬離门館东归去，又恐重来事轉疎。"]', '诗', 'shi', '', NULL, '下第投所知 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50d3711d-a019-4b13-b894-52e2389c349a', '哭方干', '哭方干', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["何言寸祿不沾身，身沒詩名萬古存。","況有數篇關教化，得無餘慶及兒孫。","漁樵共壘墳三尺，猿鶴同棲月一村。","天下未寧吾道喪，更誰將酒酹吟魂。"]', '["何言寸祿不沾身，身沒诗名万古存。","況有數篇关教化，得無餘慶及兒孫。","漁樵共壘墳三尺，猿鹤同棲月一村。","天下未寧吾道喪，更誰將酒酹吟魂。"]', '诗', 'shi', '', NULL, '哭方干 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb416a62-a7ed-48fd-86b1-ffea7d83e28f', '秋日泊浦江', '秋日泊浦江', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一帆程歇九秋時，漠漠蘆花拂浪飛。","寒浦更無船竝宿，暮山時見鳥雙歸。","照雲烽火驚離抱，剪葉風霜逼暑衣。","江月漸明汀露濕，靜驅吟魄入玄微。"]', '["一帆程歇九秋时，漠漠蘆花拂浪飞。","寒浦更無船竝宿，暮山时见鸟雙归。","照云烽火驚離抱，剪葉风霜逼暑衣。","江月漸明汀露濕，静驱吟魄入玄微。"]', '诗', 'shi', '', NULL, '秋日泊浦江 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d6bdf1c-f81b-4ca8-9cf4-cefdd597adea', '白髮吟', '白髮吟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一莖兩莖初似絲，不妨驚度少年時。","幾人亂世得及此，今我滿頭何足悲。","九轉靈丹那勝酒，五音清樂未如詩。","家山蒼翠萬餘尺，藜杖楮冠輸老兒。"]', '["一莖兩莖初似絲，不妨驚度少年时。","幾人亂世得及此，今我满头何足悲。","九轉靈丹那勝酒，五音清乐未如诗。","家山蒼翠万餘尺，藜杖楮冠輸老兒。"]', '诗', 'shi', '', NULL, '白髮吟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb7cf8d0-aa05-415b-9dd1-03e13a81fae6', '下第寄池州鄭員外', '下第寄池州鄭員外', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["省出蓬蒿修謁初，蒙知曾不見生疎。","侯門數處將書薦，帝里經年借宅居。","未必有詩堪諷誦，祗憐無援過吹噓。","如今足得成持取，莫使江湖却釣魚。"]', '["省出蓬蒿修謁初，蒙知曾不见生疎。","侯门數处將书薦，帝里經年借宅居。","未必有诗堪諷誦，祗怜無援過吹噓。","如今足得成持取，莫使江湖却釣鱼。"]', '诗', 'shi', '', NULL, '下第寄池州鄭員外 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd01992e-ed6f-47cf-a444-a05a4526e190', '塞上', '塞上', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["旌旗鬣鬣漢將軍，閑出巡邊帝命新。","沙塞旋收饒帳幕，犬戎時殺少煙塵。","冰河夜渡偷來馬，雪嶺朝飛獵去人。","獨作書生疑不穩，軟弓輕劒也隨身。"]', '["旌旗鬣鬣漢將軍，闲出巡邊帝命新。","沙塞旋收饒帳幕，犬戎时殺少煙塵。","冰河夜渡偷来马，雪嶺朝飞獵去人。","独作书生疑不穩，軟弓轻劒也隨身。"]', '诗', 'shi', '', NULL, '塞上 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31e3c174-4ac9-408d-a5cc-bc10a1a368b4', '贈題兜率寺閑上人院', '贈題兜率寺闲上人院', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["人間寺應諸天號，真行僧禪此寺中。","百歲有涯頭上雪，萬般無染耳邊風。","挂帆波浪驚心白，上馬塵埃翳眼紅。","畢竟浮生謾勞役，算來何事不成空。"]', '["人间寺應諸天號，真行僧禪此寺中。","百歲有涯头上雪，万般無染耳邊风。","挂帆波浪驚心白，上马塵埃翳眼紅。","畢竟浮生謾勞役，算来何事不成空。"]', '诗', 'shi', '', NULL, '贈題兜率寺閑上人院 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86cfbffc-313b-458a-ab3f-7facae93741c', '別四明鍾尚書', '別四明鍾尚书', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["九華天際碧嵯峨，無奈春來入夢何。","難與英雄論教化，却思猿鳥共煙蘿。","風前柳態閑時少，雨後花容淡處多。","都大人生有離別，且將詩句代離歌。"]', '["九华天際碧嵯峨，無奈春来入梦何。","难與英雄論教化，却思猿鸟共煙蘿。","风前柳態闲时少，雨後花容淡处多。","都大人生有離別，且將诗句代離歌。"]', '诗', 'shi', '', NULL, '別四明鍾尚書 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd17ef3d-98fd-4cb7-9463-6d85bea90f6e', '題護國大師塔', '題護国大師塔', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["莫認雙林是佛林，禪棲無地亦無金。","塔前盡禮灰來相，衲下誰宗印了心。","笠象胤明雙不見，線源分派寸難尋。","吾師覺路余知處，大藏經門一夜吟。"]', '["莫認雙林是佛林，禪棲無地亦無金。","塔前尽禮灰来相，衲下誰宗印了心。","笠象胤明雙不见，線源分派寸难尋。","吾師覺路余知处，大藏經门一夜吟。"]', '诗', 'shi', '', NULL, '題護國大師塔 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('123a1f14-745c-4268-bb16-b2090684c3b3', '春日山中對雪有作', '春日山中对雪有作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["竹樹無聲或有聲，霏霏漠漠散還凝。","嶺梅謝後重粧蘂，巖水鋪來却結冰。","牢繫鹿兒防獵客，滿添茶鼎候吟僧。","好將膏雨同功力，松徑莓苔又一層。"]', '["竹樹無声或有声，霏霏漠漠散還凝。","嶺梅謝後重粧蘂，巖水鋪来却結冰。","牢繫鹿兒防獵客，满添茶鼎候吟僧。","好將膏雨同功力，松徑莓苔又一層。"]', '诗', 'shi', '', NULL, '春日山中對雪有作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c84da30-f186-4766-ace6-1203bd33da0c', '山中對雪有作', '山中对雪有作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一渾乾坤萬象收，唯應不壅大江流。","虎狼遇獵難藏跡，松柏因風易舉頭。","玉帳英雄攜妓賞，山村鳥雀共民愁。","豈堪久蔽蒼蒼色，須放三光照九州。"]', '["一渾乾坤万象收，唯應不壅大江流。","虎狼遇獵难藏跡，松柏因风易舉头。","玉帳英雄携妓賞，山村鸟雀共民愁。","豈堪久蔽蒼蒼色，須放三光照九州。"]', '诗', 'shi', '', NULL, '山中對雪有作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da558545-641b-4dab-aff7-2cac070994d9', '戲題王處士書齋', '戲題王处士书斋', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["先生高興似樵漁，水鳥山猿一處居。","石徑可行苔色厚，釣竿時斫竹叢疎。","欺春祗愛和醅酒，諱老猶看夾注書。","莫道無金空有壽，有金無壽欲何如。"]', '["先生高兴似樵漁，水鸟山猿一处居。","石徑可行苔色厚，釣竿时斫竹叢疎。","欺春祗愛和醅酒，諱老猶看夾注书。","莫道無金空有壽，有金無壽欲何如。"]', '诗', 'shi', '', NULL, '戲題王處士書齋 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7196cf75-49ee-465c-b4a2-7f3e0c656b6c', '早發', '早發', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["東窗未明塵夢蘇，呼童結束登征途。","落葉鋪霜馬蹄滑，寒猿嘯月人心孤。","時逆帽簷風刮頂，旋呵鞭手凍粘鬚。","青雲快活一未見，爭得安閑釣五湖。"]', '["东窗未明塵梦蘇，呼童結束登征途。","落葉鋪霜马蹄滑，寒猿嘯月人心孤。","时逆帽簷风刮頂，旋呵鞭手凍粘鬚。","青云快活一未见，爭得安闲釣五湖。"]', '诗', 'shi', '', NULL, '早發 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d72d6db9-c7b5-4323-a028-0290b74f2ca6', '題仇處士郊居', '題仇处士郊居', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["江南景簇此林亭，手板藍裾自可輕。","洞裏客來無俗話，郭中人到有公情。","閑敲巖果呼猿接，時釣溪魚引鶴爭。","笑我有詩三百首，馬蹄紅日急於名。"]', '["江南景簇此林亭，手板藍裾自可轻。","洞裏客来無俗話，郭中人到有公情。","闲敲巖果呼猿接，时釣溪鱼引鹤爭。","笑我有诗三百首，马蹄紅日急於名。"]', '诗', 'shi', '', NULL, '題仇處士郊居 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('522c8e7e-bc9d-4973-a336-2b0f3e032202', '依韻次同年張曙先輩見寄之什', '依韻次同年張曙先輩见寄之什', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["天上詩名天下傳，引來齊列玉皇前。","大仙錄後頭無雪，至藥成來竈絕煙。","笑躡紫雲金作闕，夢拋塵世鐵爲船。","九華山叟驚凡骨，同到蓬萊豈偶然。"]', '["天上诗名天下傳，引来齊列玉皇前。","大仙錄後头無雪，至藥成来竈絕煙。","笑躡紫云金作闕，梦拋塵世鐵爲船。","九华山叟驚凡骨，同到蓬萊豈偶然。"]', '诗', 'shi', '', NULL, '依韻次同年張曙先輩見寄之什 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adffd7e8-42b9-4016-9fd0-9a78011989d3', '亂後逢李昭象敘別', '亂後逢李昭象敘別', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["李生李生何所之，家山窣雲胡不歸。","兵戈到處弄性命，禮樂向人生是非。","却與野猿同橡塢，還將溪鳥共漁磯。","也知不是男兒事，爭奈時情賤布衣。"]', '["李生李生何所之，家山窣云胡不归。","兵戈到处弄性命，禮乐向人生是非。","却與野猿同橡塢，還將溪鸟共漁磯。","也知不是男兒事，爭奈时情賤布衣。"]', '诗', 'shi', '', NULL, '亂後逢李昭象敘別 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3405ba46-baf3-455c-8227-b959638d1794', '晚春寄同年張曙先輩', '晚春寄同年張曙先輩', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["莫將時態破天真，祗合高歌醉過春。","易落好花三箇月，難留浮世百年身。","無金潤屋渾閑事，有酒扶頭是了人。","恩地未酬閑未得，一迴醒話一沾巾。"]', '["莫將时態破天真，祗合高歌醉過春。","易落好花三箇月，难留浮世百年身。","無金潤屋渾闲事，有酒扶头是了人。","恩地未酬闲未得，一迴醒話一沾巾。"]', '诗', 'shi', '', NULL, '晚春寄同年張曙先輩 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e585d3a7-dfca-488a-9ca5-5254c3ec9aab', '長安春感', '长安春感', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["出京無計住京難，深入東風轉索然。","滿眼有花寒食下，一家無信楚江邊。","此時晴景愁於雨，是處鶯聲苦却蟬。","公道算來終達去，更從今日望明年。"]', '["出京無計住京难，深入东风轉索然。","满眼有花寒食下，一家無信楚江邊。","此时晴景愁於雨，是处鶯声苦却蟬。","公道算来終達去，更從今日望明年。"]', '诗', 'shi', '', NULL, '長安春感 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc24a36e-ffe7-4e95-b4ee-08f1bb7bae85', '登靈山水閣貽釣者', '登靈山水閣貽釣者', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["江上見僧誰是了，修齋補衲日勞身。","未勝漁父閑垂釣，獨背斜陽不采人。","縱有風波猶得睡，總無蓑笠始爲貧。","瓦瓶盛酒瓷甌酌，荻浦蘆灣是要津。"]', '["江上见僧誰是了，修斋補衲日勞身。","未勝漁父闲垂釣，独背斜陽不采人。","縱有风波猶得睡，總無蓑笠始爲貧。","瓦瓶盛酒瓷甌酌，荻浦蘆灣是要津。"]', '诗', 'shi', '', NULL, '登靈山水閣貽釣者 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50276b0b-69f4-4ff9-9eb2-1326ce4e7e07', '贈溧水崔少府', '贈溧水崔少府', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["庭戶蕭條燕雀喧，日高窗下枕書眠。","祗聞留客教沽酒，未省逢人說料錢。","洞口禮星披鶴氅，溪頭吟月上漁船。","九華山叟心相許，不計官卑贈一篇。"]', '["庭戶蕭條燕雀喧，日高窗下枕书眠。","祗闻留客教沽酒，未省逢人说料錢。","洞口禮星披鹤氅，溪头吟月上漁船。","九华山叟心相許，不計官卑贈一篇。"]', '诗', 'shi', '', NULL, '贈溧水崔少府 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5675af1d-37a1-4dd0-8e7c-17cca3e32a38', '讀張僕射詩', '读張僕射诗', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["秋吟一軸見心胷，萬象搜羅詠欲空。","才大却嫌天上桂，世危翻立陣前功。","廉頗解武文無說，謝朓能文武不通。","雙美總輸張太守，二南章句六鈞弓。"]', '["秋吟一軸见心胷，万象搜羅詠欲空。","才大却嫌天上桂，世危翻立陣前功。","廉頗解武文無说，謝朓能文武不通。","雙美總輸張太守，二南章句六鈞弓。"]', '诗', 'shi', '', NULL, '讀張僕射詩 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f2074a4-b3cb-491e-b491-3104db399ae8', '題所居村舍', '題所居村舍', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["家隨兵盡屋空存，稅額寧容減一分。","衣食旋營猶可過，賦輸長急不堪聞。","蠶無夏織桑充寨，田廢春耕犢勞軍。","如此數州誰會得，殺民將盡更邀勳。"]', '["家隨兵尽屋空存，稅額寧容減一分。","衣食旋營猶可過，賦輸长急不堪闻。","蠶無夏织桑充寨，田廢春耕犢勞軍。","如此數州誰會得，殺民將尽更邀勳。"]', '诗', 'shi', '', NULL, '題所居村舍 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a3dc41c-9ddf-4592-a6e2-68467a791243', '獻錢塘縣羅著作判官', '獻錢塘縣羅著作判官', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["還鄉夫子遇賢侯，撫字情知不自由。","莫把一名專懊惱，放教雙眼絕冤讐。","猩袍懶著辭公宴，鶴氅閑披訪道流。","猶有九華知己在，羨君高臥早回頭。"]', '["還乡夫子遇賢侯，撫字情知不自由。","莫把一名專懊惱，放教雙眼絕冤讐。","猩袍懶著辞公宴，鹤氅闲披訪道流。","猶有九华知己在，羨君高臥早回头。"]', '诗', 'shi', '', NULL, '獻錢塘縣羅著作判官 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('effa4b36-9b79-4e81-9c28-a7e9eca64252', '遣懷', '遣懷', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["驅馳岐路共營營，祗爲人間利與名。","紅杏園中終擬醉，白雲山下懶歸耕。","題橋每念相如志，佩印當期季子榮。","謾道彊親堪倚賴，到頭須是有前程。"]', '["驱驰岐路共營營，祗爲人间利與名。","紅杏园中終擬醉，白云山下懶归耕。","題橋每念相如志，佩印當期季子榮。","謾道彊親堪倚賴，到头須是有前程。"]', '诗', 'shi', '', NULL, '遣懷 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fd994b0-b5d0-41b9-9259-03f292e81ebf', '長安道中有作', '长安道中有作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["回頭不忍看羸僮，一路行人我最窮。","馬跡蹇於槐影裏，釣船拋在月明中。","帽簷曉滴淋蟬露，衫袖時飄卷鴈風。","子細尋思底模樣，騰騰又過玉關東。"]', '["回头不忍看羸僮，一路行人我最窮。","马跡蹇於槐影裏，釣船拋在月明中。","帽簷晓滴淋蟬露，衫袖时飄卷鴈风。","子細尋思底模樣，腾腾又過玉关东。"]', '诗', 'shi', '', NULL, '長安道中有作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f23933d8-63a9-4ea4-8333-b72aecaf8c10', '題開元寺門閤', '題开元寺门閤', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一登高閣眺清秋，滿目風光盡勝遊。","何處畫橈尋綠水，幾家鳴笛咽紅樓。","雲山已老應長在，歲月如波祗暗流。","唯有禪居離塵俗，了無榮辱挂心頭。"]', '["一登高閣眺清秋，满目风光尽勝游。","何处畫橈尋綠水，幾家鳴笛咽紅楼。","云山已老應长在，歲月如波祗暗流。","唯有禪居離塵俗，了無榮辱挂心头。"]', '诗', 'shi', '', NULL, '題開元寺門閤 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('695b68f0-cd07-4a67-aba0-bc8e9ac293cc', '出關投孫侍御', '出关投孫侍御', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["東歸還著舊麻衣，爭免花前有淚垂。","每歲春光九十日，一生年少幾多時。","青雲寸祿心耕早，明月仙枝分種遲。","不爲感恩酬未得，五湖閑作釣魚師。"]', '["东归還著旧麻衣，爭免花前有泪垂。","每歲春光九十日，一生年少幾多时。","青云寸祿心耕早，明月仙枝分種遲。","不爲感恩酬未得，五湖闲作釣鱼師。"]', '诗', 'shi', '', NULL, '出關投孫侍御 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2a021b-82ff-4c1f-8189-cc89e1be27fd', '送項山人歸天台', '送項山人归天台', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["因話天台歸思生，布囊藤杖笑離城。","不教日月拘身事，自與煙蘿結野情。","龍鎮古潭雲色黑，露淋秋檜鶴聲清。","此中是處堪終隱，何要世人知姓名。"]', '["因話天台归思生，布囊藤杖笑離城。","不教日月拘身事，自與煙蘿結野情。","龙鎮古潭云色黑，露淋秋檜鹤声清。","此中是处堪終隐，何要世人知姓名。"]', '诗', 'shi', '', NULL, '送項山人歸天台 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77500e84-6495-4f98-8f4f-ee135285ff4e', '題衡陽隱士山居', '題衡陽隐士山居', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["閑居不問世如何，雲起山門日已斜。","放鶴去尋三島客，任人來看四時花。","松醪臘醞安神酒，布水宵煎覓句茶。","畢竟金多也頭白，算來爭得似君家。"]', '["闲居不问世如何，云起山门日已斜。","放鹤去尋三島客，任人来看四时花。","松醪臘醞安神酒，布水宵煎覓句茶。","畢竟金多也头白，算来爭得似君家。"]', '诗', 'shi', '', NULL, '題衡陽隱士山居 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c068344-02d0-47d2-94e3-ad4176161a06', '題江寺禪和', '題江寺禪和', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["江寺禪僧似悟禪，壞衣芒履住茅軒。","懶求施主修真像，翻說經文是妄言。","出浦釣船驚宿鴈，伐巖樵斧迸寒猿。","行人莫問師宗旨，眼不浮華耳不喧。"]', '["江寺禪僧似悟禪，壞衣芒履住茅軒。","懶求施主修真像，翻说經文是妄言。","出浦釣船驚宿鴈，伐巖樵斧迸寒猿。","行人莫问師宗旨，眼不浮华耳不喧。"]', '诗', 'shi', '', NULL, '題江寺禪和 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ba532f9-953e-4d49-8d9b-7885ac626693', '題弟姪書堂', '題弟姪书堂', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["何事居窮道不窮，亂時還與靜時同。","家山雖在干戈地，弟姪常修禮樂風。","窗竹影搖書案上，野泉聲入硯池中。","少年辛苦終身事，莫向光陰惰寸功。"]', '["何事居窮道不窮，亂时還與静时同。","家山雖在干戈地，弟姪常修禮乐风。","窗竹影搖书案上，野泉声入硯池中。","少年辛苦終身事，莫向光陰惰寸功。"]', '诗', 'shi', '', NULL, '題弟姪書堂 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8e5d970-11e1-430f-b6f3-00f0d375ab0c', '和友人寄長林孟明府', '和友人寄长林孟明府', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["爲政爲人漸見心，長才聊屈宰長林。","莫嫌月入無多俸，須喜秋來不廢吟。","寒雨旋疎叢菊豔，晚風時動小松陰。","訟庭閑寂公書少，留客看山索酒斟。"]', '["爲政爲人漸见心，长才聊屈宰长林。","莫嫌月入無多俸，須喜秋来不廢吟。","寒雨旋疎叢菊豔，晚风时动小松陰。","訟庭闲寂公书少，留客看山索酒斟。"]', '诗', 'shi', '', NULL, '和友人寄長林孟明府 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f96f38-d204-42b6-a4fc-d61f1564ec05', '戲贈漁家', '戲贈漁家', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["見君生計羨君閑，求食求衣有底難。","養一箔蠶供釣線，種千莖竹作漁竿。","葫蘆杓酌春濃酒，舴艋舟流夜漲灘。","却笑農家最辛苦，聽蟬鞭馬入長安。"]', '["见君生計羨君闲，求食求衣有底难。","養一箔蠶供釣線，種千莖竹作漁竿。","葫蘆杓酌春濃酒，舴艋舟流夜漲灘。","却笑農家最辛苦，听蟬鞭马入长安。"]', '诗', 'shi', '', NULL, '戲贈漁家 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6811f546-6a2f-486f-bdff-48f5985dbbdd', '登城有作', '登城有作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["上得孤城向晚春，眼前何事不傷神。","遍看原上纍纍塚，曾是城中汲汲人。","盡謂黃金堪潤屋，誰思荒骨旋成塵。","一名一宦平生事，不放愁侵易過身。"]', '["上得孤城向晚春，眼前何事不傷神。","遍看原上纍纍塚，曾是城中汲汲人。","尽謂黄金堪潤屋，誰思荒骨旋成塵。","一名一宦平生事，不放愁侵易過身。"]', '诗', 'shi', '', NULL, '登城有作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f8bdd1e-d25d-4336-bad8-8be2ae39d460', '秋日山中寄池州李常侍', '秋日山中寄池州李常侍', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["近來參謁陡生疎，因向雲山僻處居。","出爲羈孤營糲食，歸同弟姪讀生書。","風凋古木秋陰薄，月滿寒山夜景虛。","但得中興知己在，算應身未老樵漁。"]', '["近来參謁陡生疎，因向云山僻处居。","出爲羈孤營糲食，归同弟姪读生书。","风凋古木秋陰薄，月满寒山夜景虛。","但得中兴知己在，算應身未老樵漁。"]', '诗', 'shi', '', NULL, '秋日山中寄池州李常侍 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a727745-8f9b-45aa-ae55-ac55b702bd7e', '辭楊侍郎', '辞楊侍郎', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["春在門闌秋未離，不因人薦只因詩。","半年賓館成前事，一日侯門失舊知。","霜島樹凋猿叫夜，湖田穀熟鴈來時。","西風萬里東歸去，更把愁心說向誰。"]', '["春在门闌秋未離，不因人薦只因诗。","半年賓館成前事，一日侯门失旧知。","霜島樹凋猿叫夜，湖田穀熟鴈来时。","西风万里东归去，更把愁心说向誰。"]', '诗', 'shi', '', NULL, '辭楊侍郎 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('659e3169-ef7d-44e6-8a80-64d8e0ea967b', '題汪氏茅亭', '題汪氏茅亭', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["茅亭客到多稱奇，茅亭之上難題詩。","出塵景物不可狀，小手篇章徒爾爲。","牛畔稻苗新雨後，鶴邊松韻晚風時。","君今酷愛人間事，爭得安閑老在茲。"]', '["茅亭客到多稱奇，茅亭之上难題诗。","出塵景物不可狀，小手篇章徒爾爲。","牛畔稻苗新雨後，鹤邊松韻晚风时。","君今酷愛人间事，爭得安闲老在茲。"]', '诗', 'shi', '', NULL, '題汪氏茅亭 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1a6adb6-78e9-4fc5-9178-f617f0ec4d03', '喜從弟雪中遠至有作', '喜從弟雪中远至有作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["深山大雪懶開門，門逕行蹤自爾新。","無酒禦寒雖寡況，有書供讀且資身。","便均情愛同諸弟，莫更生疎似外人。","晝短夜長須強學，學成貧亦勝他貧。"]', '["深山大雪懶开门，门逕行蹤自爾新。","無酒禦寒雖寡況，有书供读且資身。","便均情愛同諸弟，莫更生疎似外人。","晝短夜长須強学，学成貧亦勝他貧。"]', '诗', 'shi', '', NULL, '喜從弟雪中遠至有作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50734116-bb9a-497a-aee8-b2e336452cfa', '送僧歸國清寺', '送僧归国清寺', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["吟送越僧歸海涯，僧行渾不覺程賒。","路沿山脚潮痕出，睡倚松根日色斜。","撼錫度岡猿抱樹，挈瓶盛浪鷺翹沙。","到參禪後知無事，看引秋泉灌藕花。"]', '["吟送越僧归海涯，僧行渾不覺程賒。","路沿山脚潮痕出，睡倚松根日色斜。","撼錫度岡猿抱樹，挈瓶盛浪鷺翹沙。","到參禪後知無事，看引秋泉灌藕花。"]', '诗', 'shi', '', NULL, '送僧歸國清寺 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7f7b63f-127d-450b-8a6f-60983091994a', '題汪明府山居', '題汪明府山居', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["不似當官祗似閑，野情終日不離山。","方知薄宦難拘束，多與高人作往還。","牛笛漫吹煙雨裏，稻苗平入水雲間。","羨君公退歸欹枕，免向他門厚客顏。"]', '["不似當官祗似闲，野情終日不離山。","方知薄宦难拘束，多與高人作往還。","牛笛漫吹煙雨裏，稻苗平入水云间。","羨君公退归欹枕，免向他门厚客顏。"]', '诗', 'shi', '', NULL, '題汪明府山居 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('245cf83d-1e26-4c1f-be2c-3468bea22734', '下第東歸將及故園有作', '下第东归將及故园有作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["平生操立有天知，何事謀身與志違。","上國獻詩還不遇，故園經亂又空歸。","山城欲暮人煙歛，江月初寒釣艇歸。","且把風寒作閑事，懶能和淚拜庭闈。"]', '["平生操立有天知，何事謀身與志違。","上国獻诗還不遇，故园經亂又空归。","山城欲暮人煙歛，江月初寒釣艇归。","且把风寒作闲事，懶能和泪拜庭闈。"]', '诗', 'shi', '', NULL, '下第東歸將及故園有作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49cbcec7-9263-4b13-aba6-5e02a3d30f67', '宿東林寺題願公院', '宿东林寺題願公院', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["古寺沈沈僧未眠，搘頤將客說閑緣。","一溪月色非塵世，滿洞松聲似雨天。","簷底水涵抄律燭，窗間風引煮茶煙。","無由住得吟相伴，心繫青雲十五年。"]', '["古寺沈沈僧未眠，搘頤將客说闲緣。","一溪月色非塵世，满洞松声似雨天。","簷底水涵抄律燭，窗间风引煮茶煙。","無由住得吟相伴，心繫青云十五年。"]', '诗', 'shi', '', NULL, '宿東林寺題願公院 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f45cf5-fdf4-4e41-a2cb-84b0c39502db', '山居自遣', '山居自遣', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["茅屋周回松竹陰，山翁時挈酒相尋。","無人開口不言利，只我白頭空愛吟。","月在釣潭秋睡重，雲橫樵逕野情深。","此中一日過一日，有底閑愁得到心。"]', '["茅屋周回松竹陰，山翁时挈酒相尋。","無人开口不言利，只我白头空愛吟。","月在釣潭秋睡重，云橫樵逕野情深。","此中一日過一日，有底闲愁得到心。"]', '诗', 'shi', '', NULL, '山居自遣 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bae4f365-d38f-4e7d-bcf5-6bf716bbdab9', '贈友人罷舉赴辟命', '贈友人罷舉赴辟命', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["連天一水浸吳東，十幅帆飛二月風。","好景採拋詩句裏，別愁驅入酒杯中。","漁依岸柳眠圓影，鳥傍嵒花戲暖紅。","不是桂枝終不得，自緣年少好從戎。"]', '["連天一水浸吳东，十幅帆飞二月风。","好景採拋诗句裏，別愁驱入酒杯中。","漁依岸柳眠圓影，鸟傍嵒花戲暖紅。","不是桂枝終不得，自緣年少好從戎。"]', '诗', 'shi', '', NULL, '贈友人罷舉赴辟命 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02e873a1-5052-4011-9e9b-f59e24b5de39', '亂後旅中遇友人', '亂後旅中遇友人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["念子爲儒道未亨，依依心向十年兄。","莫依亂世輕依託，須學前賢隱姓名。","大國未知何日靜，舊山猶可入雲耕。","不如自此同歸去，帆挂秋風一信程。"]', '["念子爲儒道未亨，依依心向十年兄。","莫依亂世轻依託，須学前賢隐姓名。","大国未知何日静，旧山猶可入云耕。","不如自此同归去，帆挂秋风一信程。"]', '诗', 'shi', '', NULL, '亂後旅中遇友人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dc69395-9fd5-4a46-9e2a-7fb865596625', '贈休糧僧', '贈休糧僧', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["自言因病學休糧，本意非求不死方。","徒有至人傳道術，更無齋客到禪房。","雨中林鳥歸巢晚，霜後嵒猨拾橡忙。","爭似吾師無一事，穩披雲衲坐藤牀。"]', '["自言因病学休糧，本意非求不死方。","徒有至人傳道術，更無斋客到禪房。","雨中林鸟归巢晚，霜後嵒猨拾橡忙。","爭似吾師無一事，穩披云衲坐藤牀。"]', '诗', 'shi', '', NULL, '贈休糧僧 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('092610c9-e27a-42db-8778-63c81c699876', '維揚春日再遇孫侍御', '維揚春日再遇孫侍御', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["本爲榮家不爲身，讀書誰料轉家貧。","三年行却千山路，兩地思歸一主人。","絡岸柳絲懸細雨，繡田花朵弄殘春。","多情御史應嗟見，未上青雲白髮新。"]', '["本爲榮家不爲身，读书誰料轉家貧。","三年行却千山路，兩地思归一主人。","絡岸柳絲懸細雨，繡田花朵弄殘春。","多情御史應嗟见，未上青云白髮新。"]', '诗', 'shi', '', NULL, '維揚春日再遇孫侍御 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('572fd0d1-9717-4015-9710-cdeb7c4e673d', '亂後宿南陵廢寺寄沈明府', '亂後宿南陵廢寺寄沈明府', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["祗共寒燈坐到明，塞鴻衝雪一聲聲。","亂時爲客無人識，廢寺吟詩有鬼驚。","且把酒杯添志氣，已將身事託公卿。","男兒仗劒酬恩在，未肯徒然過一生。"]', '["祗共寒灯坐到明，塞鴻衝雪一声声。","亂时爲客無人識，廢寺吟诗有鬼驚。","且把酒杯添志氣，已將身事託公卿。","男兒仗劒酬恩在，未肯徒然過一生。"]', '诗', 'shi', '', NULL, '亂後宿南陵廢寺寄沈明府 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26df26fc-92f0-41e8-9b67-eb36fe04afa2', '投鄭先輩', '投鄭先輩', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["匣中長劒未酬恩，不遇男兒不合論。","悶向酒杯吞日月，閑將詩句問乾坤。","寧辭馬足勞關路，肯爲漁竿憶水村。","兩鬢欲斑三百首，更教裝寫傍誰門。"]', '["匣中长劒未酬恩，不遇男兒不合論。","悶向酒杯吞日月，闲將诗句问乾坤。","寧辞马足勞关路，肯爲漁竿憶水村。","兩鬢欲斑三百首，更教裝寫傍誰门。"]', '诗', 'shi', '', NULL, '投鄭先輩 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10d6075d-503e-4883-91b5-966156361446', '途中有作', '途中有作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["無論南北與西東，名利牽人處處同。","枕上事仍多馬上，山中心更甚關中。","川原晚結陰沈氣，草樹秋生索漠風。","百歲此身如且健，大家閑作臥雲翁。"]', '["無論南北與西东，名利牽人处处同。","枕上事仍多马上，山中心更甚关中。","川原晚結陰沈氣，草樹秋生索漠风。","百歲此身如且健，大家闲作臥云翁。"]', '诗', 'shi', '', NULL, '途中有作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('483caed2-d0d4-4052-a452-5f19058ede17', '和舍弟題書堂', '和舍弟題书堂', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["兄弟將知大自強，亂時同葺讀書堂。","嵒泉遇雨多還鬧，溪竹唯風少即涼。","藉草醉吟花片落，傍山閑步藥苗香。","團圓便是家肥事，何必盈倉與滿箱。"]', '["兄弟將知大自強，亂时同葺读书堂。","嵒泉遇雨多還鬧，溪竹唯风少即涼。","藉草醉吟花片落，傍山闲步藥苗香。","團圓便是家肥事，何必盈倉與满箱。"]', '诗', 'shi', '', NULL, '和舍弟題書堂 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('581313cd-a67a-4e42-8405-24bad3c1b56f', '送蜀客遊維揚', '送蜀客游維揚', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["見說西川景物繁，維揚景物勝西川。","青春花柳樹臨水，白日綺羅人上船。","夾岸畫樓難惜醉，數橋明月不教眠。","送君嬾問君回日，才子風流正少年。"]', '["见说西川景物繁，維揚景物勝西川。","青春花柳樹臨水，白日綺羅人上船。","夾岸畫楼难惜醉，數橋明月不教眠。","送君嬾问君回日，才子风流正少年。"]', '诗', 'shi', '', NULL, '送蜀客遊維揚 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e334c10-1d22-47cc-bd8c-3a8f7b528e4c', '旅寓', '旅寓', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["暗筭鄉程隔數州，欲歸無計淚空流。","已違骨肉來時約，更束琴書何處遊。","畫角引風吹斷夢，垂楊和雨結成愁。","去年今日還如此，似與青春有舊讐。"]', '["暗筭乡程隔數州，欲归無計泪空流。","已違骨肉来时約，更束琴书何处游。","畫角引风吹斷梦，垂楊和雨結成愁。","去年今日還如此，似與青春有旧讐。"]', '诗', 'shi', '', NULL, '旅寓 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41c55f68-d3ad-495b-966a-8dc8f5aed343', '途中春', '途中春', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["年光身事旋成空，畢竟何門遇至公。","人世鶴歸雙鬢上，客程蛇遶亂山中。","牧童向日眠春草，漁父隈巖避晚風。","一醉未醒花又落，故鄉回首楚關東。"]', '["年光身事旋成空，畢竟何门遇至公。","人世鹤归雙鬢上，客程蛇遶亂山中。","牧童向日眠春草，漁父隈巖避晚风。","一醉未醒花又落，故乡回首楚关东。"]', '诗', 'shi', '', NULL, '途中春 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad847d61-66cb-4901-8dab-6dfb798048a6', '維揚冬末寄幕中二從事', '維揚冬末寄幕中二從事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["江上數株桑棗樹，自從離亂更荒涼。","那堪旅館經殘臘，祗把空書寄故鄉。","典盡客衣三尺雪，鍊精詩句一頭霜。","故人多在芙蓉幕，應笑孜孜道未光。"]', '["江上數株桑棗樹，自從離亂更荒涼。","那堪旅館經殘臘，祗把空书寄故乡。","典尽客衣三尺雪，鍊精诗句一头霜。","故人多在芙蓉幕，應笑孜孜道未光。"]', '诗', 'shi', '', NULL, '維揚冬末寄幕中二從事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d55597f5-fad7-459e-9b0a-a12e1fff6e88', '辭鄭員外入關', '辞鄭員外入关', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["男兒三十尚蹉跎，未遂青雲一桂科。","在客易爲銷歲月，到家難住似經過。","帆飛楚國風濤潤，馬度藍關雨雪多。","長把行藏信天道，不知天道竟如何。"]', '["男兒三十尚蹉跎，未遂青云一桂科。","在客易爲銷歲月，到家难住似經過。","帆飞楚国风濤潤，马度藍关雨雪多。","长把行藏信天道，不知天道竟如何。"]', '诗', 'shi', '', NULL, '辭鄭員外入關 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bed76586-a845-455c-aa6b-6d96d3a6c489', '書齋即事', '书斋即事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["時清祗合力爲儒，不可家貧與善疎。","賣却屋邊三畝地，添成窗下一牀書。","沿溪摘果霜晴後，出竹吟詩月上初。","鄉里老農多見笑，不知稽古勝耕鋤。"]', '["时清祗合力爲儒，不可家貧與善疎。","賣却屋邊三畝地，添成窗下一牀书。","沿溪摘果霜晴後，出竹吟诗月上初。","乡里老農多见笑，不知稽古勝耕鋤。"]', '诗', 'shi', '', NULL, '書齋即事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57a01fbb-f85a-415a-824e-b2210c455f3f', '雋陽道中', '雋陽道中', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["客路客路何悠悠，蟬聲向背槐花愁。","爭知百歲不百歲，未合白頭今白頭。","四五朵山妝雨色，兩三行鴈帖雲秋。","輸他江上垂綸者，祗在船中老便休。"]', '["客路客路何悠悠，蟬声向背槐花愁。","爭知百歲不百歲，未合白头今白头。","四五朵山妝雨色，兩三行鴈帖云秋。","輸他江上垂綸者，祗在船中老便休。"]', '诗', 'shi', '', NULL, '雋陽道中 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fcf54f6-1a27-4e76-a58e-a50d59055c4c', '入關因別舍弟', '入关因別舍弟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["吾今別汝汝聽言，去住人情足可安。","百口度荒均食易，數年經亂保家難。","莫愁寒族無人薦，但願春官把卷看。","天道不欺心意是，帝鄉吾土一般般。"]', '["吾今別汝汝听言，去住人情足可安。","百口度荒均食易，數年經亂保家难。","莫愁寒族無人薦，但願春官把卷看。","天道不欺心意是，帝乡吾土一般般。"]', '诗', 'shi', '', NULL, '入關因別舍弟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7ec905b-272d-4c09-a5ab-1fadb2ea9d19', '贈彭蠡釣者', '贈彭蠡釣者', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["偏坐漁舟出葦林，葦花零落向秋深。","祗將波上鷗爲侶，不把人間事繫心。","傍岸歌來風欲起，卷絲眠去月初沈。","若教我似君閑放，贏得湖山到老吟。"]', '["偏坐漁舟出葦林，葦花零落向秋深。","祗將波上鷗爲侶，不把人间事繫心。","傍岸歌来风欲起，卷絲眠去月初沈。","若教我似君闲放，贏得湖山到老吟。"]', '诗', 'shi', '', NULL, '贈彭蠡釣者 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a61ac93-4a2e-462f-953b-0ae293cb2ab7', '送友人入關', '送友人入关', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["此去青雲莫更疑，出人才行足人知。","況當朝野搜賢日，正是孤寒取士時。","仙島煙霞通鶴信，早春雷雨與龍期。","我今不得同君去，兩鬢霜欺桂一枝。"]', '["此去青云莫更疑，出人才行足人知。","況當朝野搜賢日，正是孤寒取士时。","仙島煙霞通鹤信，早春雷雨與龙期。","我今不得同君去，兩鬢霜欺桂一枝。"]', '诗', 'shi', '', NULL, '送友人入關 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a2675f1-be4d-4de3-9442-86dbc8a8b2a2', '送友人宰潯陽', '送友人宰潯陽', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["高興那言去路長，非君不解愛潯陽。","有時猨鳥來公署，到處煙霞是道鄉。","釣艇滿江魚賤菜，紙窯連嶽楮多桑。","陶潛舊隱依稀在，好繼高蹤結草堂。"]', '["高兴那言去路长，非君不解愛潯陽。","有时猨鸟来公署，到处煙霞是道乡。","釣艇满江鱼賤菜，紙窯連嶽楮多桑。","陶潛旧隐依稀在，好繼高蹤結草堂。"]', '诗', 'shi', '', NULL, '送友人宰潯陽 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48242f24-a894-4c18-bb15-f150aab6dcbd', '秋日臥病', '秋日臥病', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["浮世浮名能幾何，致身流落向天涯。","少年心壯輕爲客，一日病來思在家。","山頂老猨啼古木，渡頭新鴈下平沙。","不堪吟罷西風起，黃葉滿庭寒日斜。"]', '["浮世浮名能幾何，致身流落向天涯。","少年心壯轻爲客，一日病来思在家。","山頂老猨啼古木，渡头新鴈下平沙。","不堪吟罷西风起，黄葉满庭寒日斜。"]', '诗', 'shi', '', NULL, '秋日臥病 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('515e884a-6fe0-4919-81a9-ac1725a8b490', '敘吟', '敘吟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["多慙到處有詩名，轉覺吟詩僻性成。","度水却嫌船著岸，過山翻恨馬貪程。","如讐雪月年年景，似夢笙歌處處聲。","未合白頭今已白，自知非爲別愁生。"]', '["多慙到处有诗名，轉覺吟诗僻性成。","度水却嫌船著岸，過山翻恨马貪程。","如讐雪月年年景，似梦笙歌处处声。","未合白头今已白，自知非爲別愁生。"]', '诗', 'shi', '', NULL, '敘吟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59b6a8a9-11bf-4970-80a6-908d0a1c5220', '行次滎陽却寄諸弟', '行次滎陽却寄諸弟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["難把歸書說遠情，奉親多闕拙爲兄。","早知寸祿榮家晚，悔不深山共汝耕。","枕上算程關月落，帽前搜景嶽雲生。","如今已作長安計，祗得辛勤取一名。"]', '["难把归书说远情，奉親多闕拙爲兄。","早知寸祿榮家晚，悔不深山共汝耕。","枕上算程关月落，帽前搜景嶽云生。","如今已作长安計，祗得辛勤取一名。"]', '诗', 'shi', '', NULL, '行次滎陽却寄諸弟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4692469a-f711-4707-ab80-f315da4a1280', '登石壁禪師水閣有作', '登石壁禪師水閣有作', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["石壁早聞僧說好，今來偏與我相宜。","有山有水堪吟處，無雨無風見景時。","漁父晚船分浦釣，牧童寒笛倚牛吹。","畫人畫得從他畫，六幅應輸八句詩。"]', '["石壁早闻僧说好，今来偏與我相宜。","有山有水堪吟处，無雨無风见景时。","漁父晚船分浦釣，牧童寒笛倚牛吹。","畫人畫得從他畫，六幅應輸八句诗。"]', '诗', 'shi', '', NULL, '登石壁禪師水閣有作 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a8ed98-3334-4145-aa6e-405db50b38bc', '贈袒肩和尚', '贈袒肩和尚', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["山衣草屐染莓苔，雙眼猶慵向俗開。","若比吾師居世上，何如野客臥嵒隈。","才聞錫杖離三楚，又說隨緣向五臺。","乘醉吟詩問禪理，爲誰須去爲誰來。"]', '["山衣草屐染莓苔，雙眼猶慵向俗开。","若比吾師居世上，何如野客臥嵒隈。","才闻錫杖離三楚，又说隨緣向五台。","乘醉吟诗问禪理，爲誰須去爲誰来。"]', '诗', 'shi', '', NULL, '贈袒肩和尚 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08346b38-91b9-4807-980d-3695f7b636eb', '閑居即事', '闲居即事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["形覺清羸道覺肥，竹門前徑靜相宜。","一壺村酒無求處，數朵庭花見落時。","章句偶爲前輩許，話言多被俗人疑。","一枝仙桂如攀得，祗此山前是老期。"]', '["形覺清羸道覺肥，竹门前徑静相宜。","一壺村酒無求处，數朵庭花见落时。","章句偶爲前輩許，話言多被俗人疑。","一枝仙桂如攀得，祗此山前是老期。"]', '诗', 'shi', '', NULL, '閑居即事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7469d1af-167b-41af-abc3-eddb8596bf16', '自敘', '自敘', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["酒甕琴書伴病身，熟諳時事樂於貧。","寧爲宇宙閑吟客，怕作乾坤竊祿人。","詩旨未能忘救物，世情奈值不容真。","平生肺腑無言處，白髮吾唐一逸人。"]', '["酒甕琴书伴病身，熟諳时事乐於貧。","寧爲宇宙闲吟客，怕作乾坤竊祿人。","诗旨未能忘救物，世情奈值不容真。","平生肺腑無言处，白髮吾唐一逸人。"]', '诗', 'shi', '', NULL, '自敘 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f98526e-d0e0-41c1-a42b-13cac9ed79e0', '空閑二公遞以禪律相鄙因而解之', '空闲二公遞以禪律相鄙因而解之', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一教誰云闢二途，律禪禪律智歸愚。","念珠在手隳禪衲，禪衲披肩壞念珠。","象外空分空外象，無中有作有中無。","有無無有師窮取，山到平來海亦枯。"]', '["一教誰云闢二途，律禪禪律智归愚。","念珠在手隳禪衲，禪衲披肩壞念珠。","象外空分空外象，無中有作有中無。","有無無有師窮取，山到平来海亦枯。"]', '诗', 'shi', '', NULL, '空閑二公遞以禪律相鄙因而解之 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5cac4e1-2599-4ee6-8409-43026970d22b', '寄溫州朱尚書幷呈軍倅崔太傅', '寄溫州朱尚书幷呈軍倅崔太傅', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["永嘉名郡昔推名，連屬荀家弟與兄。","教化靜師龔渤海，篇章高體謝宣城。","山從海岸妝吟景，水自城根演政聲。","今日老輸崔博士，不妨疎逸伴雙旌。"]', '["永嘉名郡昔推名，連屬荀家弟與兄。","教化静師龔渤海，篇章高體謝宣城。","山從海岸妝吟景，水自城根演政声。","今日老輸崔博士，不妨疎逸伴雙旌。"]', '诗', 'shi', '', NULL, '寄溫州朱尚書幷呈軍倅崔太傅 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4d9db46-0b2d-4ae8-928a-5ce636298763', '恩門致書遠及山居因獻之', '恩门致书远及山居因獻之', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["時難轉覺保身難，難向師門欲繼顏。","若把白衣輕易脫，却成青桂偶然攀。","身居劒戟爭雄地，道在乾坤未喪間。","必許酬恩酬未晚，且須容到九華山。"]', '["时难轉覺保身难，难向師门欲繼顏。","若把白衣轻易脫，却成青桂偶然攀。","身居劒戟爭雄地，道在乾坤未喪间。","必許酬恩酬未晚，且須容到九华山。"]', '诗', 'shi', '', NULL, '恩門致書遠及山居因獻之 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e136415d-62b4-4912-a5b0-b858bb91f8ab', '寄溫州崔博士', '寄溫州崔博士', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["懷君勞我寫詩情，窣窣陰風有鬼聽。","縣宰不仁工部餓，酒家無識翰林醒。","眼昏經史天何在，心盡英雄國未寧。","好向賢侯話吟侶，莫教辜負少微星。"]', '["懷君勞我寫诗情，窣窣陰风有鬼听。","縣宰不仁工部餓，酒家無識翰林醒。","眼昏經史天何在，心尽英雄国未寧。","好向賢侯話吟侶，莫教辜負少微星。"]', '诗', 'shi', '', NULL, '寄溫州崔博士 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dc66959-5056-440f-9810-a15c3f4448cc', '李昭象云與二三同人見訪有寄', '李昭象云與二三同人见訪有寄', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["得君書後病顏開，云拉同人訪我來。","在路不妨衝雨雪，到山還免踏塵埃。","吟沈水閣何宵月，坐破松巖幾處苔。","貧舍款賓無別物，止於空戰大尊罍。"]', '["得君书後病顏开，云拉同人訪我来。","在路不妨衝雨雪，到山還免踏塵埃。","吟沈水閣何宵月，坐破松巖幾处苔。","貧舍款賓無別物，止於空戰大尊罍。"]', '诗', 'shi', '', NULL, '李昭象云與二三同人見訪有寄 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a5a4c58-11f3-4cbd-af80-5dbebf7a9016', '自江西歸九華', '自江西归九华', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["他鄉終日憶吾鄉，及到吾鄉值亂荒。","雲外好山看不見，馬頭歧路去何忙。","無衣織女桑猶小，闕食農夫麥未黃。","許大乾坤吟未了，揮鞭回首出陵陽。"]', '["他乡終日憶吾乡，及到吾乡值亂荒。","云外好山看不见，马头歧路去何忙。","無衣织女桑猶小，闕食農夫麦未黄。","許大乾坤吟未了，揮鞭回首出陵陽。"]', '诗', 'shi', '', NULL, '自江西歸九華 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e984b06-dfc7-4d20-8afe-e91ae02ab932', '和友人見題山居水閣八韻', '和友人见題山居水閣八韻', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["池閣初成眼豁開，眼前霽景屬微才。","試攀簷果猨先見，纔把漁竿鶴即來。","修竹已多猶可種，豔花雖少不勞栽。","南昌一榻延徐孺，楚國千鍾逼老萊。","未稱執鞭奔紫陌，惟宜策杖步蒼苔。","籠禽豈是摩霄翼，潤木元非澗下材。","鑒己每將天作鏡，陶情常以海爲杯。","和君詩句吟聲大，蟲豸聞之謂蟄雷。"]', '["池閣初成眼豁开，眼前霽景屬微才。","試攀簷果猨先见，纔把漁竿鹤即来。","修竹已多猶可種，豔花雖少不勞栽。","南昌一榻延徐孺，楚国千鍾逼老萊。","未稱執鞭奔紫陌，惟宜策杖步蒼苔。","籠禽豈是摩霄翼，潤木元非澗下材。","鑒己每將天作镜，陶情常以海爲杯。","和君诗句吟声大，蟲豸闻之謂蟄雷。"]', '诗', 'shi', '', NULL, '和友人見題山居水閣八韻 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69cb80d3-e99c-4cbe-9247-127a06766fef', '感寓', '感寓', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["大海波濤淺，小人方寸深。","海枯終見底，人死不知心。"]', '["大海波濤淺，小人方寸深。","海枯終见底，人死不知心。"]', '诗', 'shi', '', NULL, '感寓 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66dba053-99b0-4bbe-b793-96e76e53bea9', '春閨怨', '春閨怨', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["朝喜花豔春，暮悲花委塵。","不悲花落早，悲妾似花身。"]', '["朝喜花豔春，暮悲花委塵。","不悲花落早，悲妾似花身。"]', '诗', 'shi', '', NULL, '春閨怨 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e626ff19-7f8a-4613-947e-2b327faba257', '馬上行', '马上行', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["五里復五里，去時無住時。","日將家漸遠，猶恨馬行遲。"]', '["五里复五里，去时無住时。","日將家漸远，猶恨马行遲。"]', '诗', 'shi', '', NULL, '馬上行 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f01a63c0-533e-4060-b10f-1c0e5b40b465', '釣叟', '釣叟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["茅屋深灣裏，釣船橫竹門。","經營衣食外，猶得弄兒孫。"]', '["茅屋深灣裏，釣船橫竹门。","經營衣食外，猶得弄兒孫。"]', '诗', 'shi', '', NULL, '釣叟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90909ca8-cc8f-46ed-a957-e3f46a038640', '再經胡城縣', '再經胡城縣', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["去歲曾經此縣城，縣民無口不冤聲。","今來縣宰加朱紱，便是生靈血染成。"]', '["去歲曾經此縣城，縣民無口不冤声。","今来縣宰加朱紱，便是生靈血染成。"]', '诗', 'shi', '', NULL, '再經胡城縣 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28ad4845-cccc-46d5-98f1-f8f3d931bc1c', '讀諸家詩', '读諸家诗', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["辭賦文章能者稀，難中難者莫過詩。","直應吟骨無生死，祗我前身是阿誰。"]', '["辞賦文章能者稀，难中难者莫過诗。","直應吟骨無生死，祗我前身是阿誰。"]', '诗', 'shi', '', NULL, '讀諸家詩 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('741b4d85-9368-45f5-aef3-c4443e822ec2', '春來燕', '春来燕', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["我屋汝嫌低不住，雕梁畫閣也知寬。","大須穩擇安巢處，莫道巢成却不安。"]', '["我屋汝嫌低不住，雕梁畫閣也知寬。","大須穩擇安巢处，莫道巢成却不安。"]', '诗', 'shi', '', NULL, '春來燕 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17d9c123-e0c6-4d1d-8271-27b233f84f8f', '清溪來明府出二子請詩因遺一絕', '清溪来明府出二子請诗因遺一絕', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["珠明玉潤盡驚人，不稱寒門不稱貧。","若向吾唐作雙瑞，便同祥鳳與祥麟。"]', '["珠明玉潤尽驚人，不稱寒门不稱貧。","若向吾唐作雙瑞，便同祥鳳與祥麟。"]', '诗', 'shi', '', NULL, '清溪來明府出二子請詩因遺一絕 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac39de3d-058c-41bb-8198-8e3d71cdb5f3', '哭陳陶', '哭陳陶', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["耒陽山下傷工部，采石江邊弔翰林。","兩地荒墳各三尺，却成開解哭君心。"]', '["耒陽山下傷工部，采石江邊弔翰林。","兩地荒墳各三尺，却成开解哭君心。"]', '诗', 'shi', '', NULL, '哭陳陶 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ceb248e-be94-4408-891d-0cebb51f1994', '哭貝韜', '哭貝韜', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["交朋來哭我來歌，喜傍山家葬荔蘿。","四海十年人殺盡，似君埋少不埋多。"]', '["交朋来哭我来歌，喜傍山家葬荔蘿。","四海十年人殺尽，似君埋少不埋多。"]', '诗', 'shi', '', NULL, '哭貝韜 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a42a500-d24a-4e44-9504-dda41d890b42', '蠶婦', '蠶婦', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["粉色全無飢色加，豈知人世有榮華。","年年道我蠶辛苦，底事渾身着苧麻。"]', '["粉色全無飢色加，豈知人世有榮华。","年年道我蠶辛苦，底事渾身着苧麻。"]', '诗', 'shi', '', NULL, '蠶婦 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4380c071-6a60-4097-bb05-4740593e57b9', '山寺老僧', '山寺老僧', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["草靸無塵心地閑，靜隨猿鳥過寒暄。","眼昏齒落看經遍，却向僧中總不言。"]', '["草靸無塵心地闲，静隨猿鸟過寒暄。","眼昏齒落看經遍，却向僧中總不言。"]', '诗', 'shi', '', NULL, '山寺老僧 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde7e297-13d9-4606-b002-18035d482cac', '閩中秋思', '閩中秋思', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["雨勻紫菊叢叢色，風弄紅蕉葉葉聲。","北畔是山南畔海，祗堪圖畫不堪行。"]', '["雨勻紫菊叢叢色，风弄紅蕉葉葉声。","北畔是山南畔海，祗堪圖畫不堪行。"]', '诗', 'shi', '', NULL, '閩中秋思 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d40d1b44-ef68-4070-8cc4-a7a7c08c8ef7', '八駿圖', '八駿圖', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["丹雘傳真未得真，那知筋骨與精神。","祗今恃駿憑毛色，綠耳驊騮賺殺人。"]', '["丹雘傳真未得真，那知筋骨與精神。","祗今恃駿憑毛色，綠耳驊騮賺殺人。"]', '诗', 'shi', '', NULL, '八駿圖 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abd386e7-8775-4570-bf2b-980d94c3754d', '贈僧', '贈僧', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["利門名路兩何憑，百歲風前短焰燈。","祗恐爲僧僧不了，爲僧得了總輸僧。"]', '["利门名路兩何憑，百歲风前短焰灯。","祗恐爲僧僧不了，爲僧得了總輸僧。"]', '诗', 'shi', '', NULL, '贈僧 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7398c0a8-32e9-4e88-8f9f-a04d7691a889', '秋夕', '秋夕', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["世間多少能詩客，誰是無愁得睡人。","自我夜來霜月下，到頭吟魄始終身。"]', '["世间多少能诗客，誰是無愁得睡人。","自我夜来霜月下，到头吟魄始終身。"]', '诗', 'shi', '', NULL, '秋夕 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('030c5b3a-c6c1-4aa9-83e3-134d1afb40f4', '溪興', '溪兴', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["山雨溪風卷釣絲，瓦甌篷底獨斟時。","醉來睡着無人喚，流下前溪也不知。"]', '["山雨溪风卷釣絲，瓦甌篷底独斟时。","醉来睡着無人喚，流下前溪也不知。"]', '诗', 'shi', '', NULL, '溪興 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3507c4e-c1f1-4236-afb7-5b2b3e035003', '過巢湖', '過巢湖', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["世人貪利復貪榮，來向湖邊始至誠。","男子登舟與登陸，把心何不一般行。"]', '["世人貪利复貪榮，来向湖邊始至誠。","男子登舟與登陸，把心何不一般行。"]', '诗', 'shi', '', NULL, '過巢湖 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89fce731-7332-4d99-b3fa-e217173fb677', '傷硤石縣病叟', '傷硤石縣病叟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["無子無孫一病翁，將何筋力事耕農。","官家不管蓬蒿地，須勒王租出此中。"]', '["無子無孫一病翁，將何筋力事耕農。","官家不管蓬蒿地，須勒王租出此中。"]', '诗', 'shi', '', NULL, '傷硤石縣病叟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e2072af-1025-484a-85f7-3113c035928c', '贈老僧', '贈老僧', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["童子爲僧今白首，暗鋤心地種閑情。","時將舊衲添新線，披坐披行過一生。"]', '["童子爲僧今白首，暗鋤心地種闲情。","时將旧衲添新線，披坐披行過一生。"]', '诗', 'shi', '', NULL, '贈老僧 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9075579-94ee-4a22-9e90-c5191e89ef9b', '釣叟', '釣叟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["田不曾耕地不鋤，誰人閑散得如渠。","渠將底物爲香餌，一度擡竿一箇魚。"]', '["田不曾耕地不鋤，誰人闲散得如渠。","渠將底物爲香餌，一度擡竿一箇鱼。"]', '诗', 'shi', '', NULL, '釣叟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('228ca668-391c-40a4-9919-d6d6df8243e0', '溪岸秋思', '溪岸秋思', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["桑柘窮頭三四家，挂罾垂釣是生涯。","秋風忽起溪灘白，零落岸邊蘆荻花。"]', '["桑柘窮头三四家，挂罾垂釣是生涯。","秋风忽起溪灘白，零落岸邊蘆荻花。"]', '诗', 'shi', '', NULL, '溪岸秋思 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f2929f2-66cb-495a-9fad-be3e6d71bea0', '春日旅寓', '春日旅寓', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["滿城羅綺拖春色，幾處笙歌揭畫樓。","江上有家歸未得，眼前花是眼前愁。"]', '["满城羅綺拖春色，幾处笙歌揭畫楼。","江上有家归未得，眼前花是眼前愁。"]', '诗', 'shi', '', NULL, '春日旅寓 杜荀鶴 shi');
